package com.example.data.local

object DuaDatabaseSeeder {
    fun getSeedDuas(): List<DuaEntity> {
        return listOf(
            // Morning & Evening Supplications
            DuaEntity(
                id = 1,
                category = "Morning & Evening",
                title = "Virtue of Dhikr",
                arabic = "فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ، يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا. وَقَالَ ﷺ: مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ",
                transliteration = "Fadhkuruni adhkurkum washkuru li wa la takfurun, ya ayyuhalladhina amanu-dhkurullaha dhikran kathiran wa sabbihuhu bukratan wa asila. Wa qala (SAW): Mathalulladhi yadhkuru Rabbahu walladhi la yadhkuru Rabbahu mathalul-hayyi wal-mayyit.",
                translation = "Therefore remember Me, I will remember you; and be grateful to Me, and do not disbelieve in Me. O you who believe! Remember Allah with much remembrance, and glorify Him morning and evening. And the Prophet (ﷺ) said: 'The example of the one who remembers his Lord and the one who does not is like that of the living and the dead.'",
                translationHausa = "Saboda haka ku ambace Ni, Zan ambace ku; kuma ku gode Mini, kada ku kafirce Mini. Ya ku waɗanda kuka yi imani! Ku ambaci Allah ambato mai yawa, kuma ku yi tasbihi gare Shi da safe da yamma. Kuma Annabi (SAW) ya ce: 'Kwatancin wanda yake ambaton Ubangijinsa da wanda ba ya ambaton Ubangijinsa, kamar kwatancin mai rai ne da matacce.'",
                translationYoruba = "Tẹsiwaju lati ranti Mi, Emi yoo ranti yin. Ẹ si dupe fun Mi, ẹ ma ṣe ṣaipẹ fun Mi. Ẹyin ti ẹ gbagbọ! Ẹ ranti Allāhu pẹlu iranti ti o pọ̀, ki ẹ si ṣe afọmọ fun Un ni owurọ ati irọlẹ. Kuma Ojisẹ Allāhu (SAW) sọ pe: 'Àpẹẹrẹ ẹni ti n ranti Olúwa rẹ̀ ati ẹni ti kò ranti Olúwa rẹ̀ dabi àpẹẹrẹ alààyè ati òkú.'",
                translationIgbo = "Cheta m ka m cheta gị. Nwee ekele n'ebe m nọ ma ghara ịgọnarị m. Ndị kweere! Chetanụ Chineke site n'ọtụtụ ncheta, ma na-eto Ya n'ụtụtụ na n'anyasị. Onye Ozi Chineke (SAW) sịkwara: 'Ihe atụ nke onye na-echeta Onyenwe ya na onye na-adịghị echeta Onyenwe ya dị ka ihe atụ nke onye dị ndụ na onye nwụrụ anwụ.'",
                reference = "Surah Al-Baqarah 2:152, Surah Al-Ahzab 33:41-42, Sahih Al-Bukhari 11/208, Sahih Muslim 1/539. Hisnul Muslim Chapter 1."
            ),
            DuaEntity(
                id = 2,
                category = "Morning & Evening",
                title = "Sayyidul Istighfar (Master Forgiveness)",
                arabic = "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ",
                transliteration = "Allahumma anta Rabbi la ilaha illa Anta, khalaqtani wa ana 'abduka, wa ana 'ala 'ahdika wa wa'dika mastata'tu, a'udhu bika min sharri ma sana'tu, abu'u laka bini'matika 'alayya, wa abu'u bidhanbi faghfir li fa'innahu la yaghfiru-dhunuba illa Anta.",
                translation = "O Allah, You are my Lord, there is none worthy of worship but You. You created me and I am your slave. I keep Your covenant, and my pledge to You so far as I am able. I seek refuge in You from the evil of what I have done. I admit to Your grace upon me, and I admit to my sin. So forgive me, for surely none can forgive sins but You.",
                translationHausa = "Ya Allah, Kai ne Ubangijina, babu abin bautawa da gaskiya sai Kai. Ka halitta ni kuma ni bawanKa ne. Ina kan alkawarinKa da wa'adinKa gwargwadon ikona. Ina neman tsari da Kai daga sharrin abin da na aikata. Ina amsa muku ni'imarKa a kaina, kuma ina amsa zunubina. Don haka Ka gafarta mini, domin babu mai gafarta zunubai sai Kai.",
                translationYoruba = "Allāhu n bẹ, Iwọ ni Ọlọrun mi, ko si ọba miran ti a gbọdọ jọsin fun afi Iwọ. Iwọ lo da mi, emi si ni ẹru Rẹ. Mo duro lori adehun Rẹ ati ileri Rẹ gẹgẹ bi agbara mi ti mọ. Mo tọrọ isadi lọdọ Rẹ lọwọ aburu ohun ti mo ṣe. Mo jẹwọ awọn ikẹ Rẹ lori mi, mo si jẹwọ ẹṣẹ mi. Nitori naa, rọ mi lẹṣẹ ji, nitori ko si ẹni ti n rọ ẹṣẹ ji afi Iwọ.",
                translationIgbo = "Chineke, Gị bụ Onyenwe m, ọ dịghị onye kwesịrị ofufe ma ọ bụghị Gị. Gị kere m, mụ onwe m bụkwa ohu Gị. Adị m n'elu nkwekọrịta Gị na nkwa Gị dịka ike m siri gaa. Ana m achọ ebe mgbaba n'aka Gị pụọ n'ihe ọjọọ niile m mere. Ana m ekwupụta amara Gị n'ebe m nọ, ana m ekwupụtakwa mmehie m. Ya mere meere m ebere gbaghara m, n'ihi na ọ dịghị onye ọzọ nwere ike ịgbaghara mmehie ma ọ bụghị Gị.",
                reference = "Whoever says this during the day with firm belief in it and dies will be from the people of Paradise.\nReference: Al-Bukhari 7/150."
            ),
            DuaEntity(
                id = 3,
                category = "Morning & Evening",
                title = "Protection from Harm (Recite 3 times)",
                arabic = "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ",
                transliteration = "Bismillahil-ladhi la yadurru ma'as-mihi shay'un fil-ardi wa la fis-sama'i wa Huwas-Sami'ul-'Alim.",
                translation = "In the Name of Allah, Who with His Name nothing can cause harm in the earth nor in the heavens, and He is the All-Hearing, the All-Knowing.",
                translationHausa = "Da sunan Allah wanda babu abin da ke cutarwa tare da sunanSa a kasa ko a sama, kuma Shi ne Mai ji, Masani.",
                translationYoruba = "Pẹlu orukọ Allāhu ti nkan kankan ko le pa lara pẹlu orukọ Rẹ ni ilẹ ati ni oju sanma, Kuma on ni Olugbọ, Onimọ.",
                translationIgbo = "N'aha Chineke, Onye na-enweghị ihe ọ bụla nwere ike imerụ ahụ n'ụwa ma ọ bụ n'eluigwe site n'aha Ya, ma Ya onwe Ya bụ Onye Na-anụ ihe, Onye Maara ihe niile.",
                reference = "Recited 3 times morning and evening for complete protection from sudden calamities.\nReference: Abu Dawud 4/323, At-Tirmidhi 5/465."
            ),
            DuaEntity(
                id = 4,
                category = "Morning & Evening",
                title = "Satisfaction with Islam & Allah (Recite 3 times)",
                arabic = "رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلَامِ دِيناً، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيَّاً",
                transliteration = "Raditu billahi Rabban, wa bil-Islami dinan, wa bi-Muhammadin (sallallahu 'alayhi wa sallam) Nabiyya.",
                translation = "I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace and blessings of Allah be upon him) as my Prophet.",
                translationHausa = "Na yarda da Allah a matsayin Ubangiji, da Musulunci a matsayin addini, da Muhammad (tsira da amincin Allah su tabbata a gare shi) a matsayin Annabi.",
                translationYoruba = "Mo gba Allāhu gbọ gẹgẹ bi Ọlọrun mi, ati Ẹsin Islam gẹgẹ bi ẹsin mi, ati Muhammad (ki ikẹ ati ọla Allāhu ma ba a) gẹgẹ bi Ojisẹ nla.",
                translationIgbo = "Enwere m obi ụtọ na m nwere Chineke dị ka Onyenwe m, na Islam dị ka okpukpe m, na Muhammad dị ka Onye Amụma m.",
                reference = "Abu Dawud 4/318, At-Tirmidhi 5/465."
            ),

            // Sleeping & Waking Up
            DuaEntity(
                id = 5,
                category = "Sleeping & Waking Up",
                title = "Before Sleeping",
                arabic = "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا",
                transliteration = "Bismika-llahumma amutu wa ahya.",
                translation = "In Your Name, O Allah, I die and I live.",
                translationHausa = "Da sunanKa ya Allah nake mutuwa kuma nake rayuwa.",
                translationYoruba = "Pẹlu orukọ Rẹ Allāhu ni mo n ku ti mo si n di alaaye.",
                translationIgbo = "N'aha Gị Chineke ka m na-anwụ ma na-adị ndụ.",
                reference = "Al-Bukhari (Fathul-Bari 11/113), Muslim 4/2083."
            ),
            DuaEntity(
                id = 6,
                category = "Sleeping & Waking Up",
                title = "Upon Waking Up",
                arabic = "الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ",
                transliteration = "Alhamdu lillahil-ladhi 'afani fi jasadi, wa radda 'alayya ruhi, wa adhina li bidhikrih.",
                translation = "Praise is to Allah Who gave strength to my body and returned my soul to me and permitted me to remember Him.",
                translationHausa = "Godiya ta tabbata ga Allah wanda Ya ba wa jikina lafiya, Ya mayar mini da raina, kuma Ya ba ni izinin ambatonSa.",
                translationYoruba = "Ọpẹ ni fun Allāhu ti o fun ara mi ni ilera, ti o si da ẹmi mi pada fun mi, ti o si gba mi laaye lati ranti Rẹ.",
                translationIgbo = "Otuto dịrị Chineke Onye nyere ahụ m ume na ike, weghachiri mkpụrụ obi m n'ime m ma kwe ka m cheta aha Ya.",
                reference = "At-Tirmidhi 5/473."
            ),

            // Prayers & Mosque
            DuaEntity(
                id = 7,
                category = "Prayers & Mosque",
                title = "Entering the Mosque",
                arabic = "أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ",
                transliteration = "A'udhu billahil-'Azim, wa bi-Wajhihil-Karim, wa Sultanihil-Qadim, minash-Shaytanir-Rajim.",
                translation = "I seek refuge in Almighty Allah, by His Noble Face, by His primordial power, from Satan the outcast.",
                translationHausa = "Ina neman tsari da Allah Mai girma, da fuskarSa mai daraja, da mulkinSa na dindindin, daga Shaidan jifaffe.",
                translationYoruba = "Mo wa isadi pẹlu Allāhu t’O tobi, ati oju Rẹ t’O ni ọla, ati agbara Rẹ t’O ti wa tipẹ, lọwọ satani ẹni-egbe.",
                translationIgbo = "Ana m achọ ebe mgbaba n'aka Chineke Onye Pụrụ Ime Ihe Niile, site n'Ihu Ọma Ya, na Ike Ya ebighi ebi, pụọ n'aka Setan onye a chụpụrụ achụpụ.",
                reference = "Abu Dawud 1/127."
            ),
            DuaEntity(
                id = 8,
                category = "Prayers & Mosque",
                title = "Leaving the Mosque",
                arabic = "اللَّهُمَّ إِنِّي أَسْتَلُكَ مِنْ فَضْلِكَ",
                transliteration = "Allahumma inni as'aluka min fadlik.",
                translation = "O Allah, I ask You of Your bounty.",
                translationHausa = "Ya Allah, lallai ina rokonKa daga cikin falalarKa.",
                translationYoruba = "Allāhu, mo bọ lọwọ Rẹ lati fun mi ni ninu awọn oore-ọfẹ Rẹ.",
                translationIgbo = "Chineke, ana m arịọ Gị amara na ngọzi Gị.",
                reference = "Muslim 1/494."
            ),

            // Eating & Drinking
            DuaEntity(
                id = 10,
                category = "Eating & Drinking",
                title = "Before Eating",
                arabic = "بِسْمِ اللَّهِ",
                transliteration = "Bismillah.",
                translation = "In the Name of Allah.",
                translationHausa = "Da sunan Allah.",
                translationYoruba = "Pẹlu orukọ Allāhu.",
                translationIgbo = "N'aha Chineke.",
                reference = "Abu Dawud 3/347, At-Tirmidhi 4/288."
            ),
            DuaEntity(
                id = 11,
                category = "Eating & Drinking",
                title = "If forgotten before eating",
                arabic = "بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ",
                transliteration = "Bismillahi fi awwalihi wa akhirih.",
                translation = "In the Name of Allah, in the beginning and in the end.",
                translationHausa = "Da sunan Allah a farkonsa da karshensa.",
                translationYoruba = "Pẹlu orukọ Allāhu ni ibẹrẹ rẹ ati ni opin rẹ.",
                translationIgbo = "N'aha Chineke na mmalite ya na njedebe ya.",
                reference = "Abu Dawud 3/347, At-Tirmidhi 4/288."
            ),
            DuaEntity(
                id = 12,
                category = "Eating & Drinking",
                title = "After Eating",
                arabic = "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ",
                transliteration = "Alhamdu lillahil-ladhi at'amani hadha wa razaqanihi min ghayri hawlin minni wa la quwwah.",
                translation = "Praise is to Allah Who has fed me this and provided it for me without any might or power on my part.",
                translationHausa = "Godiya ta tabbata ga Allah wanda Ya ciyar da ni wannan kuma Ya arzuta ni da shi ba tare da wata dabara tawa ko iko nawa ba.",
                translationYoruba = "Ọpẹ ni fun Allāhu ti o fún mi ni oúnjẹ yí jẹ, ti o si pese rẹ fun mi laisi agbara tabi okun kankan lati ọdọ mi.",
                translationIgbo = "Otuto dịrị Chineke Onye nyere m nri a ma nye m ya n'enweghị mbọ m gbara ma ọ bụ ike m siri n'aka m.",
                reference = "At-Tirmidhi, Abu Dawud, Ibn Majah."
            ),

            // Travel & Home
            DuaEntity(
                id = 13,
                category = "Eating & Drinking",
                title = "Dua for the Host",
                arabic = "اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ",
                transliteration = "Allahumma barik lahum fima razaqtahum, waghfirlahum warhamhum.",
                translation = "O Allah, bless for them that which You have provided them, forgive them and have mercy upon them.",
                translationHausa = "Ya Allah, Ka yi musu albarka a cikin abin da Ka arzuta su da shi, kuma Ka gafarta musu kuma Ka ji kansu.",
                translationYoruba = "Allāhu, ṣe ibukun fun wọn ninu ohun ti O pese fun wọn, rọ wọn lẹṣẹ ji ki O si ke wọn.",
                translationIgbo = "Chineke, gọzie ha n'ihe Gị nyere ha, gbaghara ha ma meere ha ebere.",
                reference = "Muslim 3/1615."
            ),
            DuaEntity(
                id = 14,
                category = "Marriage & Family",
                title = "Before Marital Intimacy",
                arabic = "بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا",
                transliteration = "Bismillah, Allahumma jannibnash-Shaytana, wa jannibish-Shaytana ma razaqtana.",
                translation = "In the Name of Allah. O Allah, keep Satan away from us and keep Satan away from whatever You bestow upon us.",
                translationHausa = "Da sunan Allah, Ya Allah Ka nesanta Shaidan daga gare mu, kuma Ka nesanta Shaidan daga abin da Ka arzuta mu da shi.",
                translationYoruba = "Pẹlu orukọ Allāhu, Allāhu mu satani jinna si wa, ki O si mu satani jinna si nkan ti O ti pese fun wa.",
                translationIgbo = "N'aha Chineke. Chineke, mee ka Setan pụọ n'ebe anyị nọ ma mee ka Setan pụọ n'ihe ọ bụla Gị na-enye anyị.",
                reference = "Al-Bukhari 6/141, Muslim 2/1028."
            ),
            DuaEntity(
                id = 15,
                category = "Travel & Home",
                title = "Supplication for Travel",
                arabic = "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ",
                transliteration = "Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila Rabbina lamunqalibun.",
                translation = "Glory is to Him Who has subjected this to us, and we were not able to overcome it by ourselves. And surely, unto our Lord we shall return.",
                translationHausa = "Tsarki ya tabbata ga Wanda Ya horar mana da wannan alhalin ba mu kasance masu iko a kanshi ba, kuma lallai mu zuwa ga Ubangijinmu masu komawa ne.",
                translationYoruba = "Mimọ ni fun Ẹni ti O ro eyi gẹgẹ bi irọrun fun wa ti a ko si ni agbara lori rẹ, daju daju sọdọ Oluwa wa ni a o pada si.",
                translationIgbo = "Otuto dịrị Onye ahụ mere ka nke a nọrọ n'okpuru anyị, ebe anyị na-enweghị ike site n'onwe anyị imeri ya. N'ezie, n'aka Onyenwe anyị ka anyị ga-alaghachi.",
                reference = "Muslim 2/978."
            ),

            // HISNUL MUSLIM CHAPTERS 34 TO 51 IN EXACT ORDER
            DuaEntity(
                id = 16,
                category = "Hardship & Anxiety",
                title = "Relief from Anxiety and Distress",
                arabic = "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ",
                transliteration = "Allahumma inni a'udhu bika minal-hammi wal-hazani, wal-'ajzi wal-kasali, wal-bukhli wal-jubni, wa dala'id-dayni wa ghalabatir-rijal.",
                translation = "O Allah, I seek refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being overpowered by men.",
                translationHausa = "Ya Allah, lallai ina neman tsari da Kai daga damuwa da bakin ciki, da kasawa da lalaci, da rowa da tsoro, da nauyin bashi da kuma rinjayen maza a kaina.",
                translationYoruba = "Allāhu, mo wa isadi lọdọ Rẹ lọwọ ibanujẹ ati aibalẹ ọkan, ati ailera ati ọlẹ, ati ojukokoro ati ojo, ati iwuwo gbese ati lile ti awọn eniyan n ni wa lara.",
                translationIgbo = "Chineke, ana m achọ ebe mgbaba n'aka Gị pụọ na nchegbu na mwute, adịghị ike na umengwụ, anyaukwu na ụjọ, ibu arọ nke ụgwọ na ịbụ ndị mmadụ siri ike meriri anyị.",
                reference = "Al-Bukhari 7/158. Hisnul Muslim Chapter 34."
            ),
            DuaEntity(
                id = 17,
                category = "Hardship & Anxiety",
                title = "Removal of Sorrow and Grief",
                arabic = "لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ",
                transliteration = "La ilaha illallahul-'Azimul-Halim, la ilaha illallahu Rabbul-'Arshil-'Azim, la ilaha illallahu Rabbus-samawati wa Rabbul-ardi wa Rabbul-'Arshil-Karim.",
                translation = "There is none worthy of worship but Allah the Mighty, the Forbearing. There is none worthy of worship but Allah, Lord of the Magnificent Throne. There is none worthy of worship but Allah, Lord of the heavens and Lord of the earth, and Lord of the Noble Throne.",
                translationHausa = "Babu abin bautawa da gaskiya sai Allah Mai girma, Mai hakuri. Babu abin bautawa da gaskiya sai Allah, Ubangijin Al'arshi Mai girma. Babu abin bautawa da gaskiya sai Allah, Ubangijin sammai da Ubangijin kasa, kuma Ubangijin Al'arshi mai daraja.",
                translationYoruba = "Ko si ọba miran ti a gbọdọ jọsin fun afi Allāhu ti o tobi ti o si ni sũru. Ko si ọba miran ti a gbọdọ jọsin fun afi Allāhu ti o jẹ Oluwa Itẹ ti o tobi. Ko si ọba miran ti a gbọdọ jọsin fun afi Allāhu ti o jẹ Oluwa awọn sanma ati Oluwa ilẹ, ti o si jẹ Oluwa Itẹ t'o ni ọla nla.",
                translationIgbo = "Ọ dịghị onye kwesịrị ofufe ma ọ bụghị Chineke Onye Pụrụ Ime Ihe Niile, Onye nwere ndidi. Ọ dịghị onye kwesịrị ofufe ma ọ bụghị Chineke, Onyenwe ocheeze dị ebube. Ọ dịghị onye kwesịrị ofufe ma ọ bụghị Chineke, Onyenwe eluigwe na Onyenwe ụwa, Onyenwe ocheeze dị asọ.",
                reference = "Al-Bukhari 8/154, Muslim 4/2092. Hisnul Muslim Chapter 35."
            ),
            DuaEntity(
                id = 66,
                category = "Hardship & Anxiety",
                title = "Facing an Enemy or Person in Authority",
                arabic = "اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ",
                transliteration = "Allahumma inna naj'aluka fi nuhurihim wa na'udhu bika min shururihim.",
                translation = "O Allah, we place You before them and we seek refuge in You from their evils.",
                translationHausa = "Ya Allah, lallai mu muna sanya Ka a wuyoyinsu (don kariya), kuma muna neman tsari da Kai daga sharrudansu.",
                translationYoruba = "Allāhu, a fi Ọ si iwaju wọn, a si wa isadi pẹlu Rẹ lọwọ aburu wọn.",
                translationIgbo = "Chineke, anyị na-etinye Gị n'ihu ha ma na-achọ ebe mgbaba n'aka Gị pụọ n'ihe ọjọọ ha.",
                reference = "Abu Dawud 2/89, Al-Hakim 2/142. Hisnul Muslim Chapter 36."
            ),
            DuaEntity(
                id = 67,
                category = "Hardship & Anxiety",
                title = "Fear of Oppression by a Ruler",
                arabic = "اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَارًا مِنْ فُلَانٍ وَأَحْزَابِهِ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ أَنْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلَهَ غَيْرُكَ",
                transliteration = "Allahumma Rabbas-samawatis-sab'i, wa Rabbal-'Arshil-'Azim, kun li jaran min fulanin wa ahzabihi, an yafruta 'alayya ahadun minhum aw an yatgha, 'azza jaruk, wa jalla thana'uk, wa la ilaha ghayruk.",
                translation = "O Allah, Lord of the seven heavens and Lord of the Magnificent Throne, be a protector for me against so-and-so and his allies, lest any of them commit excess against me or transgress. Mighty is Your protection, exalted is Your praise, and there is no deity other than You.",
                translationHausa = "Ya Allah, Ubangijin sammai bakwai da Ubangijin Al'arshi mai girma, Ka zama mini makari daga wane da kungiyoyinsa, kada wani daga cikinsu ya yi mini ha'inci ko ya keta alfarmana. Majiyarka ta fi karfi, kuma yabonKa ya daukaka, kuma babu abin bautawa da gaskiya ba Kai ba.",
                translationYoruba = "Allāhu, Oluwa awọn sanma meje ati Oluwa Itẹ ti O tobi, ṣe alagbawi fun mi lọwọ lagbaja ati awọn ẹgbẹ rẹ, ki ẹnikan ninu wọn ma ṣe kọlu mi tabi ṣaṣiṣẹ. Ibora Rẹ ni agbara, iyin Rẹ ga, ko si ọba miran leyi ti ki i ṣe Iwọ.",
                translationIgbo = "Chineke, Onyenwe eluigwe asaa na Onyenwe ocheeze dị ebube, bụrụ onye nchebe m pụọ n'aka onye ahụ na ndị otu ya, ka onye ọ bụla n'ime ha ghara imerụ m ahụ ma ọ bụ gafere oke. Nchebe Gị siri ike, otuto Gị dị ukwuu, ọ dịghịkwa chineke ọzọ ma ọ bụghị Gị.",
                reference = "Al-Bukhari in Al-Adab Al-Mufrad (no. 707). Hisnul Muslim Chapter 37."
            ),
            DuaEntity(
                id = 68,
                category = "Hardship & Anxiety",
                title = "Supplication Against Enemies",
                arabic = "اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الْأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ",
                transliteration = "Allahumma Munzilal-Kitabi, Sari'al-hisabi, ihzimil-Ahzab, Allahum-mahzimhum wa zalzilhum.",
                translation = "O Allah, Revealer of the Book, Swift in account, defeat the confederates; O Allah, defeat them and shake them.",
                translationHausa = "Ya Allah, Mai saukar da Littafi, Mai gaggawar bincike, Ka kayar da kungiyoyin makiya, Ya Allah Ka kayar da su kuma Ka girgiza su.",
                translationYoruba = "Allāhu, Onisọkalẹ Tira, Oniyara lori isiro, ṣẹgun awọn ẹgbẹ; Allāhu, ṣẹgun wọn ki O si mu wọn mi pẹti.",
                translationIgbo = "Chineke, Onye na-eziga Akwụkwọ Nsọ, Onye na-enyocha ihe ngwa ngwa, merie ndị iro; Chineke, merie ha ma mee ka ha jijie.",
                reference = "Al-Bukhari 7/156, Muslim 3/1362. Hisnul Muslim Chapter 38."
            ),
            DuaEntity(
                id = 69,
                category = "Hardship & Anxiety",
                title = "When Fearing a Group of People",
                arabic = "اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ",
                transliteration = "Allahum-makfinihim bima shi't.",
                translation = "O Allah, protect me against them with whatever You will.",
                translationHausa = "Ya Allah, Ka wadatar mini daga sharrinsu da abin da Ka so.",
                translationYoruba = "Allāhu, to mi gẹgẹ bi O ṣe fẹ lọwọ wọn.",
                translationIgbo = "Chineke, chebe m pụọ n'aka ha site n'ihe ọ bụla Gị chọrọ.",
                reference = "Muslim 4/2300. Hisnul Muslim Chapter 39."
            ),
            DuaEntity(
                id = 70,
                category = "Hardship & Anxiety",
                title = "When Afflicted by Doubts in Faith",
                arabic = "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ، آمَنْتُ بِاللَّهِ وَرُسُلِهِ",
                transliteration = "A'udhu billahi minash-shaytanir-rajim, amantu billahi wa rusulih.",
                translation = "I seek refuge in Allah from Satan the outcast, I believe in Allah and His Messengers.",
                translationHausa = "Ina neman tsari da Allah daga Shaidan jifaffe, na yi imani da Allah da ManzanninSa.",
                translationYoruba = "Mo wa isadi pẹlu Allāhu lọwọ satani ẹni-egbe, mo gba Allāhu ati awọn Ojisẹ Rẹ gbo.",
                translationIgbo = "Ana m achọ ebe mgbaba n'aka Chineke pụọ n'aka Setan onye a chụpụrụ achụpụ, na-ekwere na Chineke na ndị Ozi Ya.",
                reference = "Al-Bukhari (Fathul-Bari 6/336), Muslim 1/119-120. Hisnul Muslim Chapter 40."
            ),
            DuaEntity(
                id = 31,
                category = "Hardship & Anxiety",
                title = "Dua for Settling Debts",
                arabic = "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ",
                transliteration = "Allahum-makfini bihalalika 'an haramika wa aghnini bifadlika 'amman siwak.",
                translation = "O Allah, make what is lawful sufficient for me over what is unlawful, and enrich me with Your grace so that I am independent of anyone other than You.",
                translationHausa = "Ya Allah, Ka wadatar da ni da halal dinka daga haram dinka, kuma Ka wadatar da ni da falalarKa ga barin kowa sai Kai.",
                translationYoruba = "Allāhu, jẹ ki nkan halal Rẹ to mi ju nkan haram lọ, ki O si sọ mi di ọlọrọ pẹlu oore-ọfẹ Rẹ lọwọ awọn ẹlomiran yatọ si Iwọ.",
                translationIgbo = "Chineke, mee ka ihe ndị ziri ezi zuru m ebe m ga-ahapụ ihe ndị na-ezighị ezi, were amara Gị mee m ọgaranya ka m ghara ịdabere n'aka onye ọ bụla ọzọ ma ọ bụghị Gị.",
                reference = "At-Tirmidhi 5/560. Hisnul Muslim Chapter 41."
            ),
            DuaEntity(
                id = 71,
                category = "Prayers & Mosque",
                title = "When Distracted by Whispers in Prayer",
                arabic = "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ",
                transliteration = "A'udhu billahi minash-shaytanir-rajim (watful 'an yasarihi thalathan).",
                translation = "I seek refuge in Allah from Satan the outcast (and spit lightly to the left three times).",
                translationHausa = "Ina neman tsari da Allah daga Shaidan jifaffe (sai ya yi tofi a kafadarsa ta hagu sau uku).",
                translationYoruba = "Mo wa isadi pẹlu Allāhu lọwọ satani ẹni-egbe (ki o si tu ito pẹlẹ si apa osi rẹ lẹrin mẹta).",
                translationIgbo = "Ana m achọ ebe mgbaba n'aka Chineke pụọ n'aka Setan onye a chụpụrụ achụpụ (ma gụọ iyi n'aka ekpe ugboro atọ).",
                reference = "Muslim 4/1729. Hisnul Muslim Chapter 42."
            ),
            DuaEntity(
                id = 72,
                category = "Hardship & Anxiety",
                title = "When an Affair Becomes Difficult",
                arabic = "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا",
                transliteration = "Allahumma la sahla illa ma ja'altahu sahla, wa Anta taj'alul-hazna idha shi'ta sahla.",
                translation = "O Allah, there is no ease except in that which You have made easy, and You make the difficult easy if You wish.",
                translationHausa = "Ya Allah, babu mai sauki sai abin da Ka sanya shi ya zama mai sauki, kuma Kai ne Kake sanya kuncin zuciya (ko tsanani) ya zama mai sauki idan Ka so.",
                translationYoruba = "Allāhu, ko si irọrun kankan afi eyi ti O ṣe ni irọrun, Iwọ lo si n sọ inira di irọrun ti O ba fẹ.",
                translationIgbo = "Chineke, ọ dịghị ihe dị mfe ma ọ bụghị ihe Gị mere ka ọ dị mfe, Gị na-emewokwa ka ahụhụ dị mfe ma ọ bụrụ na Gị chọrọ.",
                reference = "Ibn Hibban in his Sahih (no. 327), Ibn Hajar in Nata'ij Al-Afkar 4/27. Hisnul Muslim Chapter 43."
            ),
            DuaEntity(
                id = 73,
                category = "Hardship & Anxiety",
                title = "Expiation After Committing a Sin",
                arabic = "مَا مِنْ عَبْدٍ يُذْنِبُ ذَنْبًا فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلَّا غَفَرَ اللَّهُ لَهُ",
                transliteration = "Ma min 'abdin yudhnibu dhanban fayuhsinut-tuhura, thumma yaqumu fayusalli rak'atayn, thumma yastaghfirullaha illa ghafarallahu lah.",
                translation = "There is no servant who commits a sin, then purifies himself well, stands up and prays two units of prayer, then asks Allah for forgiveness except that Allah forgives him.",
                translationHausa = "Babu wani bawa da zai aikata zunubi sai ya kyautata alwala, sannan ya tashi ya yi raka'a biyu, sannan ya nemi gafarar Allah face Allah Ya gafarta masa.",
                translationYoruba = "Ko si ẹru ti yoo dẹṣẹ, ti yoo si ṣe alwala daradara, ti yoo gbe ra rẹ dide lati ki rak'ah meji, ti yoo si tọrọ gafara lọdọ Allāhu afi ki Allāhu rọ ọ lẹṣẹ ji.",
                translationIgbo = "Ọ dịghị ohu ga-emahi mmehie, mechaa saa ahụ nke oma, gbochie onwe ya kpere ekpere rakaat abụọ, mechaa rịọ Chineke mgbaghara ma ọ bụghị na Chineke ga-agbaghara ya.",
                reference = "Abu Dawud 2/86, At-Tirmidhi 2/257. Hisnul Muslim Chapter 44."
            ),
            DuaEntity(
                id = 74,
                category = "Protection & Evil Eye",
                title = "Expelling Satan and His Whispers",
                arabic = "الْاسْتِعَاذَةُ بِاللَّهِ مِنْهُ، وَالْأَذَانُ",
                transliteration = "Al-Isti'adhatu billahi minhu, wal-Adhan.",
                translation = "Seeking refuge in Allah from him (saying A'udhu billahi minash-shaytanir-rajim) and the call to prayer (Adhan).",
                translationHausa = "Neman tsari da Allah daga Shaidan (A'udhu billahi minash-shaytanir-rajim) da kuma Kiran Sallah (Adhan da Iqama).",
                translationYoruba = "Wíwá ìsàdí pẹ̀lú Allāhu lọ́wọ́ rẹ̀ ati pípè Àdánù.",
                translationIgbo = "Ịchọ ebe mgbaba n'aka Chineke pụọ n'aka ya na ịkpọ oku ekpere (Adhan).",
                reference = "Abu Dawud 1/206, Muslim 1/291. Hisnul Muslim Chapter 45."
            ),
            DuaEntity(
                id = 75,
                category = "Hardship & Anxiety",
                title = "When Something Unpleasant Happens",
                arabic = "قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ",
                transliteration = "Qadarullahi wa ma sha'a fa'al.",
                translation = "It is the decree of Allah and He does whatever He wills.",
                translationHausa = "Kaddarar Allah ce, kuma abin da Ya so Shi Ya aikata.",
                translationYoruba = "Kadara Allāhu ni, ohun ti O si fẹ lo ṣe.",
                translationIgbo = "Ọ bụ mkpebi Chineke, Ya emewokwa ihe ọ bụla Ọ chọrọ.",
                reference = "Muslim 4/2052. Hisnul Muslim Chapter 46."
            ),
            DuaEntity(
                id = 76,
                category = "Marriage & Family",
                title = "Congratulations on a New Born & Reply",
                arabic = "بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ",
                transliteration = "Barakallahu laka fil-mawhubi lak, wa shakartal-Wahiba, wa balagha ashuddahu, wa ruziqta birrah.",
                translation = "May Allah bless for you what He has bestowed upon you, and may you give thanks to the Bestower, and may the child reach maturity, and may you be granted its righteousness.",
                translationHausa = "Allah Ya yi muku albarka a abin da aka ba ku, ka gode wa Mai bayarwa, kuma ya isa munzalin karfinsa, kuma aka arzuta ka da biyayyarsa.",
                translationYoruba = "Ki Allāhu ṣe ibukun fun ọ ninu ohun ti a ta ọ lore rẹ, ki o dupe fun Ẹni-Ta-Lore, ki o si dagba ki o tobi, ki a si fun ọ ni iwa rere rẹ.",
                translationIgbo = "Ka Chineke gọzie gị n'ihe Ọ nyere gị, ma nwee ekele n'aka Onye na-enye ihe, ka nwa ahụ tolite, ma meere gị ezi omume.",
                reference = "An-Nawawi in Al-Adhkar p. 349, Al-Albani in Sahih Al-Adhkar. Hisnul Muslim Chapter 47."
            ),
            DuaEntity(
                id = 37,
                category = "Protection & Evil Eye",
                title = "Seeking Protection for Children",
                arabic = "أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ",
                transliteration = "U'idhukuma bikalimatil-lahit-tammah, min kulli shaytanin wa hammah, wa min kulli 'aynin lammah.",
                translation = "I seek protection for you in the Perfect Words of Allah from every devil and poisonous beast, and from every envious eye.",
                translationHausa = "Ina neman tsari gare ku da kalmomin Allah cikakku, daga dukkan Shaidan da dabba mai dafi, da kuma kowane ido mai cutarwa.",
                translationYoruba = "Mo wa isadi fun yin pẹlu awọn ọrọ Allāhu t'o peye, lọwọ gbogbo satani ati kokoro t'o ni majele, ati lọwọ gbogbo oju t'o ni ilara buruku.",
                translationIgbo = "Ana m achọ nchebe maka gị site n'okwu Chineke zuru oke pụọ n'aka mmụọ ọjọọ niile na anụ ọhịa nwere nsi, na n'anya anyaukwu ọ bụla.",
                reference = "Al-Bukhari 4/119. Hisnul Muslim Chapter 48."
            ),
            DuaEntity(
                id = 49,
                category = "Visiting the Sick",
                title = "Dua when Visiting the Sick",
                arabic = "لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ",
                transliteration = "La ba'sa tahurun in sha' Allah.",
                translation = "Do not worry, it is a purification, if Allah wills.",
                translationHausa = "Babu damuwa, tsarki ne idan Allah Ya so.",
                translationYoruba = "Ko si wahala kankan, nkan mimọ ni pẹlu iyọnu Allāhu.",
                translationIgbo = "Atụla ụjọ, ọ bụ ihe ga-asacha mmehie gị, ma ọ bụrụ na Chineke chọrọ.",
                reference = "Al-Bukhari (Fathul-Bari 10/118). Hisnul Muslim Chapter 49."
            ),
            DuaEntity(
                id = 48,
                category = "Visiting the Sick",
                title = "Virtues of Visiting the Sick",
                arabic = "مَا مِنْ مُسْلِمٍ يَعُودُ مُسْلِمًا غُدْوَةً إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ عَادَهُ مَسَاءً إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ، وَكَانَ لَهُ خَرِيفٌ فِي الْجَنَّةِ",
                transliteration = "Ma min muslimin ya'udu musliman ghudwatan illa salla 'alayhi sab'una alfa malakin hatta yumsi, wa in 'adahu masa'an illa salla 'alayhi sab'una alfa malakin hatta yusbiha, wa kana lahu kharifun fil-Jannah.",
                translation = "No Muslim visits a sick Muslim in the morning except that seventy thousand angels send blessings upon him until evening; and if he visits him in the evening, seventy thousand angels send blessings upon him until morning, and he will have an orchard in Paradise.",
                translationHausa = "Babu wani musulmi da zai ziyarci musulmi mara lafiya da safe face mala'iku dubu saba'in (70,000) sun yi masa addu'ar rahama har zuwa yamma, kuma idan ya ziyarce shi da yamma face mala'iku dubu saba'in sun yi masa addu'a har zuwa safe, kuma zai samu 'ya'yan itace a Aljanna.",
                translationYoruba = "Ko si musulumi ti yoo bẹ musulumi alaisan wo ni owurọ afi ki awọn angẹli ẹgbẹrin ọkẹ meje (70,000) ṣe adura fun un titi alẹ.",
                translationIgbo = "Ọ dịghị Onye Muslim ga-eleta Muslim ibe ya na-arịa slowly n'ụtụtụ ma ọ bụghị na puku ndị mmụọ ozi iri asaa ga-agọzi ya.",
                reference = "At-Tirmidhi 3/300, Ibn Majah 1/463, Sahih At-Tirmidhi 1/286. Hisnul Muslim Chapter 50."
            ),
            DuaEntity(
                id = 77,
                category = "Visiting the Sick",
                title = "Sick Person Despairing of Life",
                arabic = "اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى",
                transliteration = "Allahum-maghfir li warhamni wa alhiqni bir-Rafiqil-A'la.",
                translation = "O Allah, forgive me, have mercy on me and join me with the Highest Companionship.",
                translationHausa = "Ya Allah, Ka gafarta mini, Ka ji kai na, kuma Ka sadar da ni da Mafi daukakar Aboki (a Aljanna).",
                translationYoruba = "Allāhu, rọ mi lẹṣẹ ji, ki O ke mi, ki O si mu mi darapọ mọ Ọrẹ ti O ga julo.",
