                transliteration = "Ashhadu an la ilaha illallahu wahdahu la sharika lahu wa ashhadu anna Muhammadan 'abduhu wa Rasuluhu. Allahummaj-'alni minat-tawwabina waj-'alni minal-mutatahhirin.",
