                transliteration = "As-salamu 'alaykum ahlad-diyar, minal-mu'minina wal-muslimin, wa inna in sha' Allahu bikum lahiqun, nas'alullaha lana wa lakumul-'afiyah.",
                translation = "Peace be upon you, O people of these abodes, believers and Muslims.",
