                transliteration = "Allahumma salli 'ala Muhammadin wa 'ala ali Muhammadin, kama sallayta 'ala Ibrahima wa 'ala ali Ibrahima, innaka Hamidun Majid.",
                translation = "O Allah, bestow Your favor on Muhammad and on the family of Muhammad, as You have bestowed Your favor on Ibrahim and on the family of Ibrahim.",
                translationHausa = "Ya Allah, Ka yi daukaka ga Muhammad da iyalan Muhammad, kamar yadda Ka yi daukaka ga Ibrahim da iyalan Ibrahim.",
                translationYoruba = "Allāhu, ke Muhammad ati idile Muhammad, gẹgẹ bi O ṣe ke Ibrahim ati idile Ibrahim.",
                translationIgbo = "Chineke, gọzie Muhammad na ndị ezinụlọ Muhammad, dịka Gị siri gọzie Ibrahim na ndị ezinụlọ Ibrahim.",
                reference = "Al-Bukhari 6/408."
            ),
            DuaEntity(
                id = 41,
                category = "Morning & Evening",
                title = "Morning Supplication",
                arabic = "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ",
                transliteration = "Alhamdu lillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushur.",
                translation = "All praise is due to Allah who gave us life after having taken it from us and unto Him is the resurrection.",
                translationHausa = "Godiya ta tabbata ga Allah wanda Ya raye mu bayan Ya kashe mu, kuma zuwa gare Shi ne tashi.",
                translationYoruba = "Ọpẹ ni fun Allāhu ti o sọ wa di alaaye lẹyin ti o ti pa wa, ati sọdọ Rẹ ni ajinde n bẹ.",
                translationIgbo = "Otuto ni ma handu Chineke Onye nyere anyị ndụ mgbe anyị nwụsịrị, n'aka Ya ka mbilite n'ọnwụ dị.",
                reference = "Reciting this upon waking up expresses profound gratitude for physical and spiritual revival.\nReference: Al-Bukhari, Muslim 4/2083."
            ),
            DuaEntity(
                id = 42,
                category = "Dressing",
                title = "Wearing a Garment",
                arabic = "الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ",
                transliteration = "Alhamdu lillahil-ladhi kasani hadha (ath-thawba) wa razaqanihi min ghayri hawlin minni wa la quwwatin.",
                translation = "Praise is to Allah Who has clothed me with this garment and provided it for me without any power or strength from myself.",
                translationHausa = "Godiya ta tabbata ga Allah wanda Ya tufatar da ni wannan tufafi kuma Ya arzuta ni da shi ba tare da wata dabara tawa ko iko nawa ba.",
                translationYoruba = "Ọpẹ ni fun Allāhu ti o fun mi ni aṣọ yi wọ, ti o si pese rẹ fun mi laisi agbara tabi okun kankan lati ọdọ mi.",
                translationIgbo = "Otuto dịrị Chineke Onye yiri m uwe a, ma nye m ya n'enweghị mbọ m gbara ma ọ bụ ike m siri n'aka m.",
                reference = "Abu Dawud, At-Tirmidhi, Ibn Majah. Hisnul Muslim Chapter 3."
            ),
            DuaEntity(
                id = 43,
                category = "Dressing",
                title = "Wearing a New Garment",
                arabic = "اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ",
                transliteration = "Allahumma lakal-hamdu Anta kasawtanihi, as'aluka min khayrihi wa khayri ma suni'a lahu, wa a'udhu bika min sharrihi wa sharri ma suni'a lahu.",
                translation = "O Allah, unto You belongs all praise. You have clothed me with it. I ask You for its good and the good for which it was made, and I seek refuge in You from its evil and the evil for which it was made.",
                translationHausa = "Ya Allah, godiya ta tabbata gare Ka, Kai ne Ka tufatar da ni shi, ina rokonKa alherin cikinsa da alherin abin da aka yi shi dominsa, kuma ina neman tsari da Kai daga sharrinsa da sharrin abin da aka yi shi dominsa.",
                translationYoruba = "Allāhu, Rẹ ni gbogbo ọpẹ, Iwọ lo wọ mi ni aṣọ yi. Mo bọ lọwọ Rẹ fun oore rẹ ati oore ohun ti a ṣe e fun.",
                translationIgbo = "Chineke, ekele niile dịrị Gị, Gị yiri m uwe a.",
                reference = "Abu Dawud, At-Tirmidhi. Hisnul Muslim Chapter 4."
            ),
            DuaEntity(
                id = 44,
                category = "Dressing",
                title = "Dua for Someone Wearing New Clothes",
                arabic = "إِلْبَسْ جَدِيدًا، وَعِشْ حَمِيدًا، وَمُتْ شَهِيدًا",
                transliteration = "Ilbis jadidan, wa 'ish hamidan, wa mut shahidan.",
                translation = "May you wear new clothes, live a praiseworthy life, and die as a martyr.",
                translationHausa = "Sanya sabuwa, ka rayu kana abin yabo, kuma ka mutu kana shahidi.",
                translationYoruba = "Wọ aṣọ tuntun, gbe aye ti o ni iyin, ki o si ku gẹgẹ bi oniṣẹgun mọtia.",
                translationIgbo = "Yiri uwe ọhụrụ, bie ndụ a na-enwe ekele, ma nwụọ dị ka onye meriri n'ihi Chineke.",
                reference = "Ibn Majah 2/1178, An-Nasa'i. Hisnul Muslim Chapter 5."
            ),
            DuaEntity(
                id = 45,
                category = "Dressing",
                title = "Taking Off Clothes",
                arabic = "بِسْمِ اللَّهِ",
                transliteration = "Bismillah.",
                translation = "In the Name of Allah.",
                translationHausa = "Da sunan Allah.",
                translationYoruba = "Pelli orukọ Allāhu.",
                translationIgbo = "N'aha Chineke.",
                reference = "At-Tirmidhi 2/505. Hisnul Muslim Chapter 6."
            ),
            DuaEntity(
                id = 46,
                category = "Prayers & Mosque",
                title = "Walking to the Mosque",
                arabic = "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا",
                transliteration = "Allahummaj-'al fi qalbi nura, wa fi lisani nura, wa fi sam'i nura, wa fi basari nura, wa min fawqi nura, wa min tahti nura, wa 'an yamini nura, wa 'an shimali nura, wa min amami nura, wa min khalfi nura.",
                translation = "O Allah, place light in my heart, light on my tongue, light in my hearing, light in my sight, light above me, light below me, light on my right, light on my left, light before me, and light behind me.",
                translationHausa = "Ya Allah, Ka sanya haske a cikin zuciyata, da haske a harshena, da haske a jina, da haske a ganina, da haske ta samana, da haske ta karkashina, da haske ta damana, da haske ta haguna, da haske ta gabana, da haske ta bayana.",
                translationYoruba = "Allāhu, fi imọlẹ sí ọkàn mi, fi imọlẹ sí ahọ́n mi, fi imọlẹ sí ìgbọ́ràn mi.",
                translationIgbo = "Chineke, tinye ìhè n'obi m, ìhè n'alụ m, ìhè n'anụ m, ìhè n'anya m.",
                reference = "Al-Bukhari 11/116, Muslim 1/526. Hisnul Muslim Chapter 13."
            ),
            DuaEntity(
                id = 47,
                category = "Prayers & Mosque",
                title = "During and After Adhan",
                arabic = "اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ",
                transliteration = "Allahumma Rabba hadhihid-da'watit-tammah, was-salatil-qa'imah, ati Muhammadanil-wasilata wal-fadilah, wab'athhu maqaman mahmudanilladhi wa'adtah.",
                translation = "O Allah, Lord of this perfect call and established prayer, grant Muhammad the intercession and favor, and raise him to the praised station which You have promised him.",
                translationHausa = "Ya Allah, Ubangijin wannan kira cikakku, da sallah da za a tsarda, Ka ba wa Annabi Muhammad al-Wasilah da daukaka, kuma Ka tashe shi matsayi abin yabo wanda Ka yi masa wa'adi.",
                translationYoruba = "Allāhu, Oluwa ipe pipe yi ati sọláàti ti a o ṣe, fun Muhammad ni Wasilah ati ọla nla.",
                translationIgbo = "Chineke, Onyenwe oku a zuru oke na ekpere a, nye Muhammad intercession na amara.",
                reference = "Al-Bukhari 1/152. Hisnul Muslim Chapter 16."
            ),
            DuaEntity(
                id = 50,
                category = "Prayers & Mosque",
                title = "Opening Supplication in Prayer",
                arabic = "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ",
                transliteration = "Subhanakal-lahumma wa bihamdika wa tabarakas-muka wa ta'ala jadduka wa la ilaha ghayruk.",
                translation = "Glory is to You, O Allah, and praise. Blessed is Your name and exalted is Your majesty, and there is no deity other than You.",
                translationHausa = "Tsarki ya tabbata gare Ka ya Allah da godiyarKa, albarka ta tabbata ga sunanKa, kuma daukakarKa ta daukaka, kuma babu wani abin bautawa da gaskiya ba Kai ba.",
                translationYoruba = "Mimọ ni fun Rẹ Allāhu pẹlu iyin Rẹ, adura ni fun orukọ Rẹ, ti o ga ni ọla Rẹ, ko si ọba miran leyi ti ki i ṣe Iwọ.",
                translationIgbo = "Otuto dịrị Gị Chineke na ekele. Ngọzi dịrị aha Gị ma bulie elu bu ebube Gị, ọ dịghịkwa chineke ọzọ ma ọ bụghị Gị.",
                reference = "Abu Dawud 1/206, At-Tirmidhi 1/242. Hisnul Muslim Chapter 17."
            ),
            DuaEntity(
                id = 51,
                category = "Prayers & Mosque",
                title = "Supplication in Ruku (Bowing)",
                arabic = "سُبْحَانَ رَبِّيَ الْعَظِيمِ",
                transliteration = "Subhana Rabbiyal-'Azim (three times).",
                translation = "Glory is to my Lord, the Most Great (3 times).",
                translationHausa = "Tsarki ya tabbata ga Ubangijina Mai girma (sau uku).",
                translationYoruba = "Mimọ ni fun Oluwa mi ti O tobi (lẹrin mẹta).",
                translationIgbo = "Otuto dịrị Onyenwe m Onye Kachasị Ukwuu (ugboro atọ).",
                reference = "Abu Dawud, Ibn Majah, An-Nasa'i. Hisnul Muslim Chapter 18."
            ),
            DuaEntity(
                id = 52,
                category = "Prayers & Mosque",
                title = "Rising from Ruku",
                arabic = "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ، رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ",
                transliteration = "Sami'allahu liman hamidah. Rabbana wa lakal-hamdu hamdan kathiran tayyiban mubarakan fih.",
                translation = "Allah hears whoever praises Him. Our Lord, and to You belongs all praise, abundant, good and blessed praise.",
                translationHausa = "Allah Ya ji wanda ya gode Masa. Ya Ubangijinmu, godiya ta tabbata gare Ka, godiya mai yawa, mai kyau, mai albarka a cikinta.",
                translationYoruba = "Allāhu n gbo ẹni ti o n yin In. Oluwa wa, Rẹ ni gbogbo ọpẹ, ọpẹ pupọ.",
                translationIgbo = "Chineke na-anụ onye na-eto Ya. Onyenwe anyị, n'aka Gị ka otuto niile dị.",
                reference = "Al-Bukhari 2/284, Abu Dawud 1/201. Hisnul Muslim Chapter 19."
            ),
            DuaEntity(
                id = 53,
                category = "Prayers & Mosque",
                title = "Supplication in Sujud (Prostration)",
                arabic = "سُبْحَانَ رَبِّيَ الْأَعْلَى",
                transliteration = "Subhana Rabbiyal-A'la (three times).",
                translation = "Glory is to my Lord, the Most High (3 times).",
                translationHausa = "Tsarki ya tabbata ga Ubangijina Mafi daukaka (sau uku).",
                translationYoruba = "Mimọ ni fun Oluwa mi ti O ga julo (lẹrin mẹta).",
                translationIgbo = "Otuto dịrị Onyenwe m Onye Kachasị Elu (ugboro atọ).",
                reference = "Abu Dawud 1/230, At-Tirmidhi. Hisnul Muslim Chapter 20."
            ),
            DuaEntity(
                id = 54,
                category = "Prayers & Mosque",
                title = "Between the Two Prostrations",
                arabic = "رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي",
                transliteration = "Rabbigh-fir li, Rabbigh-fir li.",
                translation = "Lord forgive me, Lord forgive me.",
                translationHausa = "Ya Ubangijina Ka gafarta mini, Ya Ubangijina Ka gafarta mini.",
                translationYoruba = "Oluwa mi rọ mi lẹṣẹ ji, Oluwa mi rọ mi lẹṣẹ ji.",
                translationIgbo = "Onyenwe m gbaghara m, Onyenwe m gbaghara m.",
                reference = "Abu Dawud 1/231. Hisnul Muslim Chapter 21."
            ),
            DuaEntity(
                id = 55,
                category = "Prayers & Mosque",
                title = "Sujud of Qur'anic Recitation",
                arabic = "سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ",
                transliteration = "Sajada wajhiya lilladhi khalaqahu wa shaqqa sam'ahu wa basarahu bihawlihi wa quwwatih, fatabarakallahu ahsanul-khaliqin.",
                translation = "My face prostrates to He Who created it and fashioned its hearing and sight by His might and power.",
                translationHausa = "Fuskata ta yi sujada ga Wanda Ya halicce ta, Ya tsage jinta da ganinta da dabaraSa da ikonSa.",
                translationYoruba = "Oju mi n foribalẹ fun Ẹni ti O da a ti O si la ìgbọ́ràn rẹ ati ìríran rẹ pẹlu agbara Rẹ.",
                translationIgbo = "Ihu m na-ada n'ala sọọpụrụ Onye kere ya ma mepee ntị ya na anya ya site n'ike Ya.",
                reference = "At-Tirmidhi 2/474, An-Nasa'i. Hisnul Muslim Chapter 22."
            ),
            DuaEntity(
                id = 56,
                category = "Prayers & Mosque",
                title = "Tashahhud (Tahiyya)",
                arabic = "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ",
                transliteration = "At-tahiyyatu lillahi was-salawatu wat-tayyibat, as-salamu 'alayka ayyuhan-Nabiyyu wa rahmatullahi wa barakatuh, as-salamu 'alayna wa 'ala 'ibadillahis-salihin. Ashhadu an la ilaha illallahu wa ashhadu anna Muhammadan 'abduhu wa Rasuluh.",
                translation = "All compliments, prayers and pure words are due to Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings.",
                translationHausa = "Gaisuwa ta tabbata ga Allah, da salloli, da kyawawan abubuwa. Aminci ya tabbata a gare ka ya kai Annabi da rahamar Allah da albarkarsa.",
                translationYoruba = "Gbogbo ki-n-ni, sọláàti ati ohun mimọ ni fun Allāhu.",
                translationIgbo = "Ekele niile, ekpere na okwu dị asọ dịrị Chineke.",
                reference = "Al-Bukhari 1/13, Muslim 1/301. Hisnul Muslim Chapter 23."
            ),
            DuaEntity(
                id = 57,
                category = "Sleeping & Waking Up",
                title = "Turning Over During Sleep",
                arabic = "لَا إِلَهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ",
                transliteration = "La ilaha illallahul-Wahidul-Qahhar, Rabbus-samawati wal-ardi wa ma baynahumal-'Azizul-Ghaffar.",
                translation = "There is no deity except Allah, the One, the Irresistible, Lord of the heavens and the earth and all between them.",
                translationHausa = "Babu abin bautawa da gaskiya sai Allah, Guda Daya, Mai rinjaye, Ubangijin sammai da kasa da abin da ke tsakaninsu, Mafi mabuwayi, Mai yawan gafara.",
                translationYoruba = "Ko si ọba miran afi Allāhu ti o wa Nikan, Onijakadi, Oluwa awọn sanma ati ilẹ.",
                translationIgbo = "Ọ dịghị onye kwesịrị ofufe ma ọ bụghị Chineke, Onye Naanị Ya, Onyenwe eluigwe na ụwa.",
                reference = "An-Nasa'i, Al-Hakim 1/540. Hisnul Muslim Chapter 29."
            ),
            DuaEntity(
                id = 58,
                category = "Sleeping & Waking Up",
                title = "When Disturbed or Unable to Sleep",
                arabic = "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ",
                transliteration = "A'udhu bikalimatil-lahit-tammati min ghadabihi wa 'iqabihi, wa sharri 'ibadihi, wa min hamazatish-shayatini wa an yahdurun.",
                translation = "I seek refuge in the perfect words of Allah from His anger and His punishment, from the evil of His slaves, and from the whisperings of devils.",
                translationHausa = "Ina neman tsari da cikakkun kalmomin Allah daga fushinSa da ukubarSa, da sharrin bayinSa, da daga fizgar shaidanu da halartarsu kusa da ni.",
                translationYoruba = "Mo wa isadi pẹlu awọn ọrọ Allāhu t'o peye lọwọ ibinu Rẹ ati iyasi Rẹ.",
                translationIgbo = "Ana m achọ ebe mgbaba n'okwu Chineke zuru oke pụọ n'iwe Ya na ahụhụ Ya.",
                reference = "Abu Dawud 4/12, At-Tirmidhi 3/171. Hisnul Muslim Chapter 30."
            ),
            DuaEntity(
                id = 59,
                category = "Sleeping & Waking Up",
                title = "After Having a Bad Dream",
                arabic = "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ وَمِنْ شَرِّ هَذِهِ الرَّؤْيَا",
                transliteration = "A'udhu billahi minash-shaytani wa min sharri hadhihir-ru'ya.",
                translation = "I seek refuge in Allah from Satan and from the evil of this dream.",
                translationHausa = "Ina neman tsari da Allah daga Shaidan da kuma daga sharrin wannan mafarki. (Sai ya yi tofi ta hagu sau 3, ya juya daya bangaren).",
                translationYoruba = "Mo wa isadi pẹlu Allāhu lọwọ satani ati lọwọ aburu ala yi.",
                translationIgbo = "Ana m achọ ebe mgbaba n'aka Chineke pụọ n'aka Setan na n'ihe ọjọọ nke nrọ a.",
                reference = "Muslim 4/1772-1773. Hisnul Muslim Chapter 31."
            ),
            DuaEntity(
                id = 60,
                category = "Prayers & Mosque",
                title = "Qunut in Witr Prayer",
                arabic = "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ",
                transliteration = "Allahummahdini fiman hadayt, wa 'afini fiman 'afayt, wa tawallani fiman tawallayt, wa barik li fiman a'tayt, wa qini sharra ma qadayt.",
                translation = "O Allah, guide me among those You have guided, grant me health among those You have granted health, take me into Your care among those You have taken into Your care.",
                translationHausa = "Ya Allah, Ka shirye ni a cikin waɗanda Ka shirya, Ka ba ni lafiya a cikin waɗanda Ka ba lafiya, Ka ba ni kariya a cikin waɗanda Ka kare.",
                translationYoruba = "Allāhu, tọ mi si ọna ti o tọ ninu awọn ti O ti tọ, fun mi ni alafia ninu awọn ti O ti fun ni alafia.",
                translationIgbo = "Chineke, duzie m n'etiti ndị Gị duziri, mee ka m nwee ahụ ike n'etiti ndị Gị nyere ahụ ike.",
                reference = "Abu Dawud, At-Tirmidhi, An-Nasa'i, Ibn Majah. Hisnul Muslim Chapter 32."
            ),
            DuaEntity(
                id = 61,
                category = "Prayers & Mosque",
                title = "After Salam in Witr Prayer",
                arabic = "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ",
                transliteration = "Subhanal-Malikil-Quddus (three times).",
                translation = "Glory is to the Sovereign, the Most Holy (3 times, elongating on the third).",
                translationHausa = "Tsarki ya tabbata ga Sarki Mai tsarki (sau uku, tare da daga murya a ta ukun gami da ja).",
                translationYoruba = "Mimọ ni fun Ọba Mimọ julo (lẹrin mẹta pẹlu igbe ga lẹrin kẹta).",
                translationIgbo = "Otuto dịrị Onyenwe Alaeze, Onye Kachasị Asọ (ugboro atọ).",
                reference = "An-Nasa'i 3/244, Al-Bukhari. Hisnul Muslim Chapter 33."
            ),
            DuaEntity(
                id = 62,
                category = "Greetings & Social",
                title = "Expiation for a Gathering (Kaffaratul Majlis)",
                arabic = "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ",
                transliteration = "Subhanakal-lahumma wa bihamdika, ashhadu an la ilaha illa Anta, astaghfiruka wa atubu ilayk.",
                translation = "Glory is to You, O Allah, and praise. I bear witness that there is no deity except You. I seek Your forgiveness and repent to You.",
                translationHausa = "Tsarki ya tabbata gare Ka ya Allah da godiyarKa, na shaida babu abin bautawa da gaskiya sai Kai, ina neman gafararKa kuma ina tuba zuwa gare Ka.",
                translationYoruba = "Mimọ ni fun Rẹ Allāhu pẹlu iyin Rẹ, mo jẹrii pe ko si ọba miran afi Iwọ.",
                translationIgbo = "Otuto dịrị Gị Chineke na ekele, ana m agba ama na ọ dịghị chineke ọzọ ma ọ bụghị Gị.",
                reference = "At-Tirmidhi 3/153, Abu Dawud 4/274."
            ),
            DuaEntity(
                id = 63,
                category = "Greetings & Social",
                title = "Islamic Greeting & Reply",
                arabic = "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ - (ويرد عليه): وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",
                transliteration = "As-salamu 'alaykum wa rahmatullahi wa barakatuh. (Reply): Wa 'alaykumus-salam wa rahmatullahi wa barakatuh.",
                translation = "Peace be upon you and the mercy of Allah and His blessings. (Reply): And upon you be peace and the mercy of Allah and His blessings.",
                translationHausa = "Amincin Allah da rahamarSa da albarkocinSa su tabbata a gare ku. (Amsawa): Kuma a gare ku amincin Allah da rahamarSa da albarkocinSa su tabbata.",
                translationYoruba = "Alafia Allāhu ati aanu Rẹ ati ibukun Rẹ ki o ma ba yin.",
                translationIgbo = "Udo dịrị unu na ebere Chineke na ngọzi Ya.",
                reference = "Abu Dawud 4/350, At-Tirmidhi 5/52."
            ),
            DuaEntity(
                id = 64,
                category = "Protection & Evil Eye",
                title = "Stopping at a Place",
                arabic = "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ",
                transliteration = "A'udhu bikalimatil-lahit-tammati min sharri ma khalaq.",
                translation = "I seek refuge in the Perfect Words of Allah from the evil of what He has created.",
                translationHausa = "Ina neman tsari da cikakkun kalmomin Allah daga sharrin abin da Ya halitta.",
                translationYoruba = "Mo wa isadi pẹlu awọn ọrọ Allāhu t'o peye lọwọ aburu ohun ti O da.",
                translationIgbo = "Ana m achọ ebe mgbaba n'okwu Chineke zuru oke pụọ n'ihe ọjọọ nke ihe niile Ọ kere.",
                reference = "Muslim 4/2080."
            ),
            DuaEntity(
                id = 65,
                category = "Protection & Evil Eye",
                title = "Protection from Evil Eye & Ruqyah",
                arabic = "بِسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللَّهُ يَشْفِيكَ، بِسْمِ اللَّهِ أَرْقِيكَ",
                transliteration = "Bismillahi arqika, min kulli shay'in yu'dhika, min sharri kulli nafsin aw 'ayni hasidin, Allahu yashfika, bismillahi arqika.",
                translation = "In the Name of Allah I perform Ruqyah for you, from everything that harms you, from the evil of every soul or envious eye, may Allah heal you.",
                translationHausa = "Da sunan Allah nake muku ruqyah (tofi), daga dukkan abin da ke cutar da kai, daga sharrin kowace rai ko idon mai hasada, Allah Ya warkar da kai.",
                translationYoruba = "Pẹlu orukọ Allāhu mo ṣe adura aṣẹ fun ọ, lọwọ gbogbo ohun ti n ni ọ lara.",
                translationIgbo = "N'aha Chineke ka m na-ekpere gị ekpere nchebe.",
                reference = "Muslim 4/1715."
            ),
            DuaEntity(
                id = 78,
                category = "Hardship & Anxiety",
                title = "Righteousness in Religion, World & Hereafter",
                arabic = "اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي ، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي ، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي ، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ",
                transliteration = "Allahumma aslih li dini al-lathi huwa 'ismatu amri, wa aslih li dunya-ya al-lati fiha ma'ashi, wa aslih li akhirati al-lati fiha ma'adi, wa-ja'al al-hayata ziyadatan li fi kulli khayr, wa-ja'al al-mawta rahatan li min kulli sharr.",
                translation = "O Allah, set right my religion, which is the safeguard of my affairs; and set right my world, wherein is my living; and set right my next life, to which is my return; and make life for me an increase in all good and make death a relief for me from every evil.",
                translationHausa = "Ya Allah, Ka gyara mini addinina wanda shi ne kariya ga al'amarina, Ka gyara mini duniyata wadda a cikinta take rayuwata, Ka gyara mini akhirata wadda zuwa gare ta ne komawata, Ka sanya rayuwa ta zamo mini karuwa a dukkan alheri, Ka kuma sanya mutuwa ta zamo mini hutu daga dukkan sharri.",
                translationYoruba = "Allāhu, ṣe atunṣe ẹsin mi fun mi leyi ti o jẹ àbò fun gbogbo ọrọ mi, ki O si ṣe atunṣe aye mi fun mi leyi ti igbe aye mi bẹ ninu rẹ, ki O si ṣe atunṣe ọrun mi fun mi leyi ti ibi adabọ mi n bẹ, ki O si ṣe igbesi aye ni alekun fun mi ninu gbogbo oore, ki O si ṣe iku ni isimi fun mi lọwọ gbogbo aburu.",
                translationIgbo = "Chineke, dozie okpukpe m nke bụ nchebe nke ihe niile gbasara m, dozie ụwa m ebe obibi m dị, dozie kwa ndụ m nke ikpeazụ ebe m ga-alaghachi, mee ka ndụ bụrụ mụ mmụba n'ihe ọma niile ma mee ka ọnwụ bụrụ mụ ntụsara ahụ pụọ n'ihe ọjọọ niile.",
                reference = "Sahih Muslim Book 17, Hadith 1472 (Muslim 2720)."
            ),
            DuaEntity(
                id = 79,
                category = "Hardship & Anxiety",
                title = "Relief from Sadness and Anxiety",
                arabic = "اللَّهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي",
                transliteration = "Allahumma inni 'abduka, ibn 'abdika, ibn amatika, nasiyati biyadika, madin fiyya hukmuka, 'adlun fiyya qada'uka, as'aluka bikulli ismin huwa laka, sammayta bihi nafsaka, aw anzaltahu fi kitabika, aw 'allamtahu ahadan min khalqika, aw ista'tharta bihi fi 'ilmil-ghaybi 'indaka, an taj'alal-Qur'ana rabi'a qalbi, wa nura sadri, wa jala'a huzni, wa dhahaba hammi.",
                translation = "O Allah, I am Your slave, son of Your slave, son of Your female slave, my forelock is in Your hand, Your command over me is forever executed and Your decree over me is just. I ask You by every Name belonging to You which You named Yourself with, or revealed in Your Book, or You taught to any of Your creation, or You have preserved in the knowledge of the unseen with You, that You make the Quran the spring of my heart and the light of my chest, and the banisher of my sadness and the reliever of my anxiety.",
                translationHausa = "Ya Allah, lallai ni bawanKa ne, dan bawanKa, dan bawarKa, makandara ta tana a hannunKa, hukuncinKa a kaina mai aiki ne, kaddararKa a kaina adalci ce. Ina rokonKa da dukkan suna da Ya zamo naka, wanda Ka sunanta kanKa da shi, ko Ka saukar da shi a cikin littafinKa, ko Ka kantar da shi ga wani daga halittarKa, ko Ka kebance shi a cikin ilimin gaibi a wurinKa, Ka sanya Alkur'ani ya zama furen zuciyata, da hasken kirjina, da yaye bakin cikina, da tafiyar da damuwata.",
                translationYoruba = "Allāhu, emi ni ẹru Rẹ, ọmọ ẹru Rẹ, ọmọ ẹru Rẹ obinrin, ori mi wa ni ọwọ Rẹ, hukun Rẹ lori mi jẹ dandan, kọdara Rẹ lori mi jẹ adalci. Mo n bọ Rẹ pẹlu gbogbo orukọ ti o jẹ Rẹ, ti O fi sọ ara Rẹ, tabi ti O sọ kalẹ ninu Tira Rẹ, tabi ti O kọ ẹnikan ninu ẹda Rẹ, tabi ti O fi pamọ si ilẹ gaibi lọdọ Rẹ, ki O ṣe Al-Kur’ani ni idunnu ọkan mi, ati imọlẹ aya mi, ati imukuro ibanujẹ mi, ati itula fun aibalẹ mi.",
                translationIgbo = "Chineke, m bụ ohu Gị, nwa ohu Gị nwoke, nwa ohu Gị nwanyị, isi m dị n'aka Gị, ikpe Gị n'elu m bụ dandan, mkpebi Gị n'elu m bụ ikpe ziri ezi. Ana m arịọ Gị site n'aha ọ bụla nke Gị, nke Gị sọrọ onwe Gị aha, ma ọ bụ nke Gị zigara n'Akwụkwọ Nsọ Gị, ma ọ bụ nke Gị kụziiri onye ọ bụla n'ime ihe e kere eke Gị, ma ọ bụ nke Gị debere n'ihe nzuzo nke aka Gị, ka Gị mee Qur'an ka ọ bụrụ ọṅụ nke obi m na ìhè nke obi m, na imepụ ihe nwute m na mwepu nchegbu m.",
                reference = "Musnad Ahmad 1/391, Ibn Hibban 3/253, Al-Albani in Sahih Al-Kalim Al-Tayyib 124."
            ),
            DuaEntity(
                id = 80,
                category = "Hardship & Anxiety",
                title = "Settling Debts & Protection from Poverty",
                arabic = "اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ",
                transliteration = "Allahumma Antal-Awwalu falaysa qablaka shay', wa Antal-Akhiru falaysa ba'daka shay', wa Antaz-Zahiru falaysa fawqaka shay', wa Antal-Batinu falaysa dunaka shay', iqdi 'annad-dayna wa aghnina minal-faqr.",
                translation = "O Allah, You are the First, so there is nothing before You; You are the Last, so there is nothing after You; You are the Manifest, so there is nothing above You; and You are the Hidden, so there is nothing beyond You. Settle our debts for us and enrich us against poverty.",
                translationHausa = "Ya Allah, Kai ne Na Farko babu komai kafin Kai, Kai ne Na Karshe babu komai bayan Kai, Kai ne Mai Bayyana babu komai sama da Kai, Kai ne Batin babu komai na kusa maras Kai. Ka biya mana bashi kuma Ka wadatar da mu daga talauci.",
                translationYoruba = "Allāhu, Iwọ ni Akọkọ ti ko si nkan ṣaju Rẹ, Iwọ ni Bẹbẹ ti ko si nkan lẹyin Rẹ, Iwọ ni Onibara ti ko si nkan lori Rẹ, Iwọ ni Onibọ ti ko si nkan ti o sunmọ ju Rẹ lọ. San gbese wa fun wa ki O si sọ wa di ọlọrọ kuro ninu osi.",
                translationIgbo = "Chineke, Gị bụ Onye Mbụ nke na-enweghị ihe ọ bụla tupu Gị, Gị bụ Onye Ikpeazụ nke na-enweghị ihe ọ bụla mgbe Gị gasịrị, Gị bụ Onye Pụtara Ihe nke na-enweghị ihe ọ bụla ka Gị mma, Gị bụ Onye Nzuzo nke na-enweghị ihe ọ bụla karịrị Gị. Kwụọ gị ụgwọ anyị ma mee anyị ọgaranya pụọ n'ịda ogbenye.",
                reference = "Sahih Muslim 4/2084, Hadith 2713."
            ),
            DuaEntity(
                id = 81,
                category = "Hardship & Anxiety",
                title = "Good End in All Matters",
                arabic = "اللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ",
                transliteration = "Allahumma ahsin 'aqibatana fil-umuri kulliha, wa ajirna min khizyid-dunya wa 'adhabil-akhirah.",
                translation = "O Allah, grant a good end to all our matters, and save us from humiliation in this world and punishment in the Hereafter.",
                translationHausa = "Ya Allah, Ka kyautata karshen al'amuranmu baki daya, Ka kuma tsare mu daga kankantar duniya da azabar kiyama.",
                translationYoruba = "Allāhu, ṣe atunṣe ati igbẹhin rere fun wa ninu gbogbo ọrọ wa, ki O si gba wa laaye lọwọ itiju aye ati iya ọrun.",
                translationIgbo = "Chineke, meere anyị ezi njedebe n'ihe niile anyị na-eme, ma zọpụta anyị n'ihere nke ụwa a na ahụhụ nke ndụ ikpeazụ.",
                reference = "Musnad Ahmad 4/181, Sahih Ibn Hibban 949, Al-Mustadrak Al-Hakim 3/591."
            ),
            DuaEntity(
                id = 82,
                category = "Hardship & Anxiety",
                title = "Steadfastness & Sound Heart",
                arabic = "اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَلِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ",
                transliteration = "Allahumma inni as'aluka ath-thabata fil-amri, wal-'azimata 'ala ar-rushdi, wa as'aluka mujibati rahmatika, wa 'aza'ima maghfiratika, wa as'aluka shukra ni'matika, wa husna 'ibadatika, wa as'aluka qalban saliman, wa lisanan sadiqan, wa as'aluka min khayri ma ta'lamu, wa a'udhu bika min sharri ma ta'lamu, wa astaghfiruka lima ta'lamu, innaka Anta 'Allamul-ghuyub.",
                translation = "O Allah, I ask You for steadfastness in the matter, and firm resolve upon righteousness. I ask You for the means that entail Your mercy, and the actions that guarantee Your forgiveness. I ask You for gratitude for Your blessings, and excellence in worshipping You. I ask You for a sound heart, and a truthful tongue. I ask You for the good of what You know, I seek refuge in You from the evil of what You know, and I seek Your forgiveness for what You know, for indeed You are the Knower of the Unseen.",
                translationHausa = "Ya Allah, lallai ina rokonKa tabbatuwa a kan al'amari (addini), da kuma kudurcewa a kan gaskiya da shiriya. Ina rokonKa abubuwan da suke janyo rahamarKa, da matakan samun gafararKa. Kuma ina rokonKa godiyar ni'imominKa, da kyautata bauta muku. Kuma ina rokonKa zuciya mai tsarki (salima), da harshe mai gaskiya. Kuma ina rokonKa daga alherin da Ka sani, ina neman tsari da Kai daga sharrin da Ka sani, kuma ina neman gafararKa a kan abin da Ka sani, lallai Kai ne Masanin abubuwan boye.",
                translationYoruba = "Allāhu, mo n bọ lọwọ Rẹ fun iduroṣinṣin ninu awọn ọrọ ati ipinnu lori ọna mọọmọ. Mo n bọ lọwọ Rẹ fun awọn ohun ti n mu aarẹ Rẹ wa ati awọn ohun ti n mu idariji Rẹ wa. Mo n bọ lọwọ Rẹ fun ọpẹ lori awọn oore Rẹ ati ẹwa ninu jọsin fun Un. Mo n bọ lọwọ Rẹ fun ọkan mimọ ati ahọn olootọ. Mo n bọ lọwọ Rẹ fun oore ohun ti O mọ, mo si n sọ di mimọ pẹlu Rẹ lọwọ aburu ohun ti O mọ, mo si n bọ idariji Rẹ fun ohun ti O mọ, dajudaju Iwọ ni Onimọ gbogbo ohun ti o pamọ.",
                translationIgbo = "Chineke, ana m arịọ Gị nkwụsi ike n'ihe niile na mkpebi siri ike n'okporo ezi omume. Ana m arịọ Gị ihe na-eweta amara Gị na ihe na-enye mgbaghara Gị. Ana m arịọ Gị ekele maka ngọzi Gị na ime ofufe Gị nke ọma. Ana m arịọ Gị obi dị ọcha na ire eziokwu. Ana m arịọ Gị maka ihe ọma nke Gị maara, ana m arịọ nchebe Gị pụọ n'ihe ọjọọ nke Gị maara, ana m arịọ mgbaghara Gị maka ihe nke Gị maara, n'ihi na n'ezie Gị bụ Onye Maara ihe nzuzo niile.",
                reference = "Sunan An-Nasa'i 1304, At-Tirmidhi 3407, Musnad Ahmad 17114."
            ),
            DuaEntity(
                id = 83,
                category = "Hardship & Anxiety",
                title = "Refuge from Unbeneficial Knowledge",
                arabic = "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ ، وَمِنْ قَلْبٍ لَا يَخْشَعُ ، وَمِنْ نَفْسٍ لَا تَشْبَعُ ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا",
                transliteration = "Allahumma inni a'udhu bika min 'ilmin la yanfa', wa min qalbin la yakhsha', wa min nafsin la tashba', wa min da'watin la yustajabu laha.",
                translation = "O Allah, I seek refuge in You from knowledge that does not benefit, from a heart that does not fear You, from a soul that is never satisfied, and from a supplication that is not answered.",
                translationHausa = "Ya Allah, lallai ina neman tsari da Kai daga ilimin da ba ya yin amfani, da daga zuciyar da ba ta tsoronKa, da daga rai da ba ta koshi, da kuma daga addu'ar da ba a karba.",
                translationYoruba = "Allāhu, mo n sọ di mimọ pẹlu Rẹ lọwọ mọ ti ko ni alafia, ati lọwọ ọkan ti ko ni tẹriba, ati lọwọ ẹmi ti ko ni tẹ lọrun, ati lọwọ adura ti ko ni gba.",
                translationIgbo = "Chineke, ana m arịọ nchebe Gị pụọ n'ihe mmụta na-abaghị uru, na n'obi na-atụghị Gị egwu, na n'obere obi na-enweghị afọ ojuju, na n'ekpere a na-aza gị.",
                reference = "Sahih Muslim 4/2088, Sunan An-Nasa'i 5442, Sunan Abi Dawud 1548."
            ),
            DuaEntity(
                id = 84,
                category = "Morning & Evening",
                title = "Ayat Al-Kursi (Verse of the Throne)",
                arabic = "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ",
                transliteration = "Allahu la ilaha illa Huwal-Hayyul-Qayyum, la ta'khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa'u 'indahu illa bi-idhnih, ya'lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bi-shay'im-min 'ilmihi illa bima sha'a, wasi'a kursiyyuhus-samawati wal-arda, wa la ya'uduhu hifzuhuma, wa Huwal-'Aliyyul-'Azim.",
                translation = "Allah! There is no deity except Him, the Ever-Living, the Sustainer of all existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.",
                translationHausa = "Allah! Babu abin bautawa da gaskiya sai Shi, Mai Rai, Tsayayye mai kula da kowa da komai. Gyangyaɗi ba ya kama Shi, haka ma barci. Shi ke da dukkan abin da ke cikin sammai da abin da ke cikin ƙasa. Wane ne wanda zai iya yin ceto a wurinSa face da izininSa? Ya san abin da ke gabaninsu da abin da ke bayansu, kuma ba su kewaye komai daga iliminSa ba sai da abin da Ya so. KursiyyunSa ya yalwaci sammai da ƙasa, kuma tsare su ba ya gajiyar da Shi, kuma Shi ne Maɗaukaki, Mai Girma.",
                translationYoruba = "Allāhu! Ko si ọlọhun miiran lẹhin Rẹ, Alaye, Olugbe gbogbo nkan duro. Oorun ko n mu U bẹẹ si ni oorun asunparọ ko n gba A. Tirẹ ni ohun gbogbo ti n bẹ ninu awọn ọrun ati ohun gbogbo ti n bẹ ninu ilẹ. Ta ni ẹni naa ti o le ṣiṣẹ ẹbẹ lọdọ Rẹ ayafi pẹlu iyọọda Rẹ? O mọ ohun ti n bẹ niwaju wọn ati ohun ti n bẹ lẹhin wọn, wọn ko si le mọ nkankan ninu imọ Rẹ afi eyi ti O ba fẹ. Itẹ Rẹ fẹlẹ kọja awọn ọrun ati ilẹ, titọju wọn mejeeji ko si n rẹ Ẹ. Oun si ni Oga-jùlọ, Ọba Titobi.",
                translationIgbo = "Chineke! Ọ dịghị chi ọzọ ma e wezụga Ya, Onye Dị Ndụ, Onye Na-elekọta ihe niile. Ụra adịghị ebu Ya ma ọ bụ ụra miri emi. Ọ bụ nke Ya ka ihe niile dị n'eluigwe na n'ụwa bụ. Onye ka ọ bụ nke nwere ike ịrịọrọ Ya arịrịọ ma ọ bụghị site na ikike Ya? Ọ maara ihe dị n'ihu ha na ihe dị n'azụ ha, ha enweghịkwa ike ịghọta ihe ọ bụla n'ihe ọmụma Ya ma e wezụga ihe Ọ chọrọ. Ocheeze Ya sara mbara n'eluigwe na n'ụwa, nchekwa ha adịghịkwa agwụ Ya ike. Ma Ya bụ Onye Kachasị Elu, Onye Kachasị Ukwuu.",
                reference = "Whoever recites this in the morning will be protected until evening, and whoever recites it in the evening will be protected until morning.\nReference: Al-Hakim 1/562, Sahih At-Targhib 1/273."
            ),
            DuaEntity(
                id = 85,
                category = "Morning & Evening",
                title = "Surah Al-Ikhlas, Al-Falaq & An-Nas (Recite 3 times)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ\n\nبِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ\n\nبِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ",
                transliteration = "1. Bismillāhir-Rahmānir-Raheem. Qul Huwallāhu Ahad, Allāhus-Samad, Lam yalid wa lam yoolad, Wa lam yakul-lahoo kufuwan ahad.\n\n2. Bismillāhir-Rahmānir-Raheem. Qul a'oodhu bi-Rabbil-falaq, Min sharri mā khalaq, Wa min sharri ghāsiqin idhā waqab, Wa min sharrin-naffāthāti fil-'uqad, Wa min sharri hāsidin idhā hasad.\n\n3. Bismillāhir-Rahmānir-Raheem. Qul a'oodhu bi-Rabbin-nās, Malikin-nās, Ilāhin-nās, Min sharril-waswāsil-khannās, Alladhee yuwaswisu fee sudoorin-nās, Minal-jinnati wan-nās.",
                translation = "1. Surah Al-Ikhlas: In the name of Allah, Most Gracious, Most Merciful. Say: He is Allah, the One and Only; Allah, the Eternal, Absolute; He begets not, nor is He begotten; And there is none like unto Him.\n\n2. Surah Al-Falaq: In the name of Allah, Most Gracious, Most Merciful. Say: I seek refuge with the Lord of the Dawn, from the mischief of created things; from the mischief of Darkness as it overspreads; from the mischief of those who practise secret arts (blowing into knots / magic); and from the mischief of the envious one as he practises envy.\n\n3. Surah An-Nas: In the name of Allah, Most Gracious, Most Merciful. Say: I seek refuge with the Lord and Cherisher of Mankind, the King (or Ruler) of Mankind, the God of Mankind, from the mischief of the Whisperer (of Evil), who withdraws, who whispers into the hearts of Mankind, among Jinn and among men.",
                translationHausa = "1. Suratul Ikhlas: Da sunan Allah, Mai rahama, Mai jin kai. Ka ce: Shi ne Allah, Makaɗaici. Allah wanda ake nufi da buƙatu (ba Ya buƙatar kowa). Bai haifa ba kuma ba a haife Shi ba. Kuma babu wani da ya zama kishiya ko tamkar Sa.\n\n2. Suratul Falaq: Da sunan Allah, Mai rahama, Mai jin kai. Ka ce: Ina neman tsari da Ubangijin ketowar alfijir (hantsi), daga sharrin abubuwan da Ya halitta, da sharrin dare idan ya yi duhu sosai, da sharrin masu tofi a cikin ƙulli (masu asiri da sihiri), da kuma sharrin mai hassada idan ya yi hassada.\n\n3. Suratun Nas: Da sunan Allah, Mai rahama, Mai jin kai. Ka ce: Ina neman tsari da Ubangijin mutane, Sarkin mutane, Abin bautar mutane, daga sharrin mai rada mai ɓuya (shaidan mai sanya waswasi), wanda yake sanya waswasi a cikin zukatan mutane, daga cikin aljanu da mutane.",
                translationYoruba = "1. Suratul Ikhlas: Ni orukọ Ọlọhun, Ajọkẹ-aiye, Asakẹ-ọrun. Wi pe: Oun ni Allāhu, Ọkanṣoṣo. Allāhu, Asaku-ti. Ko bimọ, a ko si bi I. Ko si si ẹnikẹni ti o jọ Ọ.\n\n2. Suratul Falaq: Ni orukọ Ọlọhun, Ajọkẹ-aiye, Asakẹ-ọrun. Wi pe: Mo wa aabo pẹlu Oluwa afẹmọjumọ, kuro ninu aburu ohun ti O da, ati kuro ninu aburu okunkun nigba ti o ba bo ile, ati kuro ninu aburu awọn ti n fẹ si koko, ati kuro ninu aburu ilara nigba ti o ba n ṣe ilara.\n\n3. Suratun Nas: Ni orukọ Ọlọhun, Ajọkẹ-aiye, Asakẹ-ọrun. Wi pe: Mo wa aabo pẹlu Oluwa awọn eniyan, Ọba awọn eniyan, Ọlọhun awọn eniyan, kuro ninu aburu ẹlẹtan ti o n sa pamọ, ẹni ti n kẹlẹkẹlẹ si ọkan awọn eniyan, lati inu aljannu ati eniyan.",
                translationIgbo = "1. Surah Al-Ikhlas: N'aha Chineke, Onye Amara, Onye Ebere. Kwuo: Ọ bụ Chineke, Onye Nanị Ya, Chineke nke Ihe Niile Na-adabere na Ya. Ọ mụtaghị nwa, a mụtaghịkwa Ya. Ọ dịghịkwa onye yiri Ya.\n\n2. Surah Al-Falaq: N'aha Chineke, Onye Amara, Onye Ebere. Kwuo: Ana m arịọ nchebe n'aka Onye nwe chi ọbụbọ, pụọ n'ihe ọjọọ nke ihe Ọ kere, na n'ihe ọjọọ nke ọchịchịrị mgbe ọ bịara, na n'ihe ọjọọ nke ndị na-efụ n'eriri a kegidere ekegi, na n'ihe ọjọọ nke onye anyaụfụ mgbe ọ na-enwere anyaụfụ.\n\n3. Surah An-Nas: N'aha Chineke, Onye Amara, Onye Ebere. Kwuo: Ana m arịọ nchebe n'aka Onye nwe mmadụ, Eze mmadụ, Chi nke mmadụ, pụọ n'ihe ọjọọ nke onye na-atamu ntamu na-ezo ezo, onye na-atamu ntamu n'ime obi mmadụ, n'ime ndị jinn na mmadụ.",
                reference = "Whoever recites them three times in the morning and evening, they will suffice him against everything.\nReference: Abu Dawud 4/322, At-Tirmidhi 5/567."
            ),
            DuaEntity(
                id = 86,
                category = "Morning & Evening",
                title = "Morning Supplication (Asbahna wa Asbahal-Mulku Lillah)",
                arabic = "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ",
                transliteration = "Asbahna wa asbahal-mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa Huwa 'ala kulli shay'in Qadir. Rabbi as'aluka khayra ma fi hadhal-yawmi wa khayra ma ba'dah, wa a'udhu bika min sharri ma fi hadhal-yawmi wa sharri ma ba'dah, Rabbi a'udhu bika minal-kasali wa su'il-kibar, Rabbi a'udhu bika min 'adhabin fin-nari wa 'adhabin fil-qabr.",
                translation = "We have reached the morning and at this very time all sovereignty belongs to Allah, and all praise is for Allah. There is no deity worthy of worship except Allah alone, who has no partner. To Him belongs all sovereignty and to Him belongs all praise, and He is over all things capable. My Lord, I ask You for the good of what is in this day and the good of what follows it, and I seek refuge in You from the evil of what is in this day and the evil of what follows it. My Lord, I seek refuge in You from laziness and the helplessness of old age. My Lord, I seek refuge in You from punishment in the Hellfire and punishment in the grave.",
                translationHausa = "Muka wayi gari kuma mulki ya wayi gari na Allah ne, kuma dukkan godiya ta tabbata ga Allah. Babu abin bautawa da gaskiya sai Allah Shi kaɗai ba Ya da abokin tarayya. Mulki Nashi ne kuma godiya Ta tabbata a gare Shi, kuma Shi a kan kowane abu Mai iko ne. Ya Ubangijina! Ina roƙonKa alherin abin da ke cikin wannan yini da alherin abin da ke bayansa, kuma ina neman tsari da Kai daga sharrin abin da ke cikin wannan yini da sharrin abin da ke bayansa. Ya Ubangijina! Ina neman tsari da Kai daga lalaci da muguwar tsufa (gaza yin aiki). Ya Ubangijina! Ina neman tsari da Kai daga azaba a cikin wuta da azaba a cikin kabari.",
                translationYoruba = "A ti bọ si owurọ ati pe ijọba bọ si ti Allāhu, gbogbo ọpẹ si jẹ ti Allāhu. Ko si ọlọhun miiran bikoṣe Allāhu nikan, Ko ni orogun. Tirẹ ni ijọba ati ọpẹ, O si le ṣe ohun gbogbo. Oluwa mi, mo n bọ lọwọ Rẹ fun oore ohun ti n bẹ ninu ọjọ oni ati oore ohun ti o n bọ lẹhin rẹ, mo si n wa aabo lọwọ Rẹ kuro ninu aburu ohun ti n bẹ ninu ọjọ oni ati aburu ohun ti o n bọ lẹhin rẹ. Oluwa mi, mo n wa aabo lọwọ Rẹ kuro ninu ọlẹ ati arugbo buburu. Oluwa mi, mo n wa aabo lọwọ Rẹ kuro ninu iya Ina ati iya inu saare.",
                translationIgbo = "Anyị erutela ụtụtụ ma n'oge a, ọchịchị niile bụ nke Chineke, Onye nwe ụwa niile. Otuto niile dịrị Chineke. Ọ dịghị chi kwesịrị ofufe ma e wezụga Chineke nanị Ya, Onye na-enweghị onye ibe. Nke Ya bụ ọchịchị niile na otuto niile, Ọ pụkwara ime ihe niile. Onye nwe m, ana m arịọ Gị maka ihe ọma dị n'ụbọchị taa na ihe ọma na-eso ya, ana m arịọkwa nchebe Gị pụọ n'ihe ọjọọ dị n'ụbọchị taa na ihe ọjọọ na-eso ya. Onye nwe m, ana m arịọ nchebe Gị pụọ n'ịdị umengwu na ahụhụ nke agadi. Onye nwe m, ana m arịọ nchebe Gị pụọ n'ahụhụ dị n'ọkụ ala mmụọ na ahụhụ dị n'ili.",
                reference = "Muslim 4/2088. Recited in the morning."
            ),
            DuaEntity(
                id = 87,
                category = "Morning & Evening",
                title = "Evening Supplication (Amsayna wa Amsal-Mulku Lillah)",
                arabic = "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ",
                transliteration = "Amsayna wa amsal-mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa Huwa 'ala kulli shay'in Qadir. Rabbi as'aluka khayra ma fi hadhihil-laylati wa khayra ma ba'daha, wa a'udhu bika min sharri ma fi hadhihil-laylati wa sharri ma ba'daha, Rabbi a'udhu bika minal-kasali wa su'il-kibar, Rabbi a'udhu bika min 'adhabin fin-nari wa 'adhabin fil-qabr.",
                translation = "We have reached the evening and at this very time all sovereignty belongs to Allah, and all praise is for Allah. There is no deity worthy of worship except Allah alone, who has no partner. To Him belongs all sovereignty and to Him belongs all praise, and He is over all things capable. My Lord, I ask You for the good of what is in this night and the good of what follows it, and I seek refuge in You from the evil of what is in this night and the evil of what follows it. My Lord, I seek refuge in You from laziness and the helplessness of old age. My Lord, I seek refuge in You from punishment in the Hellfire and punishment in the grave.",
                translationHausa = "Muka yammata kuma mulki ya yammata na Allah ne, kuma dukkan godiya ta tabbata ga Allah. Babu abin bautawa da gaskiya sai Allah Shi kaɗai ba Ya da abokin tarayya. Mulki Nashi ne kuma godiya Ta tabbata a gare Shi, kuma Shi a kan kowane abu Mai iko ne. Ya Ubangijina! Ina roƙonKa alherin abin da ke cikin wannan dare da alherin abin da ke bayansa, kuma ina neman tsari da Kai daga sharrin abin da ke cikin wannan dare da sharrin abin da ke bayansa. Ya Ubangijina! Ina neman tsari da Kai daga lalaci da muguwar tsufa. Ya Ubangijina! Ina neman tsari da Kai daga azaba a cikin wuta da azaba a cikin kabari.",
                translationYoruba = "A ti bọ si irọlẹ ati pe ijọba bọ si ti Allāhu, gbogbo ọpẹ si jẹ ti Allāhu. Ko si ọlọhun miiran bikoṣe Allāhu nikan, Ko ni orogun. Tirẹ ni ijọba ati ọpẹ, O si le ṣe ohun gbogbo. Oluwa mi, mo n bọ lọwọ Rẹ fun oore ohun ti n bẹ ninu alẹ oni ati oore ohun ti o n bọ lẹhin rẹ, mo si n wa aabo lọwọ Rẹ kuro ninu aburu ohun ti n bẹ ninu alẹ oni ati aburu ohun ti o n bọ lẹhin rẹ. Oluwa mi, mo n wa aabo lọwọ Rẹ kuro ninu ọlẹ ati arugbo buburu. Oluwa mi, mo n wa aabo lọwọ Rẹ kuro ninu iya Ina ati iya inu saare.",
                translationIgbo = "Anyị erutela anyasị ma n'oge a, ọchịchị niile bụ nke Chineke, Onye nwe ụwa niile. Otuto niile dịrị Chineke. Ọ dịghị chi kwesịrị ofufe ma e wezụga Chineke nanị Ya, Onye na-enweghị onye ibe. Nke Ya bụ ọchịchị niile na otuto niile, Ọ pụkwara ime ihe niile. Onye nwe m, ana m arịọ Gị maka ihe ọma dị n'abalị a na ihe ọma na-eso ya, ana m arịọkwa nchebe Gị pụọ n'ihe ọjọọ dị n'abalị a na ihe ọjọọ na-eso ya. Onye nwe m, ana m arịọ nchebe Gị pụọ n'ịdị umengwu na ahụhụ nke agadi. Onye nwe m, ana m arịọ nchebe Gị pụọ n'ahụhụ dị n'ọkụ ala mmụọ na ahụhụ dị n'ili.",
                reference = "Muslim 4/2088. Recited in the evening."
            ),
            DuaEntity(
                id = 88,
                category = "Morning & Evening",
                title = "Morning Invocation (Allahumma Bika Asbahna)",
                arabic = "اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ",
                transliteration = "Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namutu, wa ilaykan-nushur.",
                translation = "O Allah, by You we enter the morning and by You we enter the evening, by You we live and by You we die, and to You is the final return.",
                translationHausa = "Ya Allah, da ikonKa muka wayi gari, kuma da ikonKa muka yammata, da ikonKa muke rayuwa kuma da ikonKa muke mutuwa, kuma zuwa gare Ka ne tashi yake.",
                reference = "At-Tirmidhi 5/466. Recited in the morning."
            ),
            DuaEntity(
                id = 89,
                category = "Morning & Evening",
                title = "Evening Invocation (Allahumma Bika Amsayna)",
                arabic = "اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ",
                transliteration = "Allahumma bika amsayna, wa bika asbahna, wa bika nahya, wa bika namutu, wa ilaykal-masir.",
                translation = "O Allah, by You we enter the evening and by You we enter the morning, by You we live and by You we die, and to You is the final return.",
                translationHausa = "Ya Allah, da ikonKa muka yammata, kuma da ikonKa muka wayi gari, da ikonKa muke rayuwa kuma da ikonKa muke mutuwa, kuma zuwa gare Ka ne komawa take.",
                reference = "At-Tirmidhi 5/466. Recited in the evening."
            ),
            DuaEntity(
                id = 90,
                category = "Morning & Evening",
                title = "Evening Protection from Evil (Recite 3 times)",
                arabic = "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ",
                transliteration = "A'udhu bikalimatil-lahit-tammati min sharri ma khalaq.",
                translation = "I seek refuge in the perfect words of Allah from the evil of what He has created.",
                translationHausa = "Ina neman tsari da cikakkun kalmomin Allah daga sharrin abin da Ya halitta.",
                reference = "Whoever recites this three times in the evening will not be harmed by anything that night.\nReference: At-Tirmidhi 3/187, Ahmad 2/290."
            ),
            DuaEntity(
                id = 91,
                category = "Morning & Evening",
                title = "Sufficient is Allah for Me (Recite 7 times)",
                arabic = "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ",
                transliteration = "Hasbiyallahu la ilaha illa Huwa 'alayhi tawakkaltu wa Huwa Rabbul-'Arshil-'Azim.",
                translation = "Allah is sufficient for me. There is no deity except Him. On Him I rely, and He is the Lord of the Mighty Throne.",
                translationHausa = "Allah Ya wadatar mini, babu abin bautawa da gaskiya sai Shi, gare Shi na dogara kuma Shi ne Ubangijin Arshi mai girma.",
                reference = "Whoever recites this seven times in the morning and evening, Allah will spare him what worries him.\nReference: Abu Dawud 4/321."
            ),
            DuaEntity(
                id = 92,
                category = "Morning & Evening",
                title = "Supplication for Well-being & Protection (Recite 3 times)",
                arabic = "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ",
                transliteration = "Allahumma 'afini fi badani, Allahumma 'afini fi sam'i, Allahumma 'afini fi basari, la ilaha illa Ant. Allahumma inni a'udhu bika minal-kufri wal-faqr, wa a'udhu bika min 'adhabil-qabr, la ilaha illa Ant.",
                translation = "O Allah, grant me health in my body. O Allah, grant me health in my hearing. O Allah, grant me health in my sight. There is no deity except You. O Allah, I seek refuge in You from disbelief and poverty, and from the punishment of the grave. There is no deity except You.",
                translationHausa = "Ya Allah, Ka ba wa jikina lafiya. Ya Allah, Ka ba wa ji na lafiya. Ya Allah, Ka ba wa gani na lafiya. Babu abin bautawa da gaskiya sai Kai. Ya Allah, ina neman tsari da Kai daga kafirci da talauci, kuma ina neman tsari da Kai daga azabar kabari. Babu abin bautawa da gaskiya sai Kai.",
                reference = "Abu Dawud 4/324, Ahmad 5/42."
            ),
            DuaEntity(
                id = 93,
                category = "Morning & Evening",
                title = "Praising Allah 100 Times (Subhanallahi wa Bihamdihi)",
                arabic = "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ",
                transliteration = "Subhanallahi wa bihamdihi.",
                translation = "Glory is to Allah and praise is to Him (100 times).",
                translationHausa = "Tsarki ya tabbata ga Allah tare da godiyarSa (sau 100).",
                reference = "Whoever recites this one hundred times in the morning and evening, no one will bring anything better on the Day of Resurrection.\nReference: Sahih Muslim 4/2071."
            ),
            DuaEntity(
                id = 94,
                category = "Morning & Evening",
                title = "Invocation for Relief & Guidance (Ya Hayyu Ya Qayyum)",
                arabic = "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ",
                transliteration = "Ya Hayyu Ya Qayyum bi-rahmatika astaghib, aslih li sha'ni kullahu wa la takilni ila nafsi tarfata 'ayn.",
                translation = "O Ever-Living One, O Sustainer, by Your mercy I seek help. Rectify for me all of my affairs and do not leave me to myself even for the blink of an eye.",
                translationHausa = "Ya Mai Rai Ya Tsayayye, da rahamarKa nake neman agaji, Ka gyara mini al'amurana baki ɗaya kuma kada Ka ragamar da ni zuwa ga kaina ko da ƙiftawar ido guda ne.",
                reference = "Al-Hakim 1/545, Sahih At-Targhib 1/273."
            ),
            DuaEntity(
                id = 95,
                category = "Morning & Evening",
                title = "Extensive Praise of Allah (Recite 3 times in Morning)",
                arabic = "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ",
                transliteration = "Subhanallahi wa bihamdihi, 'adada khalqihi, wa rida nafsihi, wa zinata 'arshihi, wa midada kalimatih.",
                translation = "Glory is to Allah and praise is to Him, by the number of His creation and His pleasure and the weight of His Throne and the ink of His words (3 times).",
                translationHausa = "Tsarki ya tabbata ga Allah tare da godiyarSa, gwargwadon adadin halittarSa, da yardar kansa, da nauyin arshinSa, da adadin kalmominSa (sau 3).",
                reference = "Sahih Muslim 4/2090. Recited 3 times in the morning."
            ),
            DuaEntity(
                id = 96,
                category = "Fasting & Ramadan",
                title = "Dua Upon Breaking the Fast (Iftar)",
                arabic = "ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ",
                transliteration = "Dhahaba adh-dhama'u wabtallatil-'urooqu wa thabatal-ajru in sha' Allah.",
                translation = "The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.",
                translationHausa = "Kishirwa ta tafi, jijiyoyi sun jika, kuma lada ya tabbata da yardar Allah.",
                translationYoruba = "Ongbẹ ti lọ, awọn iṣan ti tutu, ati pe ere ti fidimulẹ pẹlu iyọọda Allāhu.",
                translationIgbo = "Akpịrị ịkpọ nkụ agwụla, akwara niile agbaala mmiri, ma ụgwọ ọrụ e mezuola ma Chineke kwere.",
                reference = "Sunan Abi Dawud 2357, Ad-Daraqutni 2/185. Authentic Hadith."
            ),
            DuaEntity(
                id = 97,
                category = "Fasting & Ramadan",
                title = "Dua When Breaking Fast with Others",
                arabic = "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ",
                transliteration = "Aftara 'indakumus-saa'imuna, wa akala ta'amakumul-abrar, wa sallat 'alaykumul-mala'ikah.",
                translation = "May the fasting break their fast in your home, may the pious eat your food, and may the angels pray for you.",
                translationHausa = "Masu azumi su sha ruwa a wajenku, mutanen kirki su ci abincinku, kuma mala'iku su yi muku addu'a.",
                translationYoruba = "Ki awọn ti n gba aawe ba yin tu aawe, ki awọn olododo jẹ ounjẹ yin, ki awọn mọlaika si gbadura fun yin.",
                translationIgbo = "Ka ndị na-ebu ọnụ mechie ọnụ n'ụlọ gị, ka ndị ezi omume rie nri gị, ma ka ndị mmụọ ozi kpegara gị ekpere.",
                reference = "Sunan Abi Dawud 3854, Sunan Ibn Majah 1749."
            ),
            DuaEntity(
                id = 98,
                category = "Fasting & Ramadan",
                title = "Dua Upon Sighting the Crescent Moon",
                arabic = "اللَّهُ أَكْبَرُ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ، وَالسَّلَامَةِ وَالْإِسْلَامِ، وَالتَّوْفِيقِ لِمَا تُحِبُّ وَتَرْضَى، رَبُّنَا وَرَبُّكَ اللَّهُ",
                transliteration = "Allahu Akbar, Allahumma ahillahu 'alayna bil-amni wal-iman, was-salamati wal-Islam, wat-tawfiqi lima tuhibbu wa tarda, Rabbuna wa Rabbukallah.",
                translation = "Allah is the Greatest. O Allah, bring this moon upon us with peace, faith, safety, and Islam, and guidance to what You love and are pleased with. Our Lord and your Lord is Allah.",
                translationHausa = "Allah ne Mafi Girma. Ya Allah, Ka fito mana da wannan wata da aminci da imani, da lafiya da Musulunci, da dacewa da abin da Kake so Kake yarda da shi. Ubangijinmu kuma Ubangijinki Allah ne.",
                translationYoruba = "Allāhu tobi jùlọ. Allāhu, fi oṣù titun yii bọ wa pẹlu alaafia ati igbagbọ, ati aabo ati Islam, ati aṣeyọri ninu ohun ti O fẹ ti O si yọọda si. Oluwa wa ati Oluwa rẹ ni Allāhu.",
                translationIgbo = "Chineke kachasị ukwuu. Chineke, wetara anyị ọnwa ọhụrụ a na udo na okwukwe, na nchekwa na Islam, na nduzi n'ihe masịrị Gị. Onye nwe anyị na Onye nwe gị bụ Chineke.",
                reference = "Jami' at-Tirmidhi 3451, Sunan ad-Darimi 1687."
            ),
            DuaEntity(
                id = 99,
                category = "Fasting & Ramadan",
                title = "Dua for Laylatul Qadr (Night of Power)",
                arabic = "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي",
                transliteration = "Allahumma innaka 'Afuwwun tuhibbul-'afwa fa'fu 'anni.",
                translation = "O Allah, You are Most Forgiving and You love forgiveness, so forgive me.",
                translationHausa = "Ya Allah, lallai Kai Mai yafiya ne Kuma Kana son yafiya, don haka Ka yafe mini.",
                translationYoruba = "Allāhu, dajudaju Iwọ ni Alaforijin, O n fẹ idariji, nitorina dariji mi.",
                translationIgbo = "Chineke, n'ezie Gị bụ Onye Na-agbaghara mmehie ma hụ mgbaghara n'anya, ya mere gbaghara m.",
                reference = "Jami' at-Tirmidhi 3513, Sunan Ibn Majah 3850."
            ),
            DuaEntity(
                id = 100,
                category = "Fasting & Ramadan",
                title = "When Insulted While Fasting",
                arabic = "إِنِّي صَائِمٌ، إِنِّي صَائِمٌ",
                transliteration = "Inni saa'imun, inni saa'im.",
                translation = "I am fasting, I am fasting.",
                translationHausa = "Ni mai azumi ne, ni mai azumi ne.",
                translationYoruba = "Mo n gba aawe, mo n gba aawe.",
                translationIgbo = "M na-ebu ọnụ, m na-ebu ọnụ.",
                reference = "Sahih Al-Bukhari 1894, Sahih Muslim 1151."
            ),
            DuaEntity(
                id = 101,
                category = "Hajj & Umrah",
                title = "Introduction: Core Pillars & Virtues of Hajj & Umrah",
                arabic = "وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا ۚ وَمَن كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ عَنِ الْعَالَمِينَ — الْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ",
                transliteration = "Wa lillahi 'alan-naasi hijjul-bayti manistata'a ilayhi sabeela, wa man kafara fa innallaha ghaniyyun 'anil-'alameen — Al-Hajjul-mabrooru laysa lahu jazaa'un illal-Jannah.",
                translation = "Introduction to Hajj & Umrah: Hajj is the 5th pillar of Islam, obligatory once in a lifetime for every financially and physically capable Muslim. The Prophet (ﷺ) said: 'An accepted Hajj (Hajj Mabrur) has no reward except Paradise' and 'Whoever performs Hajj without obscenity or sin returns as pure as the day his mother bore him.' The 4 Pillars of Hajj: 1) Ihram (Intention), 2) Standing at Arafah, 3) Tawaf al-Ifadah, 4) Sa'ee between Safa and Marwah.",
                translationHausa = "Gabatarwa kan Aikin Hajji da Umra: Aikin Hajji shi ne rukuni na biyar na Musulunci, wajibi ne sau daya a rayuwa ga duk musulmi mai iko. Manzon Allah (ﷺ) ya ce: 'Hajji karbabbiya ba ta da sakamako face Aljanna' kuma 'Wanda ya yi Hajji ba tare da alfasha ko sabon Allah ba zai dawo kamar ranar da mahaifiyarsa ta haife shi'. Rukunai 4 na Hajji: 1) Daure Harami da Niyya, 2) Tsayuwar Arfa, 3) Dawafin Ifada a Ka'aba, 4) Sa'ayi tsakanin Safa da Marwa. (Wadannan idan aka bar daya ba Hajji).",
                translationYoruba = "Iṣaaju lori Hajj ati Umrah: Hajj jẹ ọwọ kẹrin ti Islam. Awọn ọwọ mẹrin ti Hajj: 1) Ihram, 2) Iduro ni Arafah, 3) Tawaf Ifadah, 4) Sa'ee laarin Safa ati Marwa.",
                translationIgbo = "Mmalite nke Hajj na Umrah: Hajj bụ ogidi nke ise na Islam. Ogidi 4 nke Hajj: 1) Ihram, 2) Ikwụ n'Arafah, 3) Tawaf Ifadah, 4) Sa'ee.",
                reference = "Holy Quran, Surah Ali 'Imran 3:97, Sahih al-Bukhari 1773, Sahih Muslim 1350."
            ),
            DuaEntity(
                id = 102,
                category = "Hajj & Umrah",
                title = "The 3 Types of Hajj (Tamattu', Qiran, and Ifrad)",
                arabic = "فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ",
                transliteration = "Faman tamatta'a bil-'umrati ilal-hajji famastaysara minal-hady.",
                translation = "The 3 Types of Hajj: 1) Tamattu' (Most Recommended): Performing Umrah first during the Hajj months, exiting Ihram completely into normal clothes, then entering a new Ihram for Hajj on the 8th of Dhul-Hijjah (Sacrifice required). 2) Qiran: Entering Ihram for both Umrah and Hajj together without exiting Ihram in between (Sacrifice required). 3) Ifrad: Entering Ihram for Hajj only without Umrah (No sacrifice required).",
                translationHausa = "Nau'o'in Hajji guda uku: 1) Tamattu' (Shi ne wanda ya fi falala ga wanda bai tafi da hadaya ba): Yin Umra a watannin Hajji, a kwance harami a sanya kaya na yau da kullum, sannan a sake daure wani sabon harami na Hajji a ranar 8 ga Dhul-Hijjah (wajibi ne a yanka hadaya). 2) Qiran: Hadawa tsakanin Umra da Hajji a harami daya ba tare da kwancewa ba har sai ranar Sallah (wajibi ne a yanka hadaya). 3) Ifrad: Yin aikin Hajji kadai ba tare da Umra ba (ba wajibi ne a yanka hadaya ba).",
                translationYoruba = "Awọn oriṣi mẹta ti Hajj: 1) Tamattu' (Umrah tẹle Hajj), 2) Qiran (Hapọ Umrah ati Hajj), 3) Ifrad (Hajj nikan).",
                translationIgbo = "Ụdị 3 nke Hajj: 1) Tamattu', 2) Qiran, 3) Ifrad.",
                reference = "Holy Quran, Surah Al-Baqarah 2:196, Sahih Muslim 1218 (Hadith of Jabir)."
            ),
            DuaEntity(
                id = 103,
                category = "Hajj & Umrah",
                title = "How to Perform Umrah Step-by-Step (The 4 Essential Stages)",
                arabic = "وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ",
                transliteration = "Wa atimmul-hajja wal-'umrata lillah.",
                translation = "The 4 Essential Steps of Umrah: 1) Ihram & Niyyah at the Miqat with Talbiyah. 2) Tawaf: 7 anti-clockwise circuits around the Ka'aba starting from the Black Stone, followed by 2 rak'ahs behind Maqam Ibrahim and drinking Zamzam. 3) Sa'ee: 7 laps between Mount Safa and Mount Marwa starting at Safa and ending at Marwa. 4) Halq or Taqseer: Shaving head (men) or trimming fingertip length of hair (men & women). This completes the Umrah and lifts all prohibitions.",
                translationHausa = "Koyon Aikin Umra Daki-daki (Matakai 4): 1) Harami da Niyya a Miqati tare da karanta Talbiya. 2) Dawafi: Zagaye Ka'aba sau 7 a hannun hagu farawa daga Hajarul Aswad, sannan sallar raka'a 2 a bayan Maqamu Ibrahim da shan ruwan Zamzam. 3) Sa'ayi: Tafiya tsakanin Safa da Marwa sau 7 (farawa daga Safa gamawa a Marwa). 4) Aske kai ko rage gashi (Halq ko Taqseer). Da wannan an kammala Umra, komai ya halatta.",
                translationYoruba = "Awọn igbesẹ mẹrin ti Umrah: 1) Ihram ni Miqat, 2) Tawaf yika Ka'abah, 3) Sa'ee laarin Safa ati Marwa, 4) Fari tabi ge irun.",
                translationIgbo = "Nzọụkwụ 4 nke Umrah: 1) Ihram na Miqat, 2) Tawaf gburugburu Ka'aba, 3) Sa'ee n'etiti Safa na Marwa, 4) Ịkpụ ntutu.",
                reference = "Holy Quran, Surah Al-Baqarah 2:196, Sahih al-Bukhari 1773."
            ),
            DuaEntity(
                id = 104,
                category = "Hajj & Umrah",
                title = "The Great Talbiyah of Hajj & Umrah",
                arabic = "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ",
                transliteration = "Labbayk Allahumma labbayk, labbayka la shareeka laka labbayk, innal-hamda wan-ni'mata laka wal-mulk, la shareeka lak.",
                translation = "Here I am at Your service, O Allah, here I am. Here I am, You have no partner, here I am. Truly, all praise, grace, and sovereignty belong to You. You have no partner. (Recite frequently with raised voice for men from entering Ihram until stoning Jamrat al-Aqaba on Eid day).",
                translationHausa = "Ga ni nan Ya Allah ga ni nan. Ga ni nan ba Ka da abokin tarayya ga ni nan. Lallai yabo da ni'ima da mulki Naka ne, ba Ka da abokin tarayya. (Ana yawaita karantawa da daukaka murya ga maza tun daga daure harami har zuwa lokacin da za a fara jifan Jamratul Aqaba ranar Sallah).",
                translationYoruba = "Emi wa ni iṣẹ Rẹ, Allāhu, emi wa. Emi wa, Iwọ ko ni orogun, emi wa. Dajudaju gbogbo ọpẹ, idera ati ijọba jẹ Tirẹ, O ko ni orogun.",
                translationIgbo = "Ana m abịa n'ozi Gị, Chineke, ana m abịa. Ana m abịa, Gị enweghị onye ibe, ana m abịa. N'ezie, otuto niile, ngọzi na ike bụ nke Gị. Gị enweghị onye ibe.",
                reference = "Sahih al-Bukhari 1549, Sahih Muslim 1184."
            ),
            DuaEntity(
                id = 105,
                category = "Marriage & Family",
                title = "Congratulating Newlyweds (Marriage Blessing)",
                arabic = "بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ",
                transliteration = "Barakallahu laka, wa baraka 'alayka, wa jama'a baynakuma fee khayr.",
                translation = "May Allah bless you, and shower His blessings upon you, and unite you both in goodness.",
                translationHausa = "Allah Ya yi maka albarka, Ya kuma saukar da albarkarSa a kanku, Ya kuma hada tsakaninku a cikin alheri.",
                translationYoruba = "Ki Allāhu bukun fun ọ, ki O si bukun si ọ lori, ki O si darapọ mọ yin mejeeji ninu oore.",
                translationIgbo = "Ka Chineke gọzie gị, ma wụsa ngọzi Ya n'elu gị, ma jikọta unu abụọ n'ezi ihe.",
                reference = "Sunan Abi Dawud 2130, Jami' at-Tirmidhi 1091."
            ),
            DuaEntity(
                id = 106,
                category = "Marriage & Family",
                title = "Supplication of the Groom / Buying a Mount",
                arabic = "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ",
                transliteration = "Allahumma inni as'aluka khayraha wa khayra ma jabaltaha 'alayh, wa a'udhu bika min sharriha wa sharri ma jabaltaha 'alayh.",
                translation = "O Allah, I ask You for the good in her and the good with which You created her, and I seek refuge in You from the evil in her and the evil with which You created her.",
                translationHausa = "Ya Allah, lallai ina rokonKa alherinta da alherin dabi'ar da Ka halicce ta a kanta, kuma ina neman tsari da Kai daga sharrinta da sharrin dabi'ar da Ka halicce ta a kanta.",
                translationYoruba = "Allāhu, mo n bọ lọwọ Rẹ fun oore rẹ ati oore ti O fi da a le lori, mo si n wa aabo lọwọ Rẹ kuro ninu aburu rẹ ati aburu ti O fi da a le lori.",
                translationIgbo = "Chineke, ana m arịọ Gị maka ihe ọma dị n'ime ya na ezi agwa Gị kere ya na ya, ana m arịọ nchebe Gị pụọ n'ihe ọjọọ dị n'ime ya.",
                reference = "Sunan Abi Dawud 2160, Sunan Ibn Majah 1918."
            ),
            DuaEntity(
                id = 107,
                category = "Marriage & Family",
                title = "Dua for Parents (Birr al-Walidayn)",
                arabic = "رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا",
                transliteration = "Rabbir-hamhuma kama rabbayani sagheera.",
                translation = "My Lord, have mercy upon them as they brought me up when I was small.",
                translationHausa = "Ya Ubangijina! Ka yi musu rahama kamar yadda suka rene ni ina karami.",
                translationYoruba = "Oluwa mi! Ṣe aanu fun awọn mejeeji gẹgẹ bi wọn ti tọ mi ni kekere.",
                translationIgbo = "Onye nwe m, meere ha ebere dịka ha si zụọ m mgbe m bụ obere nwatakịrị.",
                reference = "Holy Quran, Surah Al-Isra 17:24."
            ),
            DuaEntity(
                id = 108,
                category = "Good Manners",
                title = "Gratitude to Someone Doing a Favor (Jazakallahu Khayran)",
                arabic = "جَزَاكَ اللَّهُ خَيْرًا",
                transliteration = "Jazakallahu khayran.",
                translation = "May Allah reward you with good.",
                translationHausa = "Allah Ya saka maka da alheri.",
                translationYoruba = "Ki Allāhu san ẹsan rere fun ọ.",
                translationIgbo = "Ka Chineke kwụọ gị ụgwọ ọma.",
                reference = "The Prophet (ﷺ) said: 'Whoever says Jazakallahu Khayran to the one who did him a favor has excelled in praise.'\nReference: Jami' at-Tirmidhi 2035."
            ),
            DuaEntity(
                id = 109,
                category = "Greetings & Social",
                title = "To Someone Saying 'I Love You for Allah's Sake'",
                arabic = "أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ",
                transliteration = "Ahabbakalladhee ahbabtanee lahu.",
                translation = "May He for whose sake you love me, also love you.",
                translationHausa = "Wanda kake so na dominsa Shi ma Ya so ka.",
                translationYoruba = "Ki Ẹni ti o n fẹ mi nitori Rẹ fẹran iwọ naa.",
                translationIgbo = "Ka Onye ị hụrụ m n'anya n'ihi Ya hụkwa gị n'anya.",
                reference = "Sunan Abi Dawud 5125."
            ),
            DuaEntity(
                id = 110,
                category = "Visiting the Sick",
                title = "Dua for Pain in the Body (Ruqyah of Self)",
                arabic = "بِاسْمِ اللَّهِ (ثَلَاثًا)، أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ (سَبْعَ مَرَّاتٍ)",
                transliteration = "Bismillah (3 times), A'udhu bi'izzatillahi wa qudratihi min sharri ma ajidu wa uhadhiru (7 times).",
                translation = "In the Name of Allah (3 times). I seek refuge in the Might and Power of Allah from the evil of what I feel and fear (7 times).",
                translationHausa = "Da sunan Allah (sau 3). Ina neman tsari da buwayar Allah da ikonSa daga sharrin abin da nake ji da wanda nake ji masa tsoro (sau 7).",
                translationYoruba = "Ni orukọ Allāhu (ẹẹmẹta). Mo wa aabo pẹlu ọla ati agbara Allāhu kuro ninu aburu ohun ti mo n lero ti mo si n bẹru (ẹẹmeje).",
                translationIgbo = "N'aha Chineke (ugboro 3). Ana m arịọ nchebe n'ịdị ebube na ike Chineke pụọ n'ihe mgbu m na-enwe na ihe m na-atụ egwu (ugboro 7).",
                reference = "Put your hand on the place where you feel pain in your body and say this.\nReference: Sahih Muslim 2202."
            ),
            DuaEntity(
                id = 111,
                category = "Protection & Evil Eye",
                title = "Upon Hearing Rooster, Donkey or Barking of Dogs",
                arabic = "إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ، وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيْطَانِ",
                transliteration = "Idha sami'tum siyaahad-diyakati fas'alullaha min fadlih, wa idha sami'tum naheeqal-himari fata'awwadhoo billahi minash-shaytan.",
                translation = "When you hear a rooster crow, ask Allah of His bounty (for it saw an angel). When you hear a donkey bray, seek refuge in Allah from Satan (for it saw a devil).",
                translationHausa = "Idan kuka ji zakara yana cara to ku roki Allah falalarSa (domin ya ga mala'ika). Idan kuma kuka ji jakai yana kuka to ku nemi tsari da Allah daga shaidan (domin ya ga shaidan).",
                translationYoruba = "Nigbati ẹ ba gbọ akukọ ti n kọ, ẹ bẹ Allāhu fun oore Rẹ. Nigbati ẹ ba gbọ kẹkẹ ketekete, ẹ wa aabo pẹlu Allāhu kuro lọwọ Eṣu.",
                translationIgbo = "Mgbe ị nụrụ akwa ọkụkọ, rịọ Chineke maka amara Ya. Mgbe ị nụrụ ịgba ịnyịnya ibu, rịọ nchebe Chineke pụọ na Setan.",
                reference = "Sahih Al-Bukhari 3303, Sahih Muslim 2729."
            ),
            DuaEntity(
                id = 112,
                category = "Travel & Home",
                title = "Traveler's Supplication for the Resident",
                arabic = "أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ",
                transliteration = "Astawdi'ukumullahal-ladhi la tadi'u wada'i'uh.",
                translation = "I place you in the trust of Allah, whose trusts are never lost.",
                translationHausa = "Ina bar ku a karkashin amana da tsaron Allah, Wanda amanarSa ba ta taba salwanta.",
                translationYoruba = "Mo fi yin le Allāhu lọwọ, Ẹni ti awọn ohun ti A fi le lọwọ ko le sọnu laelae.",
                translationIgbo = "Ana m ahapụ gị n'aka nlekọta Chineke, Onye ihe a tụkwasịrị n'aka Ya na-adịghị efu efu.",
                reference = "Musnad Ahmad 2/403, Sunan Ibn Majah 2825."
            ),
            DuaEntity(
                id = 113,
                category = "Travel & Home",
                title = "Resident's Supplication for the Traveler",
                arabic = "أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ",
                transliteration = "Astawdi'ullaha deenaka, wa amanataka, wa khawatima 'amalik.",
                translation = "I place in the trust of Allah your religion, your commitments, and the outcome of your deeds.",
                translationHausa = "Ina damka wa Allah addininka, da amanarka, da kuma karshen ayyukanka.",
                translationYoruba = "Mo fi ẹsin rẹ, amana rẹ, ati ipari awọn iṣẹ rẹ le Allāhu lọwọ.",
                translationIgbo = "Ana m ahapụ okpukpe gị, ntụkwasị obi gị na ngwụcha ọrụ gị n'aka Chineke.",
                reference = "Jami' at-Tirmidhi 3443, Sunan Abi Dawud 2600."
            ),
            DuaEntity(
                id = 114,
                category = "Travel & Home",
                title = "Supplication Upon Returning from Travel",
                arabic = "آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ",
                transliteration = "Aayiboona, taa'iboona, 'aabidoona, li-Rabbina haamidoon.",
                translation = "We return, repenting, worshipping, and praising our Lord.",
                translationHausa = "Muna masu dawowa, masu tuba, masu bauta, ga Ubangijinmu muna masu godiya.",
                translationYoruba = "A n pada bọ, a n ronupiwada, a n jọsin, a n yin Oluwa wa.",
                translationIgbo = "Anyị na-alọta, na-echegharị, na-efe ofufe, ma na-enye Onye nwe anyị ekele.",
                reference = "Sahih Muslim 1342."
            ),
            DuaEntity(
                id = 115,
                category = "Repentance & Seeking Forgiveness",
                title = "Comprehensive Forgiveness (Astaghfirullahal-'Azeem)",
                arabic = "أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ",
                transliteration = "Astaghfirullahal-'Azimalladhi la ilaha illa Huwal-Hayyul-Qayyumu wa atubu ilayh.",
                translation = "I seek forgiveness from Allah the Almighty, there is no deity except Him, the Ever-Living, the Sustainer, and I repent unto Him.",
                translationHausa = "Ina neman gafarar Allah Mai Girma, Wanda babu abin bautawa da gaskiya sai Shi, Mai Rai, Tsayayye mai tsare komai, kuma ina tuba zuwa gare Shi.",
                translationYoruba = "Mo n tọrọ idariji lọwọ Allāhu Ọba Titobi, Ẹni ti ko si ọlọhun miiran lẹhin Rẹ, Alaye, Olugbe gbogbo nkan duro, mo si n ronupiwada si I.",
                translationIgbo = "Ana m arịọ mgbaghara n'aka Chineke Onye Pụrụ Ime Ihe Niile, Enweghị chi ọzọ ma e wezụga Ya, Onye Dị Ndụ, ma ana m echegharị n'ebe Ọ nọ.",
                reference = "The Prophet (ﷺ) said: 'Whoever says this will be forgiven even if he had fled from battle.'\nReference: Sunan Abi Dawud 1517, Jami' at-Tirmidhi 3577."
            ),
            DuaEntity(
                id = 116,
                category = "Repentance & Seeking Forgiveness",
                title = "Prophetic Repentance in Gatherings (100 Times)",
                arabic = "رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ",
                transliteration = "Rabbigh-fir lee wa tub 'alayya, innaka Antat-Tawwabur-Raheem.",
                translation = "My Lord, forgive me and accept my repentance, indeed You are the Accepter of repentance, the Most Merciful (recited 100 times in gatherings).",
                translationHausa = "Ya Ubangijina Ka gafarta mini kuma Ka karbi tubana, lallai Kai ne Mai karbar tuba, Mai jin kai (ana maimaitawa sau 100).",
                translationYoruba = "Oluwa mi, dariji mi ki O si gba ironupiwada mi, dajudaju Iwọ ni Olugba ironupiwada, Alanu (a n ka a ni ẹẹgọrun).",
                translationIgbo = "Onye nwe m, gbaghara m ma nabata nchegharị m, n'ezie Gị bụ Onye Na-anabata nchegharị, Onye Ebere (a na-agụ ya ugboro 100).",
                reference = "Ibn Umar narrated: 'We counted the Messenger of Allah (ﷺ) saying this one hundred times in a single gathering.'\nReference: Sunan Abi Dawud 1516, Jami' at-Tirmidhi 3434."
            ),
            DuaEntity(
                id = 117,
                category = "Marriage & Family",
                title = "Dua for Righteous Spouse & Children",
                arabic = "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا",
                transliteration = "Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil-muttaqeena imama.",
                translation = "Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous.",
                translationHausa = "Ya Ubangijinmu! Ka ba mu daga matanmu da zuriyarmu sanyin idanuya, kuma Ka sanya mu shugabanni ga masu tsoron Allah.",
                translationYoruba = "Oluwa wa! Fun wa lati inu awọn iyawo wa ati awọn ọmọ wa ni itura oju, ki O si ṣe wa ni aṣiwaju fun awọn olubẹru Ọlọhun.",
                translationIgbo = "Onye nwe anyị! Nye anyị site n'aka ndị nwunye anyị na ụmụ anyị ihe ga-enye obi ụtọ n'anya anyị ma mee anyị ndị ndu maka ndị na-atụ egwu Chineke.",
                reference = "Holy Quran, Surah Al-Furqan 25:74."
            ),
            DuaEntity(
                id = 118,
                category = "Marriage & Family",
                title = "Dua for Family Harmony and Reconciliation",
                arabic = "اللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا، وَأَصْلِحْ ذَاتَ بَيْنِنَا، وَاهْدِنَا سُبُلَ السَّلَامِ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ",
                transliteration = "Allahumma allif bayna quloobina, wa aslih dhata baynina, wahdina subulas-salam, wa najjina minaz-zulumati ilan-noor.",
                translation = "O Allah, reconcile between our hearts, mend our relationships, guide us to paths of peace, and deliver us from darkness into light.",
                translationHausa = "Ya Allah Ka daidaita tsakanin zukatanmu, Ka gyara alakarmu ta zaman lafiya, Ka shiryar da mu hanyoyin aminci, kuma Ka tseratar da mu daga duffai zuwa haske.",
                translationYoruba = "Allāhu, darapọ mọ awọn ọkan wa, tun aarin wa ṣe, fihan wa awọn ọna alaafia, ki O si gba wa la kuro ninu okunkun si imọlẹ.",
                translationIgbo = "Chineke, mezie obi anyị, dozie mmekọrịta dị n'etiti anyị, duzie anyị n'ụzọ udo, ma zọpụta anyị site n'ọchịchịrị banye n'ìhè.",
                reference = "Sunan Abi Dawud 969, Al-Hakim 1/265."
            ),
            DuaEntity(
                id = 119,
                category = "Marriage & Family",
                title = "Dua for Offspring to Keep Up Prayers (Ibrahim's Supplication)",
                arabic = "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ",
                transliteration = "Rabbij-'alnee muqeemas-salati wa min dhurriyyatee, Rabbana wa taqabbal du'a.",
                translation = "My Lord, make me an establisher of prayer, and from my descendants. Our Lord, and accept my supplication.",
                translationHausa = "Ya Ubangijina! Ka sanya ni mai tsayar da sallah, da kuma zuriyata. Ya Ubangijinmu, Ka amsa addu'ata.",
                translationYoruba = "Oluwa mi! Ṣe mi ni olutọju sọlaati, ati lati inu awọn ọmọ mi. Oluwa wa, gba adura mi.",
                translationIgbo = "Onye nwe m! Mee ka m bụrụ onye na-ekpe ekpere mgbe niile, yana ụmụ m. Onye nwe anyị, nabata ekpere m.",
                reference = "Holy Quran, Surah Ibrahim 14:40."
            ),
            DuaEntity(
                id = 120,
                category = "Marriage & Family",
                title = "Dua for Blessed and Pure Offspring (Zakariya's Supplication)",
                arabic = "رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ",
                transliteration = "Rabbi hab lee mil-ladunka dhurriyyatan tayyibah, innaka Samee'ud-du'a.",
                translation = "My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication.",
                translationHausa = "Ya Ubangijina! Ka ba ni zuriya mai dadi (mai albarka) daga gare Ka. Lallai Kai ne Mai jin addu'a.",
                translationYoruba = "Oluwa mi! Fun mi lati ọdọ Rẹ ni ọmọ rere. Dajudaju Iwọ ni Olugbọ adura.",
                translationIgbo = "Onye nwe m! Nye m ụmụ dị mma site n'aka Gị. N'ezie Gị bụ Onye Na-anụ ekpere.",
                reference = "Holy Quran, Surah Ali 'Imran 3:38."
            ),
            DuaEntity(
                id = 121,
                category = "Repentance & Seeking Forgiveness",
                title = "Master Supplication for Forgiveness (Sayyidul Istighfar)",
                arabic = "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ",
                transliteration = "Allahumma Anta Rabbee la ilaha illa Ant, khalaqtanee wa ana 'abduk, wa ana 'ala 'ahdika wa wa'dika mastata't, a'udhu bika min sharri ma sana't, aboo'u laka bini'matika 'alayya, wa aboo'u laka bidhanbee faghfir lee fa innahu la yaghfirudh-dhunooba illa Ant.",
                translation = "O Allah, You are my Lord, there is no deity except You. You created me and I am Your slave. I abide by Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favor upon me, and I confess my sins to You, so forgive me, for none forgives sins except You.",
                translationHausa = "Ya Allah, Kai ne Ubangijina babu abin bautawa da gaskiya sai Kai. Ka halicce ni kuma ni bawanka ne. Ina kan alkawarinka da wa'adinka gwargwadon ikona. Ina neman tsari da Kai daga sharrin abin da na aikata. Ina gode maka da ni'imarka a kaina kuma na yarda da zunubina gare Ka, saboda haka Ka gafarta mini, domin babu mai gafarta zunubai sai Kai.",
                translationYoruba = "Allāhu, Iwọ ni Oluwa mi, ko si ọlọhun miiran bikoṣe Iwọ. O da mi, emi si ni ẹru Rẹ. Mo wa lori adehun Rẹ gẹgẹ bi agbara mi ti mọ. Mo wa aabo pẹlu Rẹ kuro ninu aburu ohun ti mo ṣe. Mo jẹwọ ibukun Rẹ lori mi, mo si jẹwọ ẹṣẹ mi fun Ọ, nitorinaa dariji mi, nitori ko si ẹniti n dari ẹṣẹ ji bikoṣe Iwọ.",
                translationIgbo = "Chineke, Gị bụ Onye nwe m, ọ dịghị chi ọzọ ma e wezụga Gị. Gị kere m ma abụ m ohu Gị. Ana m eji ọgbụgba ndụ Gị dịka ike m hà. Ana m arịọ nchebe n'aka Gị pụọ n'ihe ọjọọ m mere. Ana m anabata amara Gị n'ebe m nọ ma kwupụta mmehie m, ya mere gbaghara m, n'ihi na ọ dịghị onye na-agbaghara mmehie ma e wezụga Gị.",
                reference = "The Prophet (ﷺ) said: 'Whoever recites this in the evening and dies that night will enter Paradise, and whoever recites it in the morning and dies that day will enter Paradise.'\nReference: Sahih al-Bukhari 6306."
            ),
            DuaEntity(
                id = 122,
                category = "Repentance & Seeking Forgiveness",
                title = "Dua for Complete Forgiveness in Sujood (Prostration)",
                arabic = "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ",
                transliteration = "Allahumm-aghfir lee dhanbee kullahu: diqqahu wa jillahu, wa awwalahu wa akhirahu, wa 'alaniyatahu wa sirrahu.",
                translation = "O Allah, forgive me all my sins: the minor and the major, the first and the last, the open and the hidden.",
                translationHausa = "Ya Allah, Ka gafarta mini zunubina duka: kankantansu da girmansu, na farkonsu da na karshensu, na bayyane da na boye.",
                translationYoruba = "Allāhu, dari gbogbo ẹṣẹ mi ji mi: kekere ati nla rẹ, akọkọ ati igbẹhin rẹ, eyi ti o han ati eyi ti o pamọ.",
                translationIgbo = "Chineke, gbaghara m mmehie m niile: nke nta na nke ukwu, nke mbụ na nke ikpeazụ, nke pụtara ìhè na nke zoro ezo.",
                reference = "The Messenger of Allah (ﷺ) used to say this supplication in his prostration (Sujood).\nReference: Sahih Muslim 483."
            ),
            DuaEntity(
                id = 123,
                category = "Repentance & Seeking Forgiveness",
                title = "Dua of Abu Bakr Taught by the Prophet (ﷺ) for Salah",
                arabic = "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ",
                transliteration = "Allahumma innee zalamtu nafsee zulman katheeran, wa la yaghfirudh-dhunooba illa Ant, faghfir lee maghfiratan min 'indika war-hamnee, innaka Antal-Ghafoorur-Raheem.",
                translation = "O Allah, I have wronged my soul greatly, and none forgives sins except You, so grant me forgiveness from Yourself and have mercy upon me. Indeed, You are the Forgiving, the Merciful.",
                translationHausa = "Ya Allah, lallai na zalunci kaina zalunci mai yawa, kuma babu mai gafarta zunubai sai Kai, don haka Ka gafarta mini gafara daga gare Ka, kuma Ka ji kaina, lallai Kai ne Mai gafara, Mai jin kai.",
                translationYoruba = "Allāhu, dajudaju mo ti ṣe abosi si ẹmi mi ni abosi pupọ, ko si ẹniti n dari ẹṣẹ ji ayafi Iwọ, nitorinaa fi aforiji lati ọdọ Rẹ forijin mi ki O si ke mi, dajudaju Iwọ ni Alaforijin, Alanu.",
                translationIgbo = "Chineke, emehiela m onwe m nke ukwuu, ọ dịghịkwa onye na-agbaghara mmehie ma e wezụga Gị, ya mere meere m ebere ma gbaghara m site n'aka Gị. N'ezie Gị bụ Onye Na-agbaghara mmehie, Onye Ebere.",
                reference = "Abu Bakr As-Siddiq asked the Prophet (ﷺ): 'Teach me a supplication to say in my prayer.' The Prophet taught him this.\nReference: Sahih al-Bukhari 834, Sahih Muslim 2705."
            ),
            DuaEntity(
                id = 124,
                category = "Repentance & Seeking Forgiveness",
                title = "Dua of Adam and Hawwa (Repentance of our Parents)",
                arabic = "رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ",
                transliteration = "Rabbana zalamna anfusana wa il-lam taghfir lana wa tarhamna lana-koonanna minal-khasireen.",
                translation = "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.",
                translationHausa = "Ya Ubangijinmu! Mun zalunci kanmu, idan ba Ka gafarta mana ba kuma Ka ji kanmu, lallai za mu kasance daga cikin masu hasara.",
                translationYoruba = "Oluwa wa! A ti ṣe abosi si ẹmi ara wa, ti O ba kọ lati dariji wa ti O ko si ke wa, dajudaju a o wa ninu awọn ẹni-ofo.",
                translationIgbo = "Onye nwe anyị! Anyị emehiela onwe anyị, ọ bụrụ na Gị agbagharaghị anyị ma meere anyị ebere, anyị ga-abụ ndị ga-ada n'efu.",
                reference = "Holy Quran, Surah Al-A'raf 7:23."
            ),
            DuaEntity(
                id = 125,
                category = "Repentance & Seeking Forgiveness",
                title = "Dua of Yunus in the Whale (Relief from Distress & Sins)",
                arabic = "لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ",
                transliteration = "La ilaha illa Anta subhanaka innee kuntu minaz-zalimeen.",
                translation = "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.",
                translationHausa = "Babu abin bautawa da gaskiya sai Kai, Tsarki ya tabbata a gare Ka! Lallai na kasance daga cikin azzalumai.",
                translationYoruba = "Ko si ọlọhun miiran bikoṣe Iwọ, Mímọ́ ni fun Ọ! Dajudaju emi ti wa ninu awọn alagbere (awọn t'o ṣe abosi).",
                translationIgbo = "Ọ dịghị chi ọzọ ma e wezụga Gị, Otuto dịrị Gị! N'ezie abụ m otu n'ime ndị na-eme ajọ omume.",
                reference = "The Prophet (ﷺ) said: 'No Muslim supplicates with this in any matter except that Allah answers him.'\nReference: Jami' at-Tirmidhi 3505, Surah Al-Anbiya 21:87."
            ),
            DuaEntity(
                id = 126,
                category = "Repentance & Seeking Forgiveness",
                title = "Comprehensive Prophetic Supplication for All Sins",
                arabic = "اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي",
                transliteration = "Allahumm-aghfir lee khatee'atee wa jahlee, wa israafee fee amree, wa ma Anta a'lamu bihi minnee. Allahumm-aghfir lee jiddee wa hazlee, wa khata'ee wa 'amdee, wa kullu dhalika 'indee.",
                translation = "O Allah, forgive my faults, my ignorance, my extravagance in my affairs, and what You know better than I do. O Allah, forgive my seriousness and my joking, my unintended errors and my deliberate wrongs, and all of that is in me.",
                translationHausa = "Ya Allah, Ka gafarta mini kurakuraina da jahilcina, da almubazzarancina a cikin lamurana, da kuma abin da Ka fi ni sani. Ya Allah, Ka gafarta mini gaskiyata da wasata, kuskurena da gangancina, kuma duk wannan yana tare da ni.",
                translationYoruba = "Allāhu, dari aṣiṣe mi ji mi, aimokan mi, ati aṣeju mi ninu ọrọ mi, ati ohun ti O mọ ju mi lọ. Allāhu, dari ohun ti mo ṣe ni pataki ati awada ji mi, aṣiṣe ati aimọọmọ mi, gbogbo rẹ si wa lọdọ mi.",
                translationIgbo = "Chineke, gbaghara m mmehie m, amaghị ihe m, na oke nganga m n'ihe m na-eme, na ihe Gị maara karịa m. Chineke, gbaghara m ihe m mere na ezigbo ya na ihe m mere n'egwuregwu, njehie m na nke m kpachaara anya mee.",
                reference = "Sahih al-Bukhari 6398, Sahih Muslim 2719."
            ),
            DuaEntity(
                id = 127,
                category = "Repentance & Seeking Forgiveness",
                title = "Expiation of Gatherings (Kaffarat al-Majlis)",
                arabic = "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ",
                transliteration = "Subhanakallahumma wa bihamdika, ash-hadu alla ilaha illa Ant, astaghfiruka wa atoobu ilayk.",
                translation = "Glory is to You, O Allah, and praise. I testify that there is no deity except You. I seek Your forgiveness and repent to You.",
                translationHausa = "Tsarki ya tabbata a gare Ka ya Allah tare da godiyarKa, na shaida babu abin bautawa da gaskiya sai Kai, ina neman gafararKa kuma ina tuba zuwa gare Ka.",
                translationYoruba = "Mímọ́ ni fun Ọ, Allāhu, pẹlu ọpẹ Rẹ, mo jẹri pe ko si ọlọhun miiran bikoṣe Iwọ, mo n tọrọ idariji Rẹ mo si n ronupiwada si Ọ.",
                translationIgbo = "Otuto dịrị Gị Chineke, na ekele Ya, ana m agba akaebe na ọ dịghị chi ọzọ ma e wezụga Gị, ana m arịọ mgbaghara Gị ma na-echegharị n'ebe Ọ nọ.",
                reference = "The Prophet (ﷺ) said: 'Whoever sits in a gathering where there was much noise and says this before standing up, whatever occurred in that gathering will be forgiven for him.'\nReference: Jami' at-Tirmidhi 3433."
            ),
            DuaEntity(
                id = 128,
                category = "Repentance & Seeking Forgiveness",
                title = "Salat at-Tawbah (The Prayer of Repentance)",
                arabic = "مَا مِنْ عَبْدٍ يُذْنِبُ ذَنْبًا فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلَّا غَفَرَ اللَّهُ لَهُ",
                transliteration = "Ma min 'abdin yudhnibu dhanban fayuhsinut-tuhoor, thumma yaqoomu fayusallee rak'atayn, thumma yastaghfirullaha illa ghafarallahu lah.",
                translation = "There is no servant who commits a sin, then purifies himself well, then stands and prays two units of prayer, then asks Allah for forgiveness except that Allah forgives him.",
                translationHausa = "Babu wani bawa da zai yi zunubi, sa'an nan ya kyautata alwala, ya tashi ya yi sallar raka'a biyu, sa'an nan ya nemi gafarar Allah face Allah Ya gafarta masa.",
                translationYoruba = "Ko si ẹru kan ti yoo dẹṣẹ, lẹhinna ti yoo ṣe àlwálà daradara, ti yoo dide ki o kẹ sọlaati raka'ah meji, lẹhinna ti yoo tọrọ gafara Allāhu bikoṣe pe Allāhu yoo dariji i.",
                translationIgbo = "Ọ dịghị ohu ọ bụla ga-eme mmehie, wee mee alwala nke ọma, bilie kpee ekpere nke raka'ah abụọ, wee rịọ Chineke mgbaghara ma e wezụga na Chineke ga-agbaghara ya.",
                reference = "Sunan Abi Dawud 1521, Jami' at-Tirmidhi 406, Musnad Ahmad 1/2."
            ),
            DuaEntity(
                id = 129,
                category = "Hajj & Umrah",
                title = "Hajj Step 1: Niyyah & Ihram at the Miqat (Niyya a Miqati)",
                arabic = "لَبَّيْكَ اللَّهُمَّ عُمْرَةً / لَبَّيْكَ اللَّهُمَّ حَجًّا — فَإِنْ حَبَسَنِي حَابِسٌ فَمَحِلِّي حَيْثُ حَبَسْتَنِي",
                transliteration = "Labbayk Allahumma 'Umrah (for Umrah) / Labbayk Allahumma Hajjan (for Hajj) — Fa in habasanee habisun famahillee haythu habastanee.",
                translation = "Here I am O Allah, for Umrah / Here I am O Allah, for Hajj. (If sick or afraid of hindrance add: 'If I am prevented by any obstacle, my place of exiting Ihram is where You have held me'). Perform Ghusl, put on Ihram garments, and make intention at the Miqat.",
                translationHausa = "Ga ni Ya Allah na amsa kiranka don Umra / don Hajji. (Idan ana jin tsoron cuta ko cikas a ce: 'Idan wani cikas ya tsaida ni to wurin kwance haramina shi ne inda Ka tsaida ni'). Ana yin wankan tsarki, a sanya harami, a furta niyya a Miqati.",
                translationYoruba = "Emi niyi Allāhu fun Umrah / Emi niyi Allāhu fun Hajj. Ṣe iwẹ gẹgẹ bi Sunnah, wọ aṣọ ihram, ki o si ṣe aniyan ni Miqat.",
                translationIgbo = "Lee m Chineke maka Umrah / Lee m maka Hajj. Saa ahụ nke ọma, yiri uwe ihram, ma mee ebumnuche gị na Miqat.",
                reference = "Sunnah of the Prophet (ﷺ) at the Miqat. Sahih al-Bukhari 1549, Sahih Muslim 1207."
            ),
            DuaEntity(
                id = 130,
                category = "Hajj & Umrah",
                title = "Hajj Step 2: Prohibitions of Ihram & Sunnah Warnings (Hane-hane)",
                arabic = "الْحَجُّ أَشْهُرٌ مَّعْلُومَاتٌ ۚ فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ",
                transliteration = "Al-Hajju ashhurum-ma'loomat, faman farada feehinnal-hajja fala rafatha wa la fusooqa wa la jidaala fil-Hajj.",
                translation = "Hajj is in the well-known months. Whoever undertakes Hajj therein, there must be no sexual relations, no sin, and no quarreling during Hajj. (Prohibitions: No cutting hair/nails, no perfume on body/cloth after Ihram, men must not wear sewn clothes or head coverings, women must not wear Niqab or gloves. Warnings against Sunnah violations: Do not push others, do not shout collective chants, do not wipe walls/stones for blessing).",
                translationHausa = "Abubuwan da aka haramta wa mai Harami da kiyayewa: 1) Haramun ne aske gashi ko yanke farce ko shafa turare. 2) Maza ba sa sanya tufafi mai dinki ko hula ko takalmin da ke rufe idon kafa. 3) Mata ba sa sanya nikafi (niqab) ko safar hannu. 4) Haramun ne saduwa da iyali, sabon Allah, jayayya ko zagi. Gargadi kan bidi'o'i: Haramtawa shafar Ka'aba ko duwatsu don neman tabarruki, da hani kan kururuwa ko ture mutane a dawafi.",
                translationYoruba = "Awọn ohun ti a ka leewọ fun ẹni to wa ninu Ihram: Ma ṣe ge irun tabi eekanna, ma fi lofinda si ara tabi aṣọ, awọn ọkunrin ko gbọdọ wọ aṣọ ti a ran tabi bo ori, awọn obinrin ko gbọdọ wọ niqab tabi ibọwọ. Yago fun ariyanjiyan ati ija.",
                translationIgbo = "Ihe ndị a machibidoro iwu n'oge Ihram: Ejila isi ma ọ bụ bepụ mbọ, etinyela mmanụ na-esi ísì ụtọ, ụmụ nwoke agaghị eyi uwe a dụrụ adụ ma ọ bụ kpuchie isi, ụmụ nwaanyị agaghị ekpuchi ihu ha kpamkpam. Zere arụmụka na ime ihe ọjọọ.",
                reference = "Holy Quran, Surah Al-Baqarah 2:197, Sahih al-Bukhari 1838."
            ),
            DuaEntity(
                id = 131,
                category = "Hajj & Umrah",
                title = "Hajj Step 3: Entering Masjid al-Haram & Seeing the Ka'abah",
                arabic = "اللَّهُمَّ زِدْ هَذَا الْبَيْتَ تَشْرِيفًا وَتَعْظِيمًا وَتَكْرِيمًا وَمَهَابَةً، وَزِدْ مَنْ شَرَّفَهُ وَعَظَّمَهُ مِمَّنْ حَجَّهُ أَوِ اعْتَمَرَهُ تَشْرِيفًا وَتَكْرِيمًا وَتَعْظِيمًا وَبِرًّا",
                transliteration = "Allahumma zid hadhal-Bayta tashreefan wa ta'zeeman wa takreeman wa mahabah, wa zid man sharrafahu wa 'azzamahu mimman hajjahu awi'tamarahu tashreefan wa takreeman wa ta'zeeman wa birra.",
                translation = "Enter the sacred mosque with the right foot saying Bismillah and the Mosque Dua. Upon seeing the Ka'abah, raise your hands and supplicate: 'O Allah, increase this House in honor, esteem, respect, and awe, and increase those who honor and venerate it among those who make Hajj or Umrah in honor, respect, esteem, and righteousness.'",
                translationHausa = "Shiga Masallacin Harami da kafar dama tare da addu'ar shiga masallaci. Yayin da idonka ya kalli Ka'aba, kafa hannaye ka roki Allah: 'Ya Allah, Ka kara wa wannan Daki girma da daukaka da kwarjini da girmamawa, kuma Ka kara wa duk wanda ya girmama shi daga masu Hajji da Umra daukaka da girmamawa da alheri.'",
                translationYoruba = "Nigbati o ba wọ Mọsalasi Al-Haram, gbadura adura titẹ mọsalasi. Nigbati o ba ri Ka'abah, bẹ Allāhu ki O mu ọlá ati titobi Daki Rẹ pọ si.",
                translationIgbo = "Mgbe ị banyere n'ụlọ nsọ Ka'aba, kpee ekpere ịbanye ụlọ ekpere. Mgbe ị hụrụ Ka'aba, welie aka gị rịọ Chineke ka Ọ mụbaa nsọpụrụ na ịdị ukwuu nke Ụlọ Ya.",
                reference = "Sunan Al-Bayhaqi 5/73, Ibn Abi Shaybah 3/180."
            ),
            DuaEntity(
                id = 132,
                category = "Hajj & Umrah",
                title = "Hajj Step 4: Starting Tawaf at the Black Stone (Hajar al-Aswad)",
                arabic = "بِسْمِ اللَّهِ، وَاللَّهُ أَكْبَرُ — رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",
                transliteration = "Bismillahi, Wallahu Akbar — Rabbana aatina fid-dunya hasanatan wa fil-aakhirati hasanatan wa qina 'adhaban-nar.",
                translation = "Begin each of the 7 circuits of Tawaf at the Black Stone by kissing it, touching it, or pointing towards it with the right hand saying 'Bismillahi Wallahu Akbar'. Between the Yamani Corner and the Black Stone, recite: 'Our Lord, give us in this world that which is good and in the Hereafter that which is good and save us from the torment of the Fire.'",
                translationHausa = "Fara kowane zagaye na dawafi 7 a Hajarul Aswad ta hanyar sumbanta ko shafa ko nuna shi da hannun dama tare da cewa 'Bismillahi Wallahu Akbar'. Tsakanin Ruknul Yamani da Hajarul Aswad a rinka karanta: 'Rabbana aatina fid-dunya hasanatan wa fil-aakhirati hasanatan wa qina adhaban-nar'.",
                translationYoruba = "Bẹrẹ kọọkan ninu iyipo meje ti Tawaf ni Hajarul Aswad pẹlu 'Bismillahi Wallahu Akbar'. Laarin Yamani ati Hajarul Aswad, ka adura 'Rabbana aatina...'.",
                translationIgbo = "Malite okirikiri 7 nke Tawaf na Hajarul Aswad site n'ikwu 'Bismillahi Wallahu Akbar'. N'etiti Yamani na Hajarul Aswad, gụọ 'Rabbana aatina...'.",
                reference = "Sahih al-Bukhari 1613, Sunan Abi Dawud 1892."
            ),
            DuaEntity(
                id = 133,
                category = "Hajj & Umrah",
                title = "Hajj Step 5: Prayer behind Maqam Ibrahim & Drinking Zamzam",
                arabic = "وَاتَّخِذُوا مِن مَّقَامِ إِبْرَاهِيمَ مُصَلًّى — اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا وَاسِعًا، وَشِفَاءً مِنْ كُلِّ دَاءٍ",
                transliteration = "Wattakhidhoo mim-Maqaami Ibraaheema musalla — Allahumma innee as'aluka 'ilman nafi'an, wa rizqan wasi'an, wa shifa'an min kulli daa'.",
                translation = "After completing 7 circuits, go behind Maqam Ibrahim and recite: 'And take the Station of Ibrahim as a place of prayer' (Surah 2:125). Pray 2 short rak'ahs (reciting Surah Al-Kafirun and Al-Ikhlas). Then drink Zamzam water to fullness and pour it over your head while making dua.",
                translationHausa = "Bayan kammala dawafi zagaye 7, je bayan Maqamu Ibrahim ka karanta ayar 'Wattakhidhu min maqaami Ibrahima musalla'. Ka yi sallar raka'a biyu (tare da Kafirun da Ikhlas). Sannan ka sha ruwan Zamzam ka koshi, ka zuba a kanka kana addu'a.",
                translationYoruba = "Lẹhin Tawaf, lọ si ẹhin Maqam Ibrahim, kẹ sọlaati raka'ah meji, lẹhinna mu omi Zamzam ki o si gbadura oore gbogbo.",
                translationIgbo = "Mgbe ị gụsịrị Tawaf, ga n'azụ Maqam Ibrahim, kpee ekpere raka'ah abụọ, mechaa ṅụọ mmiri Zamzam ma rịọ ngọzi niile.",
                reference = "Sahih Muslim 1218, Sunan Ibn Majah 3062."
            ),
            DuaEntity(
                id = 134,
                category = "Hajj & Umrah",
                title = "Hajj Step 6: Ascending Safa & Supplication during Sa'ee",
                arabic = "إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ... أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ — لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ",
                transliteration = "Innas-Safa wal-Marwata min sha'a'irillah... Abda'u bima bada'allahu bih — La ilaha illallahu wahdahu la shareeka lah, lahul-mulku wa lahul-hamdu wa Huwa 'ala kulli shay'in qadeer.",
                translation = "Proceed to Mount Safa for Sa'ee (7 laps). At Safa, face the Qiblah, raise hands, make Takbeer (Allahu Akbar 3 times) and recite the Shahada and praise of Allah, then make long personal dua. Walk to Marwa and repeat at each station.",
                translationHausa = "Nufi Dutsen Safa don fara Sa'ayi zagaye 7 tsakanin Safa da Marwa. A kan Safa, fuskanci alkibla, daga hannaye, ka yi kabbara sau 3 tare da zikirin 'La ilaha illallahu wahdahu...', sannan ka yi addu'ar neman bukatunka. A maimaita haka a kan kowace Safa da Marwa.",
                translationYoruba = "Lọ si Oke Safa fun Sa'ee (iyipo meje). Kọju si Qiblah, gbe ọwọ soke, ka zikiri ati adura, lẹhinna rin lọ si Marwa.",
                translationIgbo = "Gaa n'Ugwu Safa maka Sa'ee (ugboro 7). Chee ihu na Qiblah, welie aka gị, mee zikiri ma kpee ekpere, gaa n'Ugwu Marwa.",
                reference = "Sahih Muslim 1218 (Hadith of Jabir)."
            ),
            DuaEntity(
                id = 135,
                category = "Hajj & Umrah",
                title = "Hajj Step 7: Shaving (Halq) or Trimming (Taqseer)",
                arabic = "اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ... وَلِلْمُقَصِّرِينَ",
                transliteration = "Allahumm-aghfir lil-muhalliqeen... wa lil-muqassireen.",
                translation = "For Umrah completion or on Eid day: Men shave their entire head (better) or trim hair evenly all around. Women gather their hair and cut the length of a fingertip from the end. This completes Umrah or the initial exit from Ihram.",
                translationHausa = "Aske kai ko rage gashi: Ga maza, aske dukkan kai ya fi lada (Annabi ya yi wa masu aski addu'a sau 3, masu rage gashi sau 1). Mata kuma za su tara karshen gashinsu su yanke gwargwadon karshen dan yatsa. Da wannan aka kammala Umra ko samun Tahallul na farko.",
                translationYoruba = "Fifi abẹ fari tabi gigẹ irun: Awọn ọkunrin yoo fari tabi ge irun wọn, awọn obinrin yoo ge diẹ lati ipari irun wọn lati pari Umrah.",
                translationIgbo = "Ịkpụ isi ma ọ bụ ibelata ntutu: Ụmụ nwoke ga-akpụ isi ha kpamkpam ma ọ bụ belata ya, ụmụ nwaanyị ga-ebipụ obere akụkụ na nsọtụ ntutu ha.",
                reference = "Sahih al-Bukhari 1727, Sahih Muslim 1301."
            ),
            DuaEntity(
                id = 136,
                category = "Hajj & Umrah",
                title = "Hajj Step 8: Day of Tarwiyah at Mina (8th of Dhul-Hijjah)",
                arabic = "لَبَّيْكَ اللَّهُمَّ حَجًّا — يَوْمُ التَّرْوِيَةِ بِمِنَى",
                transliteration = "Labbayk Allahumma Hajjan — Yawmut-Tarwiyah bi-Mina.",
                translation = "On the morning of 8th Dhul-Hijjah, enter Ihram for Hajj from where you are staying, declaring 'Labbayk Allahumma Hajjan'. Move to Mina and pray Dhuhr, Asr, Maghrib, Isha, and Fajr shortened (Qasr, 2 rak'ahs each for 4-rak'ah prayers) but without combining them, spending the night in Mina.",
                translationHausa = "Ranar Tarwiya (8 ga Dhul-Hijjah): Da safe, mai aikin hajji zai sake ɗaure harami daga masaukinsa da cewa 'Labbayk Allahumma Hajjan'. A tafi Mina a yi sallar Azahar, La'asar, Magriba, Isha da Asuba a rage su zuwa raka'a biyu ba tare da hadawa ba, tare da kwana a Mina.",
                translationYoruba = "Ọjọ Tarwiyah (ọjọ kẹjọ ti Dhul-Hijjah): Wọ ihram fun Hajj, lọ si Mina ki o si kẹ sọlaati ni kukuru lai da wọn pọ, ki o si sun si Mina.",
                translationIgbo = "Ụbọchị Tarwiyah (ụbọchị nke 8 nke Dhul-Hijjah): Yiri ihram maka Hajj, gaa na Mina kpee ekpere n'ụdị mkpirikpi ma nọrọ abalị n'ebe ahụ.",
                reference = "Sahih Muslim 1218."
            ),
            DuaEntity(
                id = 137,
                category = "Hajj & Umrah",
                title = "Hajj Step 9: Standing at Arafah (9th Dhul-Hijjah - The Peak of Hajj)",
                arabic = "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ",
                transliteration = "La ilaha illallahu wahdahu la shareeka lah, lahul-mulku wa lahul-hamdu wa Huwa 'ala kulli shay'in qadeer.",
                translation = "Standing at Arafah on the 9th of Dhul-Hijjah from after Dhuhr until sunset. Pray Dhuhr and Asr combined and shortened at Namirah, then devote the entire afternoon to facing the Qiblah, raising hands, crying, and begging Allah for forgiveness. The Prophet (ﷺ) said: 'Hajj is Arafah.'",
                translationHausa = "Tsayuwar Arfa (9 ga Dhul-Hijjah): Shi ne jigon aikin Hajji (Annabi yace: 'Al-Hajju Arafah'). Daga bayan zawali zuwa faduwar rana, ana hada Azahar da La'asar a rage su, sannan a fuskanci alkibla a yawaita kuka, tuba, da rokon Allah gafara da alherin duniya da lahira.",
                translationYoruba = "Iduro lori Arafah (ọjọ kẹsan ti Dhul-Hijjah): Eyi ni koko Hajj. Gbadura lọwọ Allāhu pẹlu ọwọ gbigbe soke titi ti oorun yoo fi wọ.",
                translationIgbo = "Ikwụ n'Arafah (ụbọchị nke 9 nke Dhul-Hijjah): Nke a bụ isi ihe dị na Hajj. Rịọ Chineke mgbaghara ma kpee ekpere ruo mgbe anyanwụ dara.",
                reference = "Jami' at-Tirmidhi 889, Sahih Muslim 1218."
            ),
            DuaEntity(
                id = 138,
                category = "Hajj & Umrah",
                title = "Hajj Step 10: Night at Muzdalifah & Mash'ar al-Haram",
                arabic = "فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِندَ الْمَشْعَرِ الْحَرَامِ",
                transliteration = "Fa idha afadtum min 'Arafatin fadh-kurullaha 'indal-Mash'aril-Haram.",
                translation = "After sunset on 9th Dhul-Hijjah, proceed calmly to Muzdalifah. Pray Maghrib (3 rak'ahs) and Isha (2 rak'ahs) combined upon arrival. Sleep until Fajr, pray Fajr at its earliest time, then stand facing Qiblah at Al-Mash'ar al-Haram praising and supplicating to Allah until brightness before sunrise.",
                translationHausa = "Kwana a Muzdalifa (Daren 10 ga Dhul-Hijjah): Bayan faduwar rana a Arfa, a nufi Muzdalifa cikin nutsuwa. A hada Magriba (3) da Isha (2). A kwanta a yi barci har Asuba. Bayan sallar Asuba, a fuskanci alkibla a Mash'arul Haram ana zikiri da addu'a har sai gari ya waye sosai kafin fitowar rana.",
                translationYoruba = "Sun si Muzdalifah: Lẹhin Arafah, lọ si Muzdalifah, da Maghrib ati Isha pọ, sun titi di Fajr, lẹhinna ṣe zikiri ni Mash'arul Haram.",
                translationIgbo = "Ịnọ abalị na Muzdalifah: Mgbe Arafah gachara, gaa Muzdalifah, kpee Maghrib na Isha ọnụ, hie ụra ruo Fajr ma mee zikiri.",
                reference = "Holy Quran, Surah Al-Baqarah 2:198, Sahih Muslim 1218."
            ),
            DuaEntity(
                id = 139,
                category = "Hajj & Umrah",
                title = "Hajj Step 11: Day of Eid (10th Dhul-Hijjah) - Stoning, Sacrifice & Shaving",
                arabic = "اللَّهُ أَكْبَرُ (مَعَ كُلِّ حَصَاةٍ) — بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ، اللَّهُمَّ مِنْكَ وَلَكَ، اللَّهُمَّ تَقَبَّلْ مِنِّي",
                transliteration = "Allahu Akbar (with every pebble) — Bismillahi Wallahu Akbar, Allahumma minka wa laka, Allahumma taqabbal minnee.",
                translation = "Actions of Yawm an-Nahr (Eid Day): 1) Stone Jamrat al-Aqaba (the Big Pillar) with 7 pebbles saying 'Allahu Akbar' with each throw. 2) Slaughter sacrificial animal (Hady). 3) Shave/cut hair (1st Tahallul - all prohibitions lifted except intimacy). 4) Perform Tawaf al-Ifadah and Sa'ee (2nd Tahallul - all prohibitions lifted).",
                translationHausa = "Ayyukan Ranar Sallah (10 ga Dhul-Hijjah): 1) Jifan Jamratul Aqaba (Babban Gunki) da tsakuwa 7 kana cewa 'Allahu Akbar' a kowace tsakuwa. 2) Yanka Hadaya. 3) Aske kai ko rage gashi (samun Tahallul na farko inda komai ya halatta banda saduwa da iyali). 4) Dawafin Ifada da Sa'ayin Hajji a Ka'aba (samun cikon Tahallul).",
                translationYoruba = "Awọn iṣẹ ti Ọjọ Eid (10th Dhul-Hijjah): 1) Ju okuta 7 si Jamratul Aqaba. 2) Pa ẹran ẹbọ. 3) Fari tabi ge irun. 4) Ṣe Tawaf al-Ifadah ati Sa'ee.",
                translationIgbo = "Ọrụ nke Ụbọchị Eid: 1) Tụba obere okwute 7 na Jamratul Aqaba. 2) Gbuo anụ e ji achụ àjà. 3) Kpụọ ntutu. 4) Mee Tawaf al-Ifadah na Sa'ee.",
                reference = "Sahih al-Bukhari 1751, Sahih Muslim 1218."
            ),
            DuaEntity(
                id = 140,
                category = "Hajj & Umrah",
                title = "Hajj Step 12: Days of Tashreeq (11th, 12th, 13th) - Stoning the 3 Jamarat",
                arabic = "وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ — اللَّهُ أَكْبَرُ",
                transliteration = "Wadh-kurullaha fee ayyamim-ma'doodat — Allahu Akbar.",
                translation = "Stay the nights in Mina. Each afternoon after Dhuhr, stone the 3 Jamarat in order: Small (7 pebbles, then step aside and make a long dua), Middle (7 pebbles, step aside and make a long dua), and Big/Aqaba (7 pebbles, leave without standing for dua).",
                translationHausa = "Kwanakin Tashriq (11, 12, 13 ga Dhul-Hijjah a Mina): Bayan zawalin kowace rana, a jifi gunkai 3 a jere: Karami (tsakuwa 7 sannan a matsa gefe a yi doguwar addu'a), Matsakaici (tsakuwa 7 sannan a matsa gefe a yi doguwar addu'a), da Babban Gunki (tsakuwa 7 ba tare da tsayawa addu'a ba).",
                translationYoruba = "Awọn ọjọ Tashreeq: Sun si Mina, ki o si ju okuta si awọn Jamarat mẹtẹẹta lẹhin zawal lojoojumọ.",
                translationIgbo = "Ụbọchị Tashreeq: Nọrọ abalị na Mina, tụba obere okwute na Jamarat atọ kwa ụbọchị mgbe zawal gachara.",
                reference = "Holy Quran, Surah Al-Baqarah 2:203, Sahih al-Bukhari 1753."
            ),
            DuaEntity(
                id = 141,
                category = "Hajj & Umrah",
                title = "Hajj Step 13: Farewell Tawaf (Tawaf al-Wada') & Departure",
                arabic = "لَا يَنْفِرَنَّ أَحَدٌ حَتَّى يَكُونَ آخِرُ عَهْدِهِ بِالْبَيْتِ",
                transliteration = "La yanfiranna ahadun hatta yakoona akhiru 'ahdihi bil-Bayt.",
                translation = "Before departing Makkah to return home, perform Tawaf al-Wada' (7 circuits of farewell without Sa'ee) as the final act in the Holy City. Women in menses are excused from the farewell circumambulation.",
                translationHausa = "Dawafin Bankwana (Tawaf al-Wada'): Kafin mai aikin Hajji ya bar birnin Makkah ya nufi gida, wajibi ne ya yi dawafin bankwana zagaye 7 a kusa da Ka'aba ba tare da Sa'ayi ba. Mata masu jinin al'ada an yafe musu wannan dawafi.",
                translationYoruba = "Tawaf ti Idagbere (Tawaf al-Wada'): Ṣe iyipo meje ti idagbere ṣaaju ki o to fi Makkah silẹ lọ si ile.",
                translationIgbo = "Tawaf nke Ịsị nke Ọma (Tawaf al-Wada'): Mee okirikiri 7 tupu ị hapụ Makkah ịlaghachi n'ụlọ.",
                reference = "Sahih Muslim 1327, Sahih al-Bukhari 1755."
            ),
            DuaEntity(
                id = 142,
                category = "Repentance & Seeking Forgiveness",
                title = "Supplication for Past, Future, Secret & Open Sins",
                arabic = "اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ",
                transliteration = "Allahummagh-fir lee ma qaddamtu, wa ma akhkhart, wa ma asrartu wa ma a'lant, wa ma asraft, wa ma Anta a'lamu bihi minnee. Antal-Muqaddimu wa Antal-Mu'akhkhiru la ilaha illa Ant.",
                translation = "O Allah, forgive me for what I have sent forward and what I have delayed, for what I have concealed and what I have revealed, for what I have exceeded bounds in, and what You know better than I do. You are the Advancer, and You are the Delayer, there is no deity except You.",
                translationHausa = "Ya Allah, Ka gafarta mini abin da na gabatar (na zunubai da suka wuce) da wanda na jinkirta, da abin da na ɓoye da abin da na bayyana, da wanda na yi ƙetare iyaka a ciki, da abin da Ka fi ni sani. Kai ne Mai gabatarwa, kuma Kai ne Mai jinkirtarwa, babu abin bautawa da gaskiya sai Kai.",
                translationYoruba = "Allāhu, dari ohun ti mo ti firanṣẹ siwaju ati ohun ti mo da duro ji mi, ohun ti mo fi pamọ ati ohun ti mo fi han, ohun ti mo ṣe aṣeju ninu rẹ, ati ohun ti O mọ ju mi lọ. Iwọ ni Asiwaju, Iwọ si ni Alakẹyin, ko si ọlọhun miiran bikoṣe Iwọ.",
                translationIgbo = "Chineke, gbaghara m ihe m mere n'oge gara aga na nke m na-emeghị, nke m zoro ezo na nke pụtara ìhè, nke m gafere ókè na ya, na ihe Gị maara karịa m. Gị bụ Onye Mbụ na Onye Ikpeazụ, ọ dịghị chi ọzọ ma e wezụga Gị.",
                reference = "The Prophet (ﷺ) used to say this supplication in his prayer (at the end before Tasleem or in Qiyam al-Layl).\nReference: Sahih Muslim 771, Sahih al-Bukhari 1120."
            ),
            DuaEntity(
                id = 143,
                category = "Hajj & Umrah",
                title = "Common Innovations & Violations to Avoid in Hajj",
                arabic = "مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ — خُذُوا عَنِّي مَنَاسِكَكُمْ",
                transliteration = "Man 'amila 'amalan laysa 'alayhi amruna fahuwa radd — Khudhoo 'annee manasikakum.",
                translation = "Important Warnings & Violations in Hajj: 1) Seeking Tabarruk (blessing) by wiping Ka'abah walls, curtains, or Maqam Ibrahim — only touching Black Stone and Yamani Corner are Sunnah. 2) Chanting collective loud supplications disturbing others. 3) Pushing or harming fellow pilgrims at Tawaf or Jamarat. 4) Standing outside the boundary poles of Arafah. 5) Throwing slippers or large stones at Jamarat instead of 7 chickpea-sized pebbles with Takbeer. 6) Taking selfies and showing off (Riya') during sacred acts.",
                translationHausa = "Kura-kurai da Bidi'o'in da ke Saba wa Sunnah a Guje Musu: 1) Shafar bangon Ka'aba, labulenta, ko Maqamu Ibrahim da nufin neman tabarruki (shafar Hajarul Aswad da Ruknul Yamani kadai Sunnah ta koyar). 2) Karanta addu'a a tare a dunkule da babbar murya wanda ke damun sauran masu ibada. 3) Turewa, take mutane, ko cutar da 'yan uwa musulmi a dawafi ko jifa. 4) Tsayawa a wajen iyakokin Arfa (ba a cikin iyakarta ba). 5) Jifan shaidan da takalmi ko manyan duwatsu maimakon kananan tsakuwa 7 da kabbara. 6) Yin hotunan 'selfie' don nuna wa mutane da riya' a tsakiyar ibada.",
                translationYoruba = "Awọn aṣiṣe ati awọn bidi'a ti o yẹ ki a yago fun ninu Hajj: 1) Fọwọkan awọn ogiri Ka'aba fun ibukun, 2) Kiko adura jọ pẹlu ohun rara, 3) Titari tabi ipalara awọn arinrin ajo miiran, 4) Iduro ni ita Arafah, 5) Jiju bata si Jamarat.",
                translationIgbo = "Mmejọ na ihe ọhụrụ a ga-ezere na Hajj: 1) Imetụ mgbidi Ka'aba aka maka ngọzi, 2) Ikpe ekpere n'olu dara ụda na-enye nsogbu, 3) Ịkwanye ndị mmadụ na Tawaf, 4) Ikwụ n'èzí oke Arafah, 5) Ịtụ akpụkpọ ụkwụ na Jamarat.",
                reference = "The Prophet (ﷺ) commanded: 'Whoever introduces something into our religion will have it rejected' and 'Learn your rituals of Hajj from me.'\nReference: Sahih Muslim 1718, Sahih Muslim 1297."
            )
,
            DuaEntity(
                id = 144,
                category = "40 Rabbana Duas",
                title = "Rabbana 1: For Acceptance of Deeds & Prayers",
                arabic = "رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ",
                transliteration = "Rabbana taqabbal minna innaka Antas-Samee'ul-'Aleem.",
                translation = "Our Lord! Accept (this service) from us: For You are the All-Hearing, the All-Knowing.",
                translationHausa = "Ya Ubangijinmu! Ka karba daga gare mu, hakika Kai ne Mai ji, Masani.",
                translationYoruba = "Oluwa wa! Gba (iṣẹ yii) lati ọdọ wa: Dajudaju Iwọ ni Olugbọ, Onimọ.",
                translationIgbo = "Onyenwe anyị! Nabata nke a n'aka anyị: N'ezie Gị bụ Onye Na-anụ Ihe, Onye Maara Ihe Niile.",
                reference = "Surah Al-Baqarah (2:127) — The prayer of Prophet Ibrahim (Abraham) and Isma'il when building the Ka'bah."
            ),
            DuaEntity(
                id = 145,
                category = "40 Rabbana Duas",
                title = "Rabbana 2: For Submissive Hearts & Righteous Offspring",
                arabic = "رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ",
                transliteration = "Rabbana waj'alna muslimayni laka wa min dhurriyyatina ummatam-muslimatan laka wa arina manasikana wa tub 'alayna, innaka Antat-Tawwabur-Raheem.",
                translation = "Our Lord! Make of us Muslims, bowing to Your (Will), and of our progeny a people Muslim, bowing to Your (will); and show us our places for the celebration of (due) rites; and turn unto us (in Mercy); for You are the Oft-Returning, Most Merciful.",
                translationHausa = "Ya Ubangijinmu! Ka sanya mu masu mika wuya gare Ka (Musulmi), kuma daga zuri'armu al'umma mai mika wuya gare Ka, kuma Ka nuna mana hanyoyin ibadunmu, kuma Ka karbi tubanmu; hakika Kai ne Mai karbar tuba, Mai jin kai.",
                translationYoruba = "Oluwa wa! Ṣe wa ni Musulumi ti n tẹriba fun Ọ, ati lati inu irandiran wa ni orilẹ-ede Musulumi ti n tẹriba fun Ọ; ki O si fi awọn ibi ijọsin wa han wa; ki O si dariji wa; dajudaju Iwọ ni Oludariji, Alanu.",
                translationIgbo = "Onyenwe anyị! Mee ka anyị bụrụ ndị na-erubere Gị isi, na site na ụmụ anyị ka e nwee mba na-erubere Gị isi; kụziere anyị emume ofufe anyị ma gbaghara anyị.",
                reference = "Surah Al-Baqarah (2:128) — Supplication of Ibrahim and Isma'il."
            ),
            DuaEntity(
                id = 146,
                category = "40 Rabbana Duas",
                title = "Rabbana 3: For Good in This World & the Hereafter",
                arabic = "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",
                transliteration = "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'adhaban-nar.",
                translation = "Our Lord! Give us in this world that which is good and in the Hereafter that which is good, and save us from the torment of the Fire!",
                translationHausa = "Ya Ubangijinmu! Ka ba mu kyakkyawa a duniya, da kyakkyawa a Lahira, kuma Ka kare mu daga azabar wuta.",
                translationYoruba = "Oluwa wa! Fun wa ni ohun rere ni ayé yii ati ohun rere ni Ọjọ Ìkẹhin, ki O si gbà wa kuro ninu ijiya Ina!",
                translationIgbo = "Onyenwe anyị! Nye anyị ihe dị mma n'ụwa a na ihe dị mma na ndụ na-abịa, ma chebe anyị pụọ na ahụhụ nke Ọkụ!",
                reference = "Surah Al-Baqarah (2:201) — The most frequently recited supplication of the Prophet Muhammad (ﷺ) (Sahih al-Bukhari 4522)."
            ),
            DuaEntity(
                id = 147,
                category = "40 Rabbana Duas",
                title = "Rabbana 4: For Patience, Steadfastness & Victory",
                arabic = "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ",
                transliteration = "Rabbana afrigh 'alayna sabran wa thabbit aqdamana wansurna 'alal-qawmil-kafirin.",
                translation = "Our Lord! Pour out constancy on us and make our steps firm: Help us against those that reject faith.",
                translationHausa = "Ya Ubangijinmu! Ka zubo mana da hakuri a kanmu, kuma Ka tabbatar da dugaduganmu (sawunmu), kuma Ka taimake mu a kan mutane kafirai.",
                translationYoruba = "Oluwa wa! Da sùúrù le wa lori ki O si mu ẹsẹ wa duro gbag vững, ki O si ran wa lọwọ lori awọn alaigbagbọ.",
                translationIgbo = "Onyenwe anyị! Wụsa anyị ndidi ma mee ka ụkwụ anyị kwụsie ike: Nyere anyị aka megide ndị na-ekweghị ekwe.",
                reference = "Surah Al-Baqarah (2:250) — The prayer of Talut (Saul) and his faithful army against Jalut (Goliath)."
            ),
            DuaEntity(
                id = 148,
                category = "40 Rabbana Duas",
                title = "Rabbana 5: For Forgiveness of Forgetfulness & Mistakes",
                arabic = "رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا",
                transliteration = "Rabbana la tu'akhidhna in-naseena aw akhta'na.",
                translation = "Our Lord! Condemn us not if we forget or fall into error.",
                translationHausa = "Ya Ubangijinmu! Kada Ka kama mu (da laifi) idan mun mance ko kuma mun yi kuskure.",
                translationYoruba = "Oluwa wa! Ma ṣe bawi wa ti a ba gbagbe tabi ti a ba ṣina.",
                translationIgbo = "Onyenwe anyị! Ejila anyị n'ụgwọ ma anyị chefuo ma ọ bụ mebie iwu.",
                reference = "Surah Al-Baqarah (2:286) — Allah responded to this: 'I have done so' (Sahih Muslim 126)."
            ),
            DuaEntity(
                id = 149,
                category = "40 Rabbana Duas",
                title = "Rabbana 6: Protection from Heavy Burdens",
                arabic = "رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا",
                transliteration = "Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladheena min qablina.",
                translation = "Our Lord! Lay not on us a burden like that which You did lay on those before us.",
                translationHausa = "Ya Ubangijinmu! Kada Ka dora mana nauyi mai tsanani kamar yadda Ka dora shi a kan wadanda suka gabace mu.",
                translationYoruba = "Oluwa wa! Ma ṣe gbe ẹru wuwo le wa lori gẹgẹ bi O ti gbe e le awọn ti o ṣaaju wa.",
                translationIgbo = "Onyenwe anyị! Ebokwasịla anyị ibu dị arọ dịka I bokwasịrị ndị bu anyị ụzọ.",
                reference = "Surah Al-Baqarah (2:286) — Part of the blessed ending of Surah Al-Baqarah."
            ),
            DuaEntity(
                id = 150,
                category = "40 Rabbana Duas",
                title = "Rabbana 7: For Relief, Mercy, Pardon & Victory",
                arabic = "رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ",
                transliteration = "Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, Anta Mawlana fansurna 'alal-qawmil-kafirin.",
                translation = "Our Lord! Lay not on us a burden greater than we have strength to bear. Blot out our sins, and grant us forgiveness. Have mercy on us. You are our Protector; help us against those who stand against faith.",
                translationHausa = "Ya Ubangijinmu! Kada Ka dora mana abin da ba mu da ikon daukarsa. Ka yafe mana, Ka gafarta mana, kuma Ka yi mana rahama; Kai ne Majibinmu, saboda haka Ka taimake mu a kan mutane kafirai.",
                translationYoruba = "Oluwa wa! Ma ṣe gbe ohun ti agbara wa ko le gbe le wa lori. Dariji wa, ki O si ṣaanu fun wa. Iwọ ni Olugbeja wa; ran wa lọwọ lori awọn alaigbagbọ.",
                translationIgbo = "Onyenwe anyị! Ebokwasịla anyị ihe anyị na-enweghị ike iburu. Gbaghara anyị, ma mee anyị ebere. Gị bụ Onye Nchebe anyị; nyere anyị aka megide ndị na-ekweghị ekwe.",
                reference = "Surah Al-Baqarah (2:286)."
            ),
            DuaEntity(
                id = 151,
                category = "40 Rabbana Duas",
                title = "Rabbana 8: For Steadfast Faith & Divine Mercy",
                arabic = "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ",
                transliteration = "Rabbana la tuzigh quloobana ba'da idh hadaytana wa hab lana mil-ladunka rahmah, innaka Antal-Wahhab.",
                translation = "Our Lord! Let not our hearts deviate now after You have guided us, but grant us mercy from Your presence; for You are the Grantor of bounties without measure.",
                translationHausa = "Ya Ubangijinmu! Kada Ka karkatar da zukatanmu bayan Ka shiryar da mu, kuma Ka ba mu rahama daga gare Ka; hakika Kai ne Mai yawan kyauta da bayarwa.",
                translationYoruba = "Oluwa wa! Ma ṣe jẹ ki ọkan wa yipada lẹhin ti O ti fi ọna mọ wa, ki O si fun wa ni aanu lati ọdọ Rẹ; dajudaju Iwọ ni Ọlọrẹ Ọfẹ.",
                translationIgbo = "Onyenwe anyị! Ekwela ka obi anyị kpafuo mgbe I duzisịrị anyị, ma nye anyị ebere site n'ihu Gị; n'ezie Gị bụ Onye Na-enye Onyinye.",
                reference = "Surah Ali 'Imran (3:8) — Supplication of the people firmly grounded in knowledge."
            ),
            DuaEntity(
                id = 152,
                category = "40 Rabbana Duas",
                title = "Rabbana 9: Conviction in the Day of Gathering",
                arabic = "رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ",
                transliteration = "Rabbana innaka jami'un-nasi li-yawmil-la rayba feeh, innallaha la yukhliful-mee'ad.",
                translation = "Our Lord! You are He that will gather mankind Together against a day about which there is no doubt; for Allah never fails in His promise.",
                translationHausa = "Ya Ubangijinmu! Hakika Kai ne Mai tara mutane a wata rana wadda babu shakka a cikinta; hakika Allah ba Ya saba alkawari.",
                translationYoruba = "Oluwa wa! Dajudaju Iwọ ni O maa ko gbogbo eniyan jọ fun ọjọ ti ko si iyemeji ninu rẹ; dajudaju Ọlọhun kii yẹ adehun.",
                translationIgbo = "Onyenwe anyị! N'ezie Gị ga-achịkọta mmadụ niile n'ụbọchị nke na-enweghị obi abụọ; n'ezie Chineke anaghị ada ná nkwa Ya.",
                reference = "Surah Ali 'Imran (3:9)."
            ),
            DuaEntity(
                id = 153,
                category = "40 Rabbana Duas",
                title = "Rabbana 10: For Forgiveness of Sins & Salvation from Hell",
                arabic = "رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ",
                transliteration = "Rabbana innana amanna faghfir lana dhunoobana wa qina 'adhaban-nar.",
                translation = "Our Lord! We have indeed believed: forgive us, then, our sins, and save us from the agony of the Fire!",
                translationHausa = "Ya Ubangijinmu! Hakika mu mun yi imani, saboda haka Ka gafarta mana zunubanmu, kuma Ka kare mu daga azabar wuta.",
                translationYoruba = "Oluwa wa! Dajudaju a gbagbọ, nitorina dari awọn ẹṣẹ wa ji wa, ki O si gba wa kuro ninu ijiya Ina!",
                translationIgbo = "Onyenwe anyị! N'ezie anyị kwere: n'ihi ya gbaghara anyị mmehie anyị, ma zọpụta anyị n'ahụhụ nke Ọkụ!",
                reference = "Surah Ali 'Imran (3:16) — Prayer of the righteous patient believers."
            ),
            DuaEntity(
                id = 154,
                category = "40 Rabbana Duas",
                title = "Rabbana 11: To Be Counted Among the Witnesses",
                arabic = "رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ",
                transliteration = "Rabbana amanna bima anzalta wattaba'nar-Rasoola faktubna ma'ash-shahideen.",
                translation = "Our Lord! We believe in what You have revealed, and we follow the Messenger; then write us down among those who bear witness.",
                translationHausa = "Ya Ubangijinmu! Mun yi imani da abin da Ka saukar kuma mun bi Manzo; saboda haka Ka rubuta mu tare da masu shaida.",
                translationYoruba = "Oluwa wa! A gbagbọ ninu ohun ti O sọkalẹ, a si tẹle Ojiṣẹ naa; nitorina kọ wa mọ awọn ẹlẹri.",
                translationIgbo = "Onyenwe anyị! Anyị kwere n'ihe I kpughere ma soro Onye Ozi ahụ; n'ihi ya debanye aha anyị n'etiti ndị na-agba akaebe.",
                reference = "Surah Ali 'Imran (3:53) — Supplication of the disciples (Hawariyyun) of Prophet Isa (Jesus)."
            ),
            DuaEntity(
                id = 155,
                category = "40 Rabbana Duas",
                title = "Rabbana 12: For Forgiveness of Excesses & Victory",
                arabic = "رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ",
                transliteration = "Rabbanagh-fir lana dhunoobana wa israfana fee amrina wa thabbit aqdamana wansurna 'alal-qawmil-kafirin.",
                translation = "Our Lord! Forgive us our sins and any excess we have committed in our affairs, establish our feet firmly, and help us against the disbelieving people.",
                translationHausa = "Ya Ubangijinmu! Ka gafarta mana zunubanmu da wuce gona da irinmu a cikin al'amuranmu, Ka tabbatar da sawunmu (dugaduganmu), kuma Ka taimake mu a kan mutane kafirai.",
                translationYoruba = "Oluwa wa! Dariji awọn ẹṣẹ wa ati aṣeju wa ninu ọran wa, mu ẹsẹ wa duro gbọinngbọin, ki O si ran wa lọwọ lori awọn alaigbagbọ.",
                translationIgbo = "Onyenwe anyị! Gbaghara anyị mmehie anyị na oke anyị gafere n'okwu anyị, mee ka ụkwụ anyị kwụsie ike, ma nyere anyị aka megide ndị na-ekweghị ekwe.",
                reference = "Surah Ali 'Imran (3:147) — Supplication of the righteous companions of past prophets."
            ),
            DuaEntity(
                id = 156,
                category = "40 Rabbana Duas",
                title = "Rabbana 13: Contemplating Creation & Seeking Protection from Hell",
                arabic = "رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ",
                transliteration = "Rabbana ma khalaqta hadha batila, subhanaka faqina 'adhaban-nar.",
                translation = "Our Lord! Not for naught have You created (all) this! Glory be to You! Give us salvation from the penalty of the Fire.",
                translationHausa = "Ya Ubangijinmu! Ba Ka halicci wannan a banza ba; Tsarki ya tabbata a gare Ka, saboda haka Ka kare mu daga azabar wuta.",
                translationYoruba = "Oluwa wa! Iwọ ko da eyi lasan! Mimọ ni fun Ọ! Gba wa kuro ninu ijiya Ina.",
                translationIgbo = "Onyenwe anyị! Ị keghị ihe a n'efu! Otuto dịrị Gị! Zọpụta anyị n'ahụhụ nke Ọkụ.",
                reference = "Surah Ali 'Imran (3:191) — The prayer of Ulul-Albab (those endowed with deep intellect)."
            ),
            DuaEntity(
                id = 157,
                category = "40 Rabbana Duas",
                title = "Rabbana 14: Protection from Disgrace in the Fire",
                arabic = "رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ",
                transliteration = "Rabbana innaka man tudkhilin-nara faqad akhzaytah, wa ma liz-zalimeena min ansar.",
                translation = "Our Lord! Any whom You admit to the Fire, truly You cover with shame, and never will wrongdoers find any helpers!",
                translationHausa = "Ya Ubangijinmu! Hakika wanda Ka shigar da shi wuta, hakika Ka wulakanta shi, kuma azzalumai ba su da wasu mataimaka.",
                translationYoruba = "Oluwa wa! Ẹnikẹni ti O ba mu wọ Ina, dajudaju O ti dojutini; ko si si oluranlọwọ fun awọn alabosi!",
                translationIgbo = "Onyenwe anyị! Onye ọ bụla I mere ka ọ banye n'Ọkụ, n'ezie I meniela ya ihere, ndị ajọ omume agaghị enwe ndị na-enyere ha aka!",
                reference = "Surah Ali 'Imran (3:192)."
            ),
            DuaEntity(
                id = 158,
                category = "40 Rabbana Duas",
                title = "Rabbana 15 & 16: Answering the Call to Faith & Forgiveness",
                arabic = "رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ",
                transliteration = "Rabbana innana sami'na munadiyay-yunadi lil-eemani an aminoo bi-Rabbikum fa-amanna, Rabbana faghfir lana dhunoobana wa kaffir 'anna sayyi'atina wa tawaffana ma'al-abrar.",
                translation = "Our Lord! We have heard the call of one calling (Us) to Faith, 'Believe in the Lord,' and we have believed. Our Lord! Forgive us our sins, blot out from us our iniquities, and take to Yourself our souls in the company of the righteous.",
                translationHausa = "Ya Ubangijinmu! Hakika mu mun ji mai kira yana kira zuwa ga imani cewa: 'Ku yi imani da Ubangijinku,' sai muka yi imani. Ya Ubangijinmu! Ka gafarta mana zunubanmu, Ka kankare mana laifukanmu, kuma Ka karbi rayukanmu tare da mutanen kirki.",
                translationYoruba = "Oluwa wa! Dajudaju a gbọ ipe olupe kan ti n pe si igbagbọ pe: 'Ẹ gba Oluwa yin gbọ,' a si gbagbọ. Oluwa wa! Dari awọn ẹṣẹ wa ji wa, pa awọn iwa buburu wa rẹ, ki O si gba ẹmi wa pẹlu awọn olododo.",
                translationIgbo = "Onyenwe anyị! Anyị anụwo olu onye na-akpọ òkù okwukwe: 'Kwerenụ n'Onyenwe unu,' anyị wee kwere. Onyenwe anyị! Gbaghara anyị mmehie anyị, hichapụ ihe ọjọọ anyị, ma mee ka anyị nwụọ n'etiti ndị ezi omume.",
                reference = "Surah Ali 'Imran (3:193)."
            ),
            DuaEntity(
                id = 159,
                category = "40 Rabbana Duas",
                title = "Rabbana 17: Fulfillment of Promises & Deliverance on Judgment Day",
                arabic = "رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ",
                transliteration = "Rabbana wa atina ma wa'adtana 'ala rusulika wa la tukhzina yawmal-qiyamah, innaka la tukhliful-mee'ad.",
                translation = "Our Lord! Grant us what You did promise unto us through Your Messengers, and save us from shame on the Day of Judgment: For You never break Your promise.",
                translationHausa = "Ya Ubangijinmu! Ka ba mu abin da Ka yi mana alkawari a kan harsunan ManzanninKa, kuma kada Ka kunyatar da mu a Ranar Kiyama; hakika Kai ba Ka saba alkawari.",
                translationYoruba = "Oluwa wa! Fun wa ni ohun ti O ṣe adehun fun wa nipasẹ awọn Ojiṣẹ Rẹ, ma si ṣe dojutini wa ni Ọjọ Ajinde; dajudaju Iwọ kii yẹ adehun.",
                translationIgbo = "Onyenwe anyị! Nye anyị ihe I kwere anyị ná nkwa site n'ọnụ ndị Ozi Gị, ma emela ka anyị nwee ihere n'Ụbọchị Ikpe: N'ezie Ị naghị emebi nkwa Gị.",
                reference = "Surah Ali 'Imran (3:194)."
            ),
            DuaEntity(
                id = 160,
                category = "40 Rabbana Duas",
                title = "Rabbana 18: Recording Faith with Truthful Witnesses",
                arabic = "رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِدِينَ",
                transliteration = "Rabbana amanna faktubna ma'ash-shahideen.",
                translation = "Our Lord! We believe; write us down among the witnesses.",
                translationHausa = "Ya Ubangijinmu! Mun yi imani, saboda haka Ka rubuta mu tare da masu shaida gaskiya.",
                translationYoruba = "Oluwa wa! A gbagbọ; kọ wa mọ awọn ẹlẹri.",
                translationIgbo = "Onyenwe anyị! Anyị kwere; debanye aha anyị n'etiti ndị na-agba akaebe.",
                reference = "Surah Al-Ma'idah (5:83) — Recited by sincere listeners when hearing the Quran recited."
            ),
            DuaEntity(
                id = 161,
                category = "40 Rabbana Duas",
                title = "Rabbana 19: For Sustenance, Blessing & Divine Provision",
                arabic = "رَبَّنَا أَنزِلْ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَآخِرِنَا وَآيَةً مِّنكَ ۖ وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ",
                transliteration = "Rabbana anzil 'alayna ma'idatam-minas-sama'i takoonu lana 'eedal-li'awwalina wa akhirina wa ayatan minka warzuqna wa Anta Khayrur-raziqeen.",
                translation = "O Allah our Lord! Send us from heaven a table set (with food), that there may be for us - for the first and the last of us - a solemn festival and a sign from You; and provide for our sustenance, for You are the best of sustainers.",
                translationHausa = "Ya Ubangijinmu! Ka saukar mana da teburin abinci daga sama, wanda zai zama idi a gare mu, ga na farkonmu da na karshenmu, kuma aya (alama) daga gare Ka; kuma Ka azurta mu, domin Kai ne Mafi fificin masu azurtawa.",
                translationYoruba = "Oluwa wa! Sọ tabili onjẹ kalẹ fun wa lati ọrun, ki o jẹ ayẹyẹ fun wa, fun ẹni akọkọ ati ẹni ikẹhin wa, ati ami lati ọdọ Rẹ; pese fun wa, nitori Iwọ ni Olupese ti o dara julọ.",
                translationIgbo = "Onyenwe anyị! Send anyị tebụl nri si n'eluigwe, ka ọ bụrụ emume nye anyị, maka ndị mbụ na ndị ikpeazụ anyị, na ihe ịrịba ama sitere na Gị; ma nye anyị ihe oriri, n'ihi na Gị bụ Onye Kacha Nye Ihe Oriri.",
                reference = "Surah Al-Ma'idah (5:114) — The prayer of Prophet Isa (Jesus) peace be upon him."
            ),
            DuaEntity(
                id = 162,
                category = "40 Rabbana Duas",
                title = "Rabbana 20: The Repentance of Adam & Eve (Deliverance from Loss)",
                arabic = "رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ",
                transliteration = "Rabbana zalamna anfusana wa il-lam taghfir lana wa tarhamna lanakoonanna minal-khasireen.",
                translation = "Our Lord! We have wronged our own souls: If You forgive us not and bestow not upon us Your Mercy, we shall certainly be lost.",
                translationHausa = "Ya Ubangijinmu! Mun zalunci kawunanmu, kuma idan ba Ka gafarta mana ba kuma Ka yi mana rahama, lallai za mu kasance daga cikin masu hasara.",
                translationYoruba = "Oluwa wa! A ti ṣe abosi si ara wa: Ti O ko ba dariji wa ki O si ṣaanu fun wa, dajudaju a o wa ninu awọn ti o padanu.",
                translationIgbo = "Onyenwe anyị! Anyị emehiela megide onwe anyị: Ọ bụrụ na Ị gbagharaghị anyị ma mee anyị ebere, anyị ga-abụ ndị lara n'iyi.",
                reference = "Surah Al-A'raf (7:23) — The very first supplication taught to Prophet Adam and Hawwa (Eve)."
            ),
            DuaEntity(
                id = 163,
                category = "40 Rabbana Duas",
                title = "Rabbana 21: Protection from Being Among Wrongdoers",
                arabic = "رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ",
                transliteration = "Rabbana la taj'alna ma'al-qawmiz-zalimeen.",
                translation = "Our Lord! Send us not to the company of the wrongdoers.",
                translationHausa = "Ya Ubangijinmu! Kada Ka sanya mu tare da mutane azzalumai.",
                translationYoruba = "Oluwa wa! Ma ṣe fi wa pẹlu awọn eniyan alabosi.",
                translationIgbo = "Onyenwe anyị! Emetula anyị na mkpakọrịta nke ndị ajọ omume.",
                reference = "Surah Al-A'raf (7:47) — Supplication of the People of the Heights (Ahl al-A'raf)."
            ),
            DuaEntity(
                id = 164,
                category = "40 Rabbana Duas",
                title = "Rabbana 22: For Truthful Decisions & Divine Judgment",
                arabic = "رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنتَ خَيْرُ الْفَاتِحِينَ",
                transliteration = "Rabbanaftah baynana wa bayna qawmina bil-haqqi wa Anta Khayrul-fatiheen.",
                translation = "Our Lord! Decide You between us and our people in truth, for You are the best to decide.",
                translationHausa = "Ya Ubangijinmu! Ka yanke hukunci a tsakaninmu da tsakanin mutanenmu da gaskiya, kuma Kai ne Mafi fificin masu yanke hukunci.",
                translationYoruba = "Oluwa wa! Ṣe idajọ laarin awa ati awọn eniyan wa pẹlu ododo, nitori Iwọ ni Oluse Idajọ ti o dara julọ.",
                translationIgbo = "Onyenwe anyị! Kpebie n'etiti anyị na ndị anyị n'eziokwu, n'ihi na Gị bụ Onye Kacha Kpee Ikpe.",
                reference = "Surah Al-A'raf (7:89) — Prayer of Prophet Shu'ayb peace be upon him."
            ),
            DuaEntity(
                id = 165,
                category = "40 Rabbana Duas",
                title = "Rabbana 23: For Patience Under Persecution & Dying as Muslims",
                arabic = "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ",
                transliteration = "Rabbana afrigh 'alayna sabran wa tawaffana muslimeen.",
                translation = "Our Lord! Pour out on us patience and constancy, and take our souls unto You as Muslims (who bow to Your will)!",
                translationHausa = "Ya Ubangijinmu! Ka zubo mana da hakuri a kanmu, kuma Ka karbi rayukanmu muna Musulmi (masu mika wuya gare Ka).",
                translationYoruba = "Oluwa wa! Da sùúrù le wa lori ki O si gba ẹmi wa gẹgẹ bi Musulumi!",
                translationIgbo = "Onyenwe anyị! Wụsa anyị ndidi ma mee ka anyị nwụọ dịka ndị Alakụba!",
                reference = "Surah Al-A'raf (7:126) — The declaration of the magicians of Pharaoh who believed in Prophet Musa (Moses)."
            ),
            DuaEntity(
                id = 166,
                category = "40 Rabbana Duas",
                title = "Rabbana 24: Protection from Oppression & Rescue from Disbelievers",
                arabic = "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ * وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ",
                transliteration = "Rabbana la taj'alna fitnatal-lil-qawmiz-zalimeen, wa najjina bi-rahmatika minal-qawmil-kafirin.",
                translation = "Our Lord! Make us not a trial for those who practise oppression; and deliver us by Your Mercy from those who reject (You).",
                translationHausa = "Ya Ubangijinmu! Kada Ka sanya mu zama fitina ga mutane azzalumai, kuma Ka tseratar da mu da rahamarKa daga mutane kafirai.",
                translationYoruba = "Oluwa wa! Ma ṣe fi wa ṣe idanwo fun awọn eniyan alabosi; ki O si fi aanu Rẹ gba wa kuro lọwọ awọn alaigbagbọ.",
                translationIgbo = "Onyenwe anyị! Emela ka anyị bụrụ ule nye ndị mmegbu; ma zọpụta anyị site n'ebere Gị n'aka ndị na-ekweghị ekwe.",
                reference = "Surah Yunus (10:85-86) — The prayer of the followers of Prophet Musa."
            ),
            DuaEntity(
                id = 167,
                category = "40 Rabbana Duas",
                title = "Rabbana 25: Acknowledging Allah's Omniscience",
                arabic = "رَبَّنَا إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى اللَّهِ مِن شَيْءٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ",
                transliteration = "Rabbana innaka ta'lamu ma nukhfee wa ma nu'lin, wa ma yakhfa 'alallahi min shay'in fil-ardi wa la fis-sama'.",
                translation = "O our Lord! Truly You know what we conceal and what we reveal: for nothing whatever is hidden from Allah, whether on earth or in heaven.",
                translationHausa = "Ya Ubangijinmu! Hakika Kai Ka san abin da muke boyewa da abin da muke bayyanawa; kuma babu wani abu da ke boyuwa ga Allah a cikin kasa ko a cikin sama.",
                translationYoruba = "Oluwa wa! Dajudaju Iwọ mọ ohun ti a fi pamọ ati ohun ti a fi han; ko si ohun ti o farapamọ fun Ọlọhun ni ilẹ tabi ni ọrun.",
                translationIgbo = "Onyenwe anyị! N'ezie Gị maara ihe anyị na-ezo ezo na ihe anyị na-ekpughe: ọ dịghị ihe zoro ezo n'ebe Chineke nọ n'ụwa ma ọ bụ n'eluigwe.",
                reference = "Surah Ibrahim (14:38) — Prayer of Prophet Ibrahim (Abraham)."
            ),
            DuaEntity(
                id = 168,
                category = "40 Rabbana Duas",
                title = "Rabbana 26: For Establishing Prayer & Acceptance of Supplications",
                arabic = "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ",
                transliteration = "Rabbij-'alnee muqeemas-salati wa min dhurriyyatee, Rabbana wa taqabbal du'a.",
                translation = "O my Lord! Make me one who establishes regular Prayer, and also (raise such) among my offspring. O our Lord! And accept my prayer.",
                translationHausa = "Ya Ubangijina! Ka sanya ni mai tsayar da sallah, kuma daga zuri'ata ma haka. Ya Ubangijinmu! Ka karbi addu'ata.",
                translationYoruba = "Oluwa mi! Ṣe mi ni ẹni ti n gbe irun duro, ati lati inu irandiran mi pẹlu. Oluwa wa! Gba adura mi.",
                translationIgbo = "Onyenwe m! Mee ka m bụrụ onye na-ekpe ekpere mgbe niile, yana n'etiti ụmụ m. Onyenwe anyị! Nabata ekpere m.",
                reference = "Surah Ibrahim (14:40) — Supplication of Prophet Ibrahim."
            ),
            DuaEntity(
                id = 169,
                category = "40 Rabbana Duas",
                title = "Rabbana 27: For Forgiveness of Parents & All Believers",
                arabic = "رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ",
                transliteration = "Rabbanagh-fir lee wa li-walidayya wa lil-mu'mineena yawma yaqoomul-hisab.",
                translation = "O our Lord! Cover (us) with Your Forgiveness - me, my parents, and all Believers, on the Day that the Reckoning will be established!",
                translationHausa = "Ya Ubangijinmu! Ka gafarta mini, da iyayena biyu, da dukkan muminai a ranar da za a tsayar da hisabi!",
                translationYoruba = "Oluwa wa! Dariji emi, awọn obi mi mejeeji, ati gbogbo awọn onigbagbọ ni ọjọ ti iṣiro yoo duro!",
                translationIgbo = "Onyenwe anyị! Gbaghara m, ndị mụrụ m, na ndị kwere ekwe niile n'ụbọchị a ga-eme ngụkọta!",
                reference = "Surah Ibrahim (14:41) — Recited in every Muslim prayer."
            ),
            DuaEntity(
                id = 170,
                category = "40 Rabbana Duas",
                title = "Rabbana 28: Supplication of the Companions of the Cave (Mercy & Right Guidance)",
                arabic = "رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا",
                transliteration = "Rabbana atina mil-ladunka rahmatan wa hayyi' lana min amrina rashada.",
                translation = "Our Lord! Bestow on us Mercy from Yourself, and dispose of our affair for us in the right way!",
                translationHausa = "Ya Ubangijinmu! Ka ba mu rahama daga gare Ka, kuma Ka saukaka mana shiriyar al'amuranmu.",
                translationYoruba = "Oluwa wa! Fun wa ni aanu lati ọdọ Rẹ, ki O si ṣe atunṣe ọran wa fun wa ni ọna ti o tọ!",
                translationIgbo = "Onyenwe anyị! Nye anyị Ebere site n'onwe Gị, ma dozie ihe gbasara anyị n'ụzọ ziri ezi!",
                reference = "Surah Al-Kahf (18:10) — The prayer of the youth of the cave (Ashab al-Kahf) when seeking refuge."
            ),
            DuaEntity(
                id = 171,
                category = "40 Rabbana Duas",
                title = "Rabbana 29: Seeking Courage Against Oppression & Tyranny",
                arabic = "رَبَّنَا إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَا أَوْ أَن يَطْغَىٰ",
                transliteration = "Rabbana innana nakhafu ay-yafruta 'alayna aw ay-yatgha.",
                translation = "Our Lord! We fear lest he hasten with insolence against us, or lest he transgress all bounds.",
                translationHausa = "Ya Ubangijinmu! Hakika muna tsoron kada ya yi gaggawar cutar da mu ko kuma ya yi zalunci da ketare iyaka.",
                translationYoruba = "Oluwa wa! Dajudaju a n bẹru pe ki o ma ba yara binu si wa tabi ki o tayọ ẹnu-ààlà.",
                translationIgbo = "Onyenwe anyị! Anyị na-atụ egwu na ọ ga-eme ihe ike megide anyị ma ọ bụ gafee ókè.",
                reference = "Surah Taha (20:45) — The prayer of Prophet Musa and Harun before going to Pharaoh."
            ),
            DuaEntity(
                id = 172,
                category = "40 Rabbana Duas",
                title = "Rabbana 30: Appealing to the Best of Those Who Show Mercy",
                arabic = "رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ",
                transliteration = "Rabbana amanna faghfir lana warhamna wa Anta Khayrur-rahimeen.",
                translation = "Our Lord! We believe! So forgive us and have mercy upon us, for You are the Best of those who show mercy!",
                translationHausa = "Ya Ubangijinmu! Mun yi imani, saboda haka Ka gafarta mana kuma Ka yi mana rahama, domin Kai ne Mafi fificin masu jin kai!",
                translationYoruba = "Oluwa wa! A gbagbọ! Nitorina dariji wa ki O si ṣaanu fun wa, nitori Iwọ ni O dara julọ ninu awọn ti n ṣaanu!",
                translationIgbo = "Onyenwe anyị! Anyị kwere! Ya mere gbaghara anyị ma mee anyị ebere, n'ihi na Gị bụ Onye Kacha Mee Ebere!",
                reference = "Surah Al-Mu'minun (23:109)."
            ),
            DuaEntity(
                id = 173,
                category = "40 Rabbana Duas",
                title = "Rabbana 31: Averting the Punishment of Hell",
                arabic = "رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا",
                transliteration = "Rabbanas-rif 'anna 'adhaba jahannama inna 'adhabaha kana gharama.",
                translation = "Our Lord! Avert from us the Wrath of Hell, for its Wrath is indeed an affliction grievous.",
                translationHausa = "Ya Ubangijinmu! Ka karkatar (kawar) mana da azabar Jahannama; hakika azabarta ta kasance halaka mai wuyar sha'ani.",
                translationYoruba = "Oluwa wa! Yipada ijiya Ina Jahannama kuro lọdọ wa; dajudaju ijiya rẹ jẹ iparun ti ko ni opin.",
                translationIgbo = "Onyenwe anyị! Wepụ anyị n'ahụhụ nke Ọkụ Ala Mmụọ, n'ihi na ahụhụ ya bụ ihe mgbu na-adịgide adịgide.",
                reference = "Surah Al-Furqan (25:65) — Characteristic supplication of the Servants of the Most Merciful ('Ibadur-Rahman)."
            ),
            DuaEntity(
                id = 174,
                category = "40 Rabbana Duas",
                title = "Rabbana 32: For Righteous Spouses, Children & Leadership in Piety",
                arabic = "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا",
                transliteration = "Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil-muttaqeena imama.",
                translation = "Our Lord! Grant unto us wives and offspring who will be the comfort of our eyes, and give us (the grace) to lead the righteous.",
                translationHausa = "Ya Ubangijinmu! Ka ba mu daga matanmu da zuri'armu abin sanyaya idanu (farin ciki), kuma Ka sanya mu shugabanni ga masu tsoron Allah.",
                translationYoruba = "Oluwa wa! Fun wa ni awọn iyawo ati awọn ọmọ ti yoo jẹ itura oju wa, ki O si ṣe wa ni adari fun awọn olusọrọ Ọlọhun.",
                translationIgbo = "Onyenwe anyị! Nye anyị ndị nwunye na ụmụ ga-abụ ihe nkasi obi nke anya anyị, ma mee anyị ndị ndú maka ndị na-atụ egwu Chineke.",
                reference = "Surah Al-Furqan (25:74) — Beloved Quranic prayer for family harmony and pious legacy."
            ),
            DuaEntity(
                id = 175,
                category = "40 Rabbana Duas",
                title = "Rabbana 33: Angels' Prayer for Repentant Believers",
                arabic = "رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ",
                transliteration = "Rabbana wasi'ta kulla shay'ir-rahmatan wa 'ilman faghfir lilladheena taboo wattaba'oo sabeelaka wa qihim 'adhabal-jaheem.",
                translation = "Our Lord! Your Reach is over all things, in Mercy and Knowledge. Forgive, then, those who turn in Repentance, and follow Your Path; and preserve them from the Penalty of the Blazing Fire!",
                translationHausa = "Ya Ubangijinmu! RahamarKa da IliminKa sun game kowane abu; saboda haka Ka gafarta wa wadanda suka tuba kuma suka bi tafarkinKa, kuma Ka kare su daga azabar wuta mai ruruwa.",
                translationYoruba = "Oluwa wa! Aanu ati Imọ Rẹ gba gbogbo nkan; nitorina dariji awọn ti o ronupiwada ti wọn si tẹle ọna Rẹ, ki O si gba wọn kuro ninu ijiya Ina!",
                translationIgbo = "Onyenwe anyị! Ebere na Ọmụma Gị gbara ihe niile gburugburu. Ya mere gbaghara ndị chegharịrị ma soro ụzọ Gị; ma chebe ha pụọ n'ahụhụ nke Ọkụ Na-ere Ere!",
                reference = "Surah Ghafir (40:7) — The prayer of the Throne-Bearing Angels for the believers."
            ),
            DuaEntity(
                id = 176,
                category = "40 Rabbana Duas",
                title = "Rabbana 34: Reunion with Righteous Family in Paradise",
                arabic = "رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ",
                transliteration = "Rabbana wa adkhilhum jannati 'adninil-latee wa'adtahum wa man salaha min aba'ihim wa azwajihim wa dhurriyyatihim, innaka Antal-'Azeezul-Hakeem.",
                translation = "And grant, our Lord! That they enter the Gardens of Eternity, which You have promised to them, and to the righteous among their fathers, their wives, and their posterity! For You are (the Exalted), the Full of Wisdom.",
                translationHausa = "Ya Ubangijinmu! Ka shigar da su gidajen Aljannar Adnin wadanda Ka yi musu alkawari, tare da duk wanda ya yi aiki na gari daga iyayensu, da matansu, da zuri'arsu; hakika Kai ne Mabuwayi, Mai hikima.",
                translationYoruba = "Oluwa wa! Mu wọn wọ inu Ọgba Irora ti O ti ṣe adehun fun wọn, ati awọn ti o ṣe rere ninu awọn baba wọn, awọn iyawo wọn, ati awọn ọmọ wọn! Dajudaju Iwọ ni Alagbara, Ọlọgbọn.",
                translationIgbo = "Onyenwe anyị! Mee ka ha banye n'Ogige nke Ebighị Ebi nke I kwere ha ná nkwa, yana ndị ezi omume n'etiti nna ha, ndị nwunye ha na ụmụ ha! N'ezie Gị bụ Onye Pụrụ Ihe Niile, Onye Amamihe.",
                reference = "Surah Ghafir (40:8)."
            ),
            DuaEntity(
                id = 177,
                category = "40 Rabbana Duas",
                title = "Rabbana 35: Purification of Hearts from Malice Towards Believers",
                arabic = "رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ",
                transliteration = "Rabbanagh-fir lana wa li-ikhwaninal-ladheena sabaqoona bil-eemani wa la taj'al fee quloobina ghillal-lilladheena amanoo Rabbana innaka Ra'oofur-Raheem.",
                translation = "Our Lord! Forgive us, and our brethren who came before us into the Faith, and leave not, in our hearts, rancour (or sense of injury) against those who have believed. Our Lord! You are indeed Full of Kindness, Most Merciful.",
                translationHausa = "Ya Ubangijinmu! Ka gafarta mana da kuma 'yan uwanmu wadanda suka riga mu da imani, kuma kada Ka sanya wata gaba ko kiyayya a cikin zukatanmu ga wadanda suka yi imani. Ya Ubangijinmu! Hakika Kai Mai tausayi ne, Mai jin kai.",
                translationYoruba = "Oluwa wa! Dariji awa ati awọn arakunrin wa ti o ṣaaju wa ninu igbagbọ, ma si ṣe fi ikorira sinu ọkan wa si awọn ti o gbagbọ. Oluwa wa! Dajudaju Iwọ jẹ Oninuure, Alanu.",
                translationIgbo = "Onyenwe anyị! Gbaghara anyị na ụmụnna anyị ndị bu anyị ụzọ n'okwukwe, ma ahapụla ịkpọasị n'obi anyị megide ndị kwere ekwe. Onyenwe anyị! N'ezie Gị bụ Onye Ebere, Onye Ọmiko.",
                reference = "Surah Al-Hashr (59:10) — The prayer of later generations of Muslims for the Sahabah (Companions) and all believers."
            ),
            DuaEntity(
                id = 178,
                category = "40 Rabbana Duas",
                title = "Rabbana 36: Total Reliance & Repentance to Allah",
                arabic = "رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ",
                transliteration = "Rabbana 'alayka tawakkalna wa ilayka anabna wa ilaykal-maseer.",
                translation = "Our Lord! In You we trust, and to You we turn in repentance: to You is (our) final Goal.",
                translationHausa = "Ya Ubangijinmu! A gare Ka muka dogara, kuma zuwa gare Ka muka tuba, kuma zuwa gare Ka makoma take.",
                translationYoruba = "Oluwa wa! Inu Rẹ ni a gbẹkẹle, ọdọ Rẹ ni a si yipada si ni ironupiwada: ọdọ Rẹ si ni opin irin-ajo.",
                translationIgbo = "Onyenwe anyị! N'ime Gị ka anyị tụkwasịrị obi, na n'ebe Gị nọ ka anyị na-echigharị: n'ebe Gị nọ ka njedebe anyị dị.",
                reference = "Surah Al-Mumtahanah (60:4) — Supplication of Prophet Ibrahim and those with him."
            ),
            DuaEntity(
                id = 179,
                category = "40 Rabbana Duas",
                title = "Rabbana 37: Protection from Being a Trial for Disbelievers",
                arabic = "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا ۖ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ",
                transliteration = "Rabbana la taj'alna fitnatal-lilladheena kafaroo waghfir lana Rabbana, innaka Antal-'Azeezul-Hakeem.",
                translation = "Our Lord! Make us not a (test and) trial for the Unbelievers, but forgive us, our Lord! For You are the Exalted in Might, the Wise.",
                translationHausa = "Ya Ubangijinmu! Kada Ka sanya mu zama fitina ga wadanda suka kafirta, kuma Ka gafarta mana ya Ubangijinmu; hakika Kai ne Mabuwayi, Mai hikima.",
                translationYoruba = "Oluwa wa! Ma ṣe fi wa ṣe idanwo fun awọn alaigbagbọ, ki O si dariji wa Oluwa wa! Dajudaju Iwọ ni Alagbara, Ọlọgbọn.",
                translationIgbo = "Onyenwe anyị! Emela ka anyị bụrụ ule nye ndị na-ekweghị ekwe, ma gbaghara anyị, Onyenwe anyị! N'ezie Gị bụ Onye Dị Ike, Onye Amamihe.",
                reference = "Surah Al-Mumtahanah (60:5)."
            ),
            DuaEntity(
                id = 180,
                category = "40 Rabbana Duas",
                title = "Rabbana 38: Perfecting of Light on the Day of Resurrection",
                arabic = "رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا ۖ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ",
                transliteration = "Rabbana atmim lana noorana waghfir lana, innaka 'ala kulli shay'in qadeer.",
                translation = "Our Lord! Perfect our Light for us, and grant us Forgiveness: for You have power over all things.",
                translationHausa = "Ya Ubangijinmu! Ka cika mana haskenmu kuma Ka gafarta mana; hakika Kai Mai ikon yi ne a kan kowane abu.",
                translationYoruba = "Oluwa wa! Mu imọlẹ wa pe fun wa, ki O si dariji wa: dajudaju Iwọ ni Alagbara lori ohun gbogbo.",
                translationIgbo = "Onyenwe anyị! Mee ka Ihie anyị zuo oke maka anyị, ma nye anyị Mgbaghara: n'ihi na Ị nwere ike n'elu ihe niile.",
                reference = "Surah At-Tahrim (66:8) — The prayer of the believers crossing the Sirat bridge on the Day of Judgment."
            ),
            DuaEntity(
                id = 181,
                category = "40 Rabbana Duas",
                title = "Rabbana 39: Relief from Calamity & Affliction",
                arabic = "رَّبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ",
                transliteration = "Rabbanak-shif 'annal-'adhaba inna mu'minoon.",
                translation = "Our Lord! Remove the torment from us: for we are really believers.",
                translationHausa = "Ya Ubangijinmu! Ka yaye mana azaba (masifa); hakika mu muminai ne.",
                translationYoruba = "Oluwa wa! Mu ijiya kuro lori wa: dajudaju a jẹ onigbagbọ.",
                translationIgbo = "Onyenwe anyị! Wepụ ahụhụ n'ebe anyị nọ: n'ihi na anyị bụ ndị kwere ekwe n'ezie.",
                reference = "Surah Ad-Dukhan (44:12)."
            ),
            DuaEntity(
                id = 182,
                category = "40 Rabbana Duas",
                title = "Rabbana 40: Supplication for Guidance, Mercy & Final Triumph",
                arabic = "رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِدِينَ ۝ رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ ۝ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",
                transliteration = "Rabbana amanna faktubna ma'ash-shahideen. Rabbana la taj'alna ma'al-qawmiz-zalimeen. Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'adhaban-nar.",
                translation = "Our Lord! We have believed, so write us among the witnesses. Our Lord, place us not with the unjust people. Our Lord, give us good in this world and good in the Hereafter, and save us from the torment of the Fire.",
                translationHausa = "Ya Ubangijinmu! Mun yi imani Ka rubuta mu tare da masu shaida. Ya Ubangijinmu! Kada Ka sanya mu tare da azzalumai. Ya Ubangijinmu! Ka ba mu kyakkyawa a duniya da Lahira kuma Ka tseratar da mu daga azabar wuta.",
                translationYoruba = "Oluwa wa! A gbagbọ, nitorina kọ wa mọ awọn ẹlẹri. Oluwa wa, ma ṣe fi wa pẹlu awọn alabosi. Oluwa wa, fun wa ni ire ni aiye ati ire ni ọrun ki O gba wa kuro ninu Ina.",
                translationIgbo = "Onyenwe anyị! Anyị kwere, debanye aha anyị n'etiti ndị akaebe. Onyenwe anyị, emetula anyị na ndị ajọ omume. Onyenwe anyị, nye anyị ihe ọma n'ụwa na n'eluigwe ma zọpụta anyị n'Ọkụ.",
                reference = "Quran: Surah Al-Ma'idah 5:83, Surah Al-A'raf 7:47, Surah Al-Baqarah 2:201."
            ),
            DuaEntity(
                id = 183,
                category = "Ruqyah",
                title = "Surah Al-Fatihah: The Ultimate Cure & Healer (Ash-Shifa)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَٰنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ",
                transliteration = "Bismillāhir-Rahmānir-Raheem. Al-Hamdu lillāhi Rabbil-'Ālameen. Ar-Rahmānir-Raheem. Māliki Yawmid-Deen. Iyyāka na'budu wa iyyāka nasta'een. Ihdinas-Sirātal-Mustaqeem. Sirātal-ladheena an'amta 'alayhim ghayril-maghdoobi 'alayhim wa lad-dālleen.",
                translation = "In the name of Allah, Most Gracious, Most Merciful. Praise be to Allah, the Cherisher and Sustainer of the worlds; Most Gracious, Most Merciful; Master of the Day of Judgment. You alone do we worship, and Your aid alone do we seek. Show us the straight way, the way of those on whom You have bestowed Your Grace, those whose (portion) is not wrath, and who go not astray.",
                translationHausa = "Da sunan Allah, Mai rahama, Mai jin kai. Dukkan godiya ta tabbata ga Allah, Ubangijin talikai. Mai rahama, Mai jin kai. Mai mulkin Ranar Sakamako. Kai kadai muke bautawa, kuma Kai kadai muke neman taimako a gare Ka. Ka shiryar da mu a kan hanya madaidaiciya. Hanyar wadanda Ka yi musu ni'ima, ba wadanda aka yi fushi da su ba, kuma ba bata-gari ba.",
                translationYoruba = "Ni orukọ Ọlọhun, Ajọkẹ-aiye, Asakẹ-ọrun. Gbogbo ọpẹ ni fun Ọlọhun, Oluwa gbogbo agbaye. Ajọkẹ-aiye, Asakẹ-ọrun. Ọba Ọjọ Idajọ. Iwọ nikan ni a n jọsin fun, Iwọ nikan ni a si n tọrọ iranlọwọ lọdọ Rẹ. Tọ wa si ọna titọ, Ọna awọn ti O ṣe ikẹ fun, kii ṣe ti awọn ti O binu si, ati awọn ti o ṣina.",
                translationIgbo = "N'aha Chineke, Onye Amamihe, Onye Ebere. Otuto diri Chineke, Onyenwe uwa niile; Onye Amamihe, Onye Ebere; Eze nke Ubọchi Ikpe. Gi ka anyi na-efe, Gi ka anyi na-ario enyemaka. Duzie anyi n'uzo ziri ezi, Uzo ndi I goro ngozi, bughi ndi I werere iwe, ma o bu ndi kpafuru akpafu.",
                reference = "The Prophet (ﷺ) confirmed to Abu Sa'id al-Khudri that Surah Al-Fatihah is the greatest Ruqyah against poisons, physical ailments, and spiritual affliction. Reference: Sahih al-Bukhari 2276, Sahih Muslim 2201."
            ),
            DuaEntity(
                id = 184,
                category = "Ruqyah",
                title = "Ayat Al-Kursi: The Shield Verse Against Devils & Jinn",
                arabic = "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ",
                transliteration = "Allāhu lā ilāha illā Huwal-Hayyul-Qayyoom. Lā ta'khudhuhu sinatuw-wa lā nawm. Lahu mā fis-samāwāti wa mā fil-ard. Man dhal-ladhee yashfa'u 'indahoo illā bi-idhnih. Ya'lamu mā bayna aydeehim wa mā khalfahum, wa lā yuheetoona bi-shay'im-min 'ilmihee illā bimā shā'. Wasi'a Kursiyyuhus-samāwāti wal-ard, wa lā ya'ooduhu hifzuhumā, wa Huwal-'Aliyyul-'Azeem.",
                translation = "Allah! There is no deity except Him, the Ever-Living, the Sustainer of all existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.",
                translationHausa = "Allah! Babu abin bautawa da gaskiya sai Shi, Rayayye, Mai tsayuwa da komai. Gyangyadi ba ya kama Shi, haka kuma barci. Shi kadai ne da abin da ke cikin sammai da abin da ke cikin kasa. Wane ne wanda zai iya yin ceto a wurinSa face da izininSa? Ya san abin da ke gaba da su da abin da ke bayansu, kuma ba su kewayewa da komai daga iliminSa sai abin da Ya so. KursiyyunSa ya yalwaci sammai da kasa, kuma kiyaye su ba ya gajiyar da Shi. Kuma Shi ne Madaukaki, Mai girma.",
                translationYoruba = "Ọlọhun! Ko si ọlọhun miiran bikoṣe Oun, Alaaye, Olutọju ohun gbogbo. Oorun ko le mu U, bẹẹ si ni oorun asunparọ. Ti Rẹ ni gbogbo ohun ti o wa ninu awọn ọrun ati ohun ti o wa ninu ilẹ. Ta ni ẹni ti o le ṣe alarina lọdọ Rẹ bikoṣe pẹlu aṣẹ Rẹ? O mọ ohun ti o wa niwaju wọn ati ohun ti o wa lẹhin wọn, wọn ko si le mọ nkankan ninu imọ Rẹ bikoṣe ohun ti O ba fẹ. Kursiyu Rẹ gba gbogbo awọn ọrun ati ilẹ, ko si rẹ Ẹ lati tọju awọn mejeeji. Oun si ni Oga-julo, Olobi-julo.",
                translationIgbo = "Chineke! Ọ dịghị chi ọzọ ma e wezụga Ya, Onye Dị Ndụ, Onye Na-akwado ihe niile. Ụra adịghị ama Ya ma ọ bụ ụra miri emi. Nke Ya bụ ihe niile dị n'eluigwe na ihe niile dị n'ụwa. Onye bụ onye nwere ike ịrịọ arịrịọ n'ihu Ya ma e wezụga site na ikike Ya? Ọ maara ihe dị n'ihu ha na ihe dị n'azụ ha, ha enweghịkwa ike ịghọta ihe ọ bụla n'ime amamihe Ya ma e wezụga ihe Ọ chọrọ. Ocheeze Ya gbara eluigwe na ụwa gburugburu, ichebe ha adịghị agwụ Ya ike. Ya bụ Onye Kacha Elu, Onye Kacha Ukwuu.",
                reference = "The Prophet (ﷺ) said: 'Whoever recites Ayat al-Kursi before going to sleep, Allah will appoint a guardian angel over him, and no devil will approach him until morning.' Reference: Sahih al-Bukhari 2311."
            ),
            DuaEntity(
                id = 185,
                category = "Ruqyah",
                title = "Last Two Verses of Surah Al-Baqarah (Night Protection)",
                arabic = "آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۝ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ",
                transliteration = "Amanar-Rasoolu bima onzila ilayhi mir-Rabbihee wal-mu'minoon. Kullun amana billahi wa mala'ikatihee wa kutubihee wa rusulih, la nufarriqu bayna ahadim-mir-rusulih. Wa qaloo sami'na wa ata'na ghufranaka Rabbana wa ilaykal-maseer. La yukallifullahu nafsan illa wus'aha, laha ma kasabat wa 'alayha maktasabat. Rabbana la tu'akhidhna in-naseena aw akhta'na, Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladheena min qablina, Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, Anta Mawlana fansurna 'alal-qawmil-kafirin.",
                translation = "The Messenger believes in what has been sent down to him from his Lord, and so do the believers. Each one believes in Allah, His Angels, His Books, and His Messengers. (They say): 'We make no distinction between one another of His Messengers.' And they say: 'We hear, and we obey. We seek Your forgiveness, our Lord, and to You is the return.' Allah burdens not a person beyond his scope. He gets reward for that (good) which he has earned, and he is punished for that (evil) which he has earned. 'Our Lord! Condemn us not if we forget or fall into error; our Lord! Lay not on us a burden like that which You did lay on those before us; our Lord! Put not on us a burden greater than we have strength to bear. Pardon us and grant us Forgiveness. Have mercy on us. You are our Protector, and give us victory over the disbelieving people.'",
                translationHausa = "Manzo ya yi imani da abin da aka saukar masa daga Ubangijinsa, da muminai ma. Kowannensu ya yi imani da Allah, da Mala'ikunSa, da LittattafanSa, da ManzanninSa: 'Ba ma bambancewa tsakanin kowa daga ManzanninSa.' Kuma suka ce: 'Mun ji kuma mun yi biyayya, muna neman gafararKa ya Ubangijinmu, kuma zuwa gare Ka makoma take.' Allah ba Ya dora wa wani rai abin da ba zai iya ba. Yana da ladan abin da ya aikata na alheri, kuma yana da alhakin abin da ya aikata na sharri. 'Ya Ubangijinmu! Kada Ka kama mu idan mun mance ko mun yi kuskure; ya Ubangijinmu! Kada Ka dora mana nauyi kamar yadda Ka dora a kan wadanda suka gabace mu; ya Ubangijinmu! Kada Ka dora mana abin da ba mu da karfin daukarsa. Ka yafe mana, Ka gafarta mana, Ka yi mana rahama. Kai ne Majibinmu, Ka taimake mu a kan kafirai.'",
                translationYoruba = "Ojiṣẹ gbagbọ ninu ohun ti a sọkalẹ fun un lati ọdọ Oluwa rẹ, bẹẹ si ni awọn onigbagbọ...",
                translationIgbo = "Onye Ozi kwere n'ihe e siri n'aka Onyenwe ya zite ya, ya na ndị kwere ekwe...",
                reference = "The Prophet (ﷺ) said: 'Whoever recites the last two verses of Surah Al-Baqarah at night, they will suffice him (protecting against every evil).' (Sahih al-Bukhari 5009, Sahih Muslim 807)."
            ),
            DuaEntity(
                id = 186,
                category = "Ruqyah",
                title = "Surah Al-Ikhlas: Absolute Tawheed (3 Times)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ",
                transliteration = "Bismillāhir-Rahmānir-Raheem. Qul Huwallāhu Ahad. Allāhus-Samad. Lam yalid wa lam yoolad. Wa lam yakul-lahoo kufuwan ahad.",
                translation = "In the name of Allah, Most Gracious, Most Merciful. Say: He is Allah, the One and Only; Allah, the Eternal, Absolute; He begets not, nor is He begotten; And there is none like unto Him.",
                translationHausa = "Da sunan Allah, Mai rahama, Mai jin kai. Ka ce: Shi ne Allah, Makaɗaici; Allah wanda ake nufi da buƙatu (ba Ya buƙatar kowa); Bai haifa ba kuma ba a haife Shi ba; Kuma babu wani da ya zama kishiya ko kwatankwacinSa.",
                translationYoruba = "Wi pe: Oun ni Ọlọhun, Ọkanṣoṣo; Ọlọhun, Asaku-ti; Ko bimọ, a ko si bi I; Ko si si ẹnikẹni ti o jọ Ọ.",
                translationIgbo = "Sị: Ọ bụ Chineke, Onye Nanị Ya; Chineke, Onye Ebighị Ebi; Ọ mụghị nwa, a mụghịkwa Ya; Ọ dịghịkwa onye dị ka Ya.",
                reference = "The Prophet (ﷺ) said: 'Recite Qul Huwallahu Ahad and the Mu'awwidhatayn (Al-Falaq and An-Nas) three times in the morning and evening, they will suffice you against everything.' Reference: Sunan Abi Dawud 5082, Sunan At-Tirmidhi 3575 (Hasan Sahih)."
            ),
            DuaEntity(
                id = 187,
                category = "Ruqyah",
                title = "Surah Al-Falaq: Refuge from Magic, Evil Eye & Darkness (3 Times)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ",
                transliteration = "Bismillāhir-Rahmānir-Raheem. Qul a'oodhu bi-Rabbil-falaq. Min sharri mā khalaq. Wa min sharri ghāsiqin idhā waqab. Wa min sharrin-naffāthāti fil-'uqad. Wa min sharri hāsidin idhā hasad.",
                translation = "Say: I seek refuge with the Lord of the Dawn, from the mischief of created things; from the mischief of Darkness as it overspreads; from the mischief of those who practise secret arts (blowing into knots / magic); and from the mischief of the envious one as he practises envy.",
                translationHausa = "Ka ce: Ina neman tsari da Ubangijin ketowar alfijir, daga sharrin abubuwan da Ya halitta, da sharrin dare idan ya yi duhu sosai, da sharrin masu tofi a cikin kulli (masu asiri da sihiri), da kuma sharrin mai hassada idan ya yi hassada.",
                translationYoruba = "Wi pe: Mo wa aabo pẹlu Oluwa owurọ, kuro ninu aburu ohun ti O da, ati kuro ninu aburu oru ti o ba ṣu, ati kuro ninu aburu awọn afẹfẹ sinu koko (awọn oṣó ati aje), ati kuro ninu aburu owú nigba ti o ba n ṣe owú.",
                translationIgbo = "Sị: Ana m achọ mgbaba n'aka Onyenwe nke chi ọbụbọ, pụọ n'ihe ọjọọ nke ihe O kere, pụọ n'ihe ọjọọ nke ọchịchịrị mgbe ọ bịara, pụọ n'ihe ọjọọ nke ndị na-agbọ n'eriri (ndị amoosu), na pụọ n'ihe ọjọọ nke onye anyaụfụ mgbe ọ na-enwe anyaụfụ.",
                reference = "Surah Al-Falaq (113:1-5) — Primary Ruqyah revealed to cure sorcery and evil eye."
            ),
            DuaEntity(
                id = 188,
                category = "Ruqyah",
                title = "Surah An-Nas: Refuge from Satanic Whispers & Hidden Evil (3 Times)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ",
                transliteration = "Bismillāhir-Rahmānir-Raheem. Qul a'oodhu bi-Rabbin-nās. Malikin-nās. Ilāhin-nās. Min sharril-waswāsil-khannās. Alladhee yuwaswisu fee sudoorin-nās. Minal-jinnati wan-nās.",
                translation = "Say: I seek refuge with the Lord and Cherisher of Mankind, the King (or Ruler) of Mankind, the God of Mankind, from the mischief of the Whisperer (of Evil), who withdraws (after his whisper), who whispers into the hearts of Mankind, among Jinn and among men.",
                translationHausa = "Ka ce: Ina neman tsari da Ubangijin mutane, Sarkin mutane, Abin bautar mutane, daga sharrin mai rada mai fakewa da gudu (shaidan), wanda yake sanya waswasi a cikin zukatan mutane, daga cikin aljannu da mutane.",
                translationYoruba = "Wi pe: Mo wa aabo pẹlu Oluwa awọn eniyan, Ọba awọn eniyan, Ọlọhun awọn eniyan, kuro ninu aburu afẹfẹ ti n fi nkan buburu sinu ọkan, ẹni ti n fi nkan buburu sinu igba-aya awọn eniyan, ninu awọn alijannu ati eniyan.",
                translationIgbo = "Sị: Ana m achọ mgbaba n'aka Onyenwe nke mmadụ, Eze nke mmadụ, Chineke nke mmadụ, pụọ n'ihe ọjọọ nke onye na-agba asịrị na-ezobe onwe ya, onye na-agba asịrị n'ime obi mmadụ, n'etiti ndị mmụọ ọjọọ na ndị mmadụ.",
                reference = "Surah An-Nas (114:1-6) — Sunan Abi Dawud 5082, Sahih al-Bukhari 5017."
            ),
            DuaEntity(
                id = 189,
                category = "Ruqyah",
                title = "Prophetic Ruqyah for Sickness, Pain & Healing",
                arabic = "اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَأْسَ، اشْفِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا",
                transliteration = "Allahumma Rabban-nas, adh-hibil-ba's, ishfi wa Antash-Shafi, la shifa'a illa shifa'uk, shifa'an la yughadiru saqama.",
                translation = "O Allah, Lord of mankind, remove the disease and bring about healing. You are the Healer; there is no healing except Your healing - a healing that leaves behind no ailment.",
                translationHausa = "Ya Allah, Ubangijin mutane! Ka tafiyar da cuta (da radadi), Ka warkar domin Kai ne Mai warkarwa; babu waraka sai warakarKa, waraka wadda ba ta barin wata cuta a baya.",
                translationYoruba = "Allāhu, Oluwa gbogbo eniyan, mu aisan yii kuro, ki O si wo san nitori Iwọ ni Olùwòsàn; ko si iwosan afi iwosan Rẹ, iwosan ti ko fi aisan kankan silẹ.",
                translationIgbo = "Chineke, Onyenwe mmadụ niile, wepụ ọrịa a ma mee ka ọ dị mma. Gị bụ Onye Ọgwụgwọ; ọ dịghị ọgwụgwọ ọzọ ma e wezụga ọgwụgwọ Gị - ọgwụgwọ nke na-adịghị ahapụ ọrịa ọ bụla n'azụ.",
                reference = "The Prophet (ﷺ) used to wipe with his right hand over the sick and recite this. Reference: Sahih al-Bukhari 5743, Sahih Muslim 2191."
            ),
