                translationIgbo = "N'aha Chineke ka m na-agwọ gị Ruqyah, pụọ n'ihe niile na-ewute gị, pụọ n'ihe ọjọọ nke mkpụrụ obi ọ bụla ma ọ bụ anya anyaụfụ. Ka Chineke gwọọ gị. N'aha Chineke ka m na-agwọ gị.",
