                title = "Ruqyah for Nullifying Sorcery & Magic (Surah Yunus)",
                arabic = "فَلَمَّا أَلْقَوْا قَالَ مُوسَىٰ مَا جِئْتُم بِهِ السِّحْرُ ۖ إِنَّ اللَّهَ سَيُبْطِلُهُ ۖ إِنَّ اللَّهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ",
                transliteration = "Falamma alqaw qala Moosa ma ji'tum bihis-sihr, innallaha sayubtiluh, innallaha la yuslihu 'amalal-mufsideen. Wa yuhiqqullahul-haqqa bi-kalimatihee wa law karihal-mujrimoon.",
                translation = "Then when they had cast down, Musa said: 'What you have brought is sorcery; Allah will surely make it of no effect. Verily, Allah does not set right the work of corruptors. And Allah will establish the truth by His Words, even if the criminals dislike it.'",
                translationHausa = "A lokacin da suka jefa (asirinsu), sai Musa ya ce: 'Abin da kuka zo da shi asiri ne (sihiri ne); lallai Allah zai bata shi! Hakika Allah ba Ya kyautata aikin masu barna. Kuma Allah zai tabbatar da gaskiya da kalmominSa ko da masu laifi sun ki.'",
                translationYoruba = "Nigba ti wọn sọ ọ kalẹ, Musa sọ pe: 'Ohun ti ẹ mu wa yii jẹ idan; dajudaju Ọlọhun yoo ba a jẹ. Dajudaju Ọlọhun kii ṣe atunṣe iṣẹ awọn onibajẹ.'",
                translationIgbo = "Mgbe ha tụsịrị ya, Musa sịrị: 'Ihe unu wetara bụ anwansi; n'ezie Chineke ga-eme ka ọ ghara ịdị irè. N'ezie Chineke anaghị edozi ọrụ nke ndị mmebi iwu.'",
                reference = "Surah Yunus (10:81-82) — Powerful Quranic verses used in Ruqyah for dismantling sorcery, witchcraft, and spells."
            ),
